/* 题库分片：文の文法1 形式判断（118 组 · 590 問 · 纯数据）
   每组按近义主题建组；干扰项须标注陷阱类型，正解须说明接续·呼应·语气三要素 */
window.BANK.push(
{"id":"b1-01","typeKey":"bun1","title":"模拟① 逆接・让步の型","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"体に悪いと知り＿＿、たばこがやめられない人は多い。","options":["たあげく","たものの","つつある","つつも"],"answer":3,"explain":["【接续不合】「〜あげく」接た形（知ったあげく），且语义为「…的结果（多带消极收场）」，与「知り」的持续状态不合。","【接续不合】「〜ものの」接た形，应为「知ったものの」；「知りたものの」这一接续本身不成立。","【近义混同】「〜つつある」表示「正在渐渐…」（变化进行中），「知りつつある」与后句「やめられない」的逆接逻辑无关。","正解。「〜つつも」接ます形（知りつつも），表示「明知…却」，书面语气与自责的语境契合，呼应后句「やめられない」的无奈。"]},
{"label":"近义辨析","q":"確かに難しい＿＿、合格できないわけではない。","options":["というものだ","わりには","とはいうものの","にひきかえ"],"answer":2,"explain":["【近义混同】「〜というものだ」用于断言「这才真是…」，承接「難しい」后无法引出「合格できないわけではない」的让步转折。","【近义混同】「〜わりには」表示「与…程度不相称」，须与实际成果对比（如「難しいわりにはよくできた」），此处逻辑不通。","正解。「〜とはいうものの」承接前句并加以部分推翻，即「话虽如此」，与「確かに…わけではない」的先让步再反驳结构契合。","【接续不合】「〜にひきかえ」用于两者对照（多为他人他物），不能用于同一事物内部的前后让步。"]},
{"label":"近义辨析","q":"彼は会社員＿＿、夜間大学で経営学を学んでいる。","options":["のあまり","のうえは","に際して","のかたわら"],"answer":3,"explain":["【近义混同】「〜のあまり」表示「因过分…而」，前接感情或状态名词，与「会社員」搭配不成逻辑。","【近义混同】「〜のうえは」表示「从…来看／作为…」，用于限定判断角度，此处讲的是兼做另一事，语义不合。","【接续不合】「〜に際して」直接接名词表示「当…之际」，用于某一行动进行的时点，「会社員に際して」不成立。","正解。「〜かたわら」表示「以某身份为主，同时兼做另一事」，「社会員のかたわら、夜間大学で学ぶ」正是并立本业的典型用法。"]},
{"label":"呼应制约","q":"何を＿＿、彼の決心は変わらないだろう。","options":["言うにつけ","言いたがって","言わんばかり","言われようが"],"answer":3,"explain":["【呼应冲突】「〜につけ」须以「何かにつけ／その都度」的形式表示「每逢…就」，不能与「何を」搭配。","【时态肯否错位】「〜たがって」表示第三者的愿望「想要…」，与「何を」搭配后无法构成让步条件。","【近义混同】「〜んばかり」表示「几乎要…的样子」，描述眼前的情态，不能引出「決心は変わらない」的让步结论。","正解。「〜(よ)うが」接意志形（言われようが），表示「无论…都」，与后句「変わらないだろう」的全面否定呼应。"]},
{"label":"近义辨析","q":"有名大学を出た＿＿、彼の仕事ぶりは残念だ。","options":["からには","ところに","に先立って","わりには"],"answer":3,"explain":["【近义混同】「〜からには」表示「既然…就（必须）」，后句应为决心或义务，与「残念だ」的评价不合。","【接续不合】「〜ところに」表示「正当…的时候」，接动词基本形或た形表示时点，此处无时点语义。","【近义混同】「〜に先立って」表示「在…之前（先做某事）」，与后句的落差评价无关。","正解。「〜わりには」表示「与…程度相比不相称」，即「虽说毕业于名校，工作表现却令人遗憾」，前项期待与后项现实的落差正是其典型语境。"]},
]},
{"id":"b1-02","typeKey":"bun1","title":"模拟② 義務・被迫の型","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"大雨のため、登山計画の変更を＿＿。","options":["契機とした","禁じ得なかった","よそにしていた","余儀なくされた"],"answer":3,"explain":["【近义混同】「〜を契機に」表示「以…为契机（发生转变）」，此处是被迫应对而非主动转变。","【近义混同】「〜を禁じ得ない」用于「泪・怒り・驚き」等情感「禁不住…」，不能与「計画の変更」这类行为搭配。","【近义混同】「〜をよそに」表示「无视…、不顾…」，与句中「因大雨而不得不改」的被动语境相反。","正解。「〜を余儀なくされる」表示「被迫做出…」，主语因外部情况而不得不改变计划，与「大雨のため」的客观原因契合。"]},
{"label":"近义辨析","q":"彼の嘘を知って、怒りを＿＿。","options":["余儀なくされた","償いきれなかった","ものともしなかった","禁じ得なかった"],"answer":3,"explain":["【近义混同】「〜を余儀なくされる」前接行为名词（変更・撤退），表示被迫做某事，不能与情感名词「怒り」搭配。","【近义混同】「〜を償いきれない」意为「无法完全弥补」，补偿的对象应是过错或损失，不能是「怒り」。","【近义混同】「〜をものともしない」表示「不把…放在眼里」，主语以强者姿态克服困难，此处语义正好相反。","正解。「〜を禁じ得ない」接「怒り・涙」等情感名词，表示「禁不住…」，与「嘘を知って」的情感触发语境契合。"]},
{"label":"接续制约","q":"毎日の練習＿＿、上達はない。","options":["もとより","そもそも","抜きには","も同然だ"],"answer":2,"explain":["【近义混同】「〜もとより」表示「不言而喻／本来就」，为副词性用法，无法引出「上達はない」的否定条件。","【近义混同】「そもそも」为副词「原本、说到底」，不能连接名词构成条件。","正解。「〜抜きには＋否定」表示「如果没有…就没有…」，「毎日の練習抜きには、上達はない」是典型的必要条件句。","【近义混同】「〜も同然だ」表示「和…一样」，与「上達はない」的否定条件逻辑不合。"]},
{"label":"近义辨析","q":"友人の結婚式なので、欠席は＿＿。","options":["まぬがれまい","したくてたまらぬ","許されんばかりだ","するわけにはいかない"],"answer":3,"explain":["【近义混同】「〜まぬがれる」表示「免于（灾难等不好的事）」，「欠席を免れまい」与参加婚礼的道义语境不合。","【时态肯否错位】「〜たくてたまらない」表示「…得不得了」的强烈愿望，与「欠席は」搭配后语义自相矛盾。","【呼应冲突】「〜んばかりだ」表示「几乎要…的样子」，描述情态，不能用于「欠席」这一意志行为的判断。","正解。「〜わけにはいかない」表示「出于情理不能…」，「欠席はするわけにはいかない」正是好友婚礼这种道义义务的表达。"]},
{"label":"近义辨析","q":"医者に止められても、この仕事は続け＿＿。","options":["ないではいられない","ずにはおかない","ざるを得ない","かねる"],"answer":2,"explain":["【近义混同】「〜ないではいられない」表示感情自发、忍不住的冲动，而本句是医嘱这一外部权威造成的「不得不」，语气不合。","【近义混同】「〜ずにはおかない」多用于事态必然导致某结果或强意志的表态，与迫于医嘱的无奈不合。","正解。「〜ざるを得ない」（する→せざる）表示迫于外部情况而不得不做，与「医者に止められても」的让步条件及被动语境契合。","【近义混同】「〜かねる」表示「难以…（婉拒）」，「続けかねる」意为难以继续，与句意正好相反。"]},
]},
{"id":"b1-03","typeKey":"bun1","title":"模拟③ 変化・傾向の型","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"接续制约","q":"この都市の人口は、この十年減る＿＿だ。","options":["次第","がち","気味","一方"],"answer":3,"explain":["【近义混同】「〜次第だ」表示「全凭…／情况如此」，与「減る」搭配后无法表示变化趋势。","【接续不合】「〜がちだ」接ます形 stem（減りがち），「減るがちだ」这一接续不成立。","【接续不合】「〜気味だ」接ます形 stem（減り気味），表示「略带…倾向」，接辞书形「減る気味」不成立。","正解。「動辞書形＋一方だ」表示「不断地朝一个方向变化」，「減る一方だ」正是持续减少的固定表达。"]},
{"label":"接续制约","q":"徹夜仕事が続いて、彼は最近疲れ＿＿の顔をしている。","options":["つつ","ながら","がち","気味"],"answer":3,"explain":["【接续不合】「〜つつある」须接ます形＋つつある（疲れつつある表示「正在渐渐疲惫」），作定语修饰「顔」不通。","【接续不合】「〜ながらも」接ます形或名词，「疲れながらの顔」虽语法可行，但语义为「一边…一边」，与描写状态不符。","【近义混同】「〜がちだ」表示「经常、动辄」（如遅れがち），强调频度而非当下状态，与「顔をしている」的即时描写不合。","正解。「〜気味」接ます形 stem（疲れ気味），表示「稍带…状态」，「疲れ気味の顔」为惯用搭配。"]},
{"label":"近义辨析","q":"彼の巧妙な話術には、だまされ＿＿。","options":["ようがない","がたい","かねる","かねない"],"answer":3,"explain":["【近义混同】「〜ようがない」表示「没有办法…」，「だまされようがない」意为「无从被骗」，与句意相反。","【近义混同】「〜がたい」表示「难以…」，「だまされがたい」意为「不易被骗」，与句意正好相反。","【近义混同】「〜かねる」表示「难以做到（婉拒）」，主语多为说话人的意愿行为，「だまされかねる」不成逻辑。","正解。「〜かねない」表示「有…的危险、很可能（发生坏事）」，「だまされかねない」即「很可能上当」，与「巧妙な話術」的危险语境契合。"]},
{"label":"文末表现","q":"その提案には無理がありすぎて、受け入れ＿＿。","options":["かけた","かねない","がちだ","かねる"],"answer":3,"explain":["【近义混同】「〜かける」表示「开始…但未完成」，「受けかけた」意为「接受到一半」，与「无法接受」的婉拒语义不合。","【近义混同】「〜かねない」表示「很可能（发生坏事）」，「受け入れかねない」会被读成「可能接受」，与「無理がありすぎて」相反。","【接续制约】「〜がちだ」表示频度倾向（动词ます形），「受け入れがちだ」意为「倾向于接受」，与句意相反。","正解。「〜かねる」接ます形，表示「难以…（婉转拒绝）」，「受け入れかねる」是商务场景表达「碍难接受」的固定说法。"]},
{"label":"接续制约","q":"子育て支援の需要は高まり＿＿ある。","options":["つつも","気味","がち","つつ"],"answer":3,"explain":["【近义混同】「〜つつも」为逆接（虽然…却），「高まりつつもある」不成立，语义也与上升倾向无关。","【接续不合】「〜気味」接ます形 stem 后直接结句或修饰名词，「高まり気味ある」不成立。","【接续不合】「〜がちだ」接ます形 stem，「高まりがちある」不成立；且「がち」表频度倾向，与持续上升的变化不同。","正解。「動ます形＋つつある」表示「正在逐渐…」，「高まりつつある」描述需求持续上升的变化过程。"]},
]},
{"id":"b1-04","typeKey":"bun1","title":"模拟④ 様態・兆候の型","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"接续制约","q":"彼は何か言いた＿＿に口を開いた。","options":["たいそう","気味","がち","げ"],"answer":3,"explain":["【接续不合】「〜そうだ」的様態用法接形容词/动词 stem（言いたそう），但「言い＋たいそう」这一接续不成立，様態「そう」不能接「たい」。","【接续不合】「〜気味」接名词或动词ます形 stem，「言い気味」不成立；且「気味」表状态倾向，非神情描写。","【接续不合】「〜がち」接名词或动词ます形 stem（言いがち＝常说），表示频度倾向，与「口を開いた」的一次性动作不合。","正解。「〜げ」接形容词/动词连用形，表示「…的神情」，「言いたげに口を開いた」即「一副想说什么的样子开口」。"]},
{"label":"近义辨析","q":"彼は最近、遅刻＿＿の傾向がある。","options":["きわまりない","気味","げ","がち"],"answer":3,"explain":["【接续不合】「〜きわまりない」接な形容词词干或名词，表示「极其…（贬义评价）」，「遅刻きわまりないの傾向」不成立。","【近义混同】「〜気味」表示「程度略高一点的状态」（如風邪気味），描述当下状态而非频度，与「傾向がある」的频度语义不合。","【接续不合】「〜げ」接形容词或状态词表神情，「遅刻げ」不成立。","正解。「〜がち」表示「经常、动辄」的频度倾向，「遅刻がちの傾向」为惯用搭配，与「傾向がある」呼应。"]},
{"label":"近义辨析","q":"彼は満足＿＿にうなずいた。","options":["そうで","気味","がち","げ"],"answer":3,"explain":["【接续不合】「〜そうだ」的様態接词干后作连用修饰须为「満足そうに」，「満足そうでに」不成立。","【接续制约】「〜気味」多接不理想的状态（疲れ・不足気味），「満足気味」搭配生硬且非神情描写。","【接续制约】「〜がち」表频度倾向，不能描述一次点头时的神情。","正解。「〜げ」接な形容词/形容词词干，表示「…的神情」，「満足げにうなずいた」即「一脸满足地点头」。"]},
{"label":"接续制约","q":"長雨で、土壁が崩れ＿＿いる。","options":["気味に","がちに","かけて","げに"],"answer":2,"explain":["【接续不合】「〜気味」表状态倾向，须以「崩れ気味だ／の」的形式结句或修饰名词，无法与「ている」直接连用。","【接续不合】「〜がち」表频度倾向，同样无法与「ている」连用，且「崩れがち」意为「常常塌」，与一次性过程描写不合。","正解。「〜かける」接ます形，表示「开始…但未完成」，「崩れかけている」即「正在开始崩塌」，与长雨渐损的过程契合。","【接续不合】「〜げ」接状态词表神情，「崩れげ」不成立。"]},
{"label":"近义辨析","q":"仕事の合間、彼は休み＿＿の生活が続いていた。","options":["げ","気味","がち","得ない"],"answer":2,"explain":["【接续不合】「〜げ」表神情，「休みげの生活」不成立。","【近义混同】「〜気味」表示「程度略高」（休み気味＝稍微偏多休息），强调当前状态而非长期频度，与「生活が続いていた」不合。","正解。「〜がち」接ます形 stem，表示「经常处于某状态」，「休みがちの生活」即「动不动就休息的生活」，频度倾向与「続いていた」契合。","【接续不合】「〜得ない」接ます形表示「不可能…」（あり得ない），「休み得ない」与句意相反且接续生硬。"]},
]},
{"id":"b1-05","typeKey":"bun1","title":"模拟⑤ 経由・媒体の型","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"代理商＿＿、その商品は海外にも販路を広げた。","options":["をはじめ","をめぐって","を通じて","にわたって"],"answer":2,"explain":["【近义混同】「〜をはじめ」表示「以…为首（列举代表）」，代理商并非「一系列渠道之首」，语义不合。","【近义混同】「〜をめぐって」表示「围绕…（展开争论）」，后接讨论・対立类动词，与「販路を広げた」不合。","正解。「〜を通じて」表示「经由…（中介）」，「代理商を通じて」即「通过代理商」，经手人与商品流通的关系正是其典型用法。","【接续不合】「〜にわたって」接范围名词表示「持续、波及的范围」，不接中介者名词。"]},
{"label":"近义辨析","q":"彼は英語は＿＿、仏語にも精通している。","options":["に沿って","をもとに","はもとより","に反して"],"answer":2,"explain":["【接续不合】「〜に沿って」接名词表示「遵循、沿着」，此处需要的是列举递进，语义不合。","【近义混同】「〜をもとに」表示「以…为素材」，与「英语之外还精通法语」的递进列举无关。","正解。「〜はもとより」表示「…自不必说，（更）…」，「英語はもとより、仏語にも精通している」正是「A 自不必说连 B 也」的递进。","【近义混同】「〜に反して」表示「与…相反」，此处无对照关系。"]},
{"label":"近义辨析","q":"環境問題を＿＿、両者の見解は真っ向から対立した。","options":["はじめ","通じて","めぐって","に沿って"],"answer":2,"explain":["【接续不合】「〜をはじめ」表示「以…为首列举」，此处不是列举关系。","【近义混同】「〜を通じて」表示「经由某媒介完成」，但「見解が対立」的对立主体是两方人，环境问题是对立的话题而非媒介。","正解。「〜をめぐって」表示「围绕…（产生分歧、展开争论）」，「環境問題をめぐって、見解が対立した」是其最典型搭配。","【接续不合】「〜に沿って」表示「遵循」，与环境问题的对立话题无关。"]},
{"label":"近义辨析","q":"関係各省はもとより＿＿、幅広い分野から意見を聞いた。","options":["に沿って","をめぐって","をはじめ","に反して"],"answer":2,"explain":["【接续不合】「〜に沿って」表示遵循，与听取意见的对象列举无关。","【近义混同】「〜をめぐって」表示围绕某话题展开，不能与「意見を聞いた」的广泛听取关系衔接。","正解。「〜をはじめ」表示「以…为代表、以及…」，与「はもとより」呼应构成递进列举，广泛听取意见正是其语境。","【近义混同】「〜に反して」表示相反，此处无对照。"]},
{"label":"近义辨析","q":"会議は三日間＿＿行われた。","options":["にわたって","をはじめ","をもとに","を契機に"],"answer":0,"explain":["正解。「〜にわたって」接期间・范围名词，表示「持续…、跨越…」，「三日間にわたって行われた」为标准用法。","【接续不合】「〜をはじめ」表示列举之首，不能与期间名词搭配表示持续。","【近义混同】「〜をもとに」表示「以…为素材」，与会议持续进行的描述无关。","【近义混同】「〜を契機に」表示「以…为转机」，与会议的持续时间无关。"]},
]},
{"id":"b1-06","typeKey":"bun1","title":"模拟⑥ 逆接条件の型","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"たとえ＿＿、あきらめない。","options":["失敗するかのように","失敗しつつ","失敗したとしても","失敗したきり"],"answer":2,"explain":["【呼应冲突】「〜かのように」表示「仿佛…一样」，与「たとえ」的让步呼应不成立。","【接续不合】「〜つつも」逆接须接ます形（失敗しつつも），且表示同时进行的逆接，与「たとえ」不呼应。","正解。「たとえ〜たとしても」是标准的让步条件呼应，「たとえ失敗したとしても、あきらめない」即「即便失败也不放弃」。","【近义混同】「〜たきり」表示「…之后再无（下文）」，「失敗したきり、あきらめない」语义断裂。"]},
{"label":"近义辨析","q":"いまから＿＿、間に合うまい。","options":["出かけたところで","出かけるが早いか","出かけないことには","出かけるがたい"],"answer":0,"explain":["正解。「〜たところで」接た形，表示「即使…（也不会有好结果）」，与文末消极推量「まい」呼应：「现在即使出门也赶不上吧」。","【近义混同】「〜が早いか」表示「刚…就…」，描述紧接着发生的动作，与「間に合うまい」的推量不合。","【时态肯否错位】「〜ないことには」后须接否定或消极评价，但语义为「不…的话就（不能）…」，此处逻辑正好相反。","【接续不合】「〜がたい」接ます形表示「难以…」，「出かけるがたい」不成立。"]},
{"label":"呼应制约","q":"何度＿＿、彼は認めないだろう。","options":["説得しようと","説得したが最後","説得するかたわら","説得しつつ"],"answer":0,"explain":["正解。「〜(よ)うと」接意志形（説得しようと），与「何度」呼应表示「无论怎么劝都不会…」，与「認めないだろう」的全面否定契合。","【近义混同】「〜たが最後」表示「一旦…就（必然变糟）」，与「何度」的反复语义冲突。","【近义混同】「〜かたわら」表示身份并立，「説得するかたわら」语义不成立。","【接续不合】「〜つつも」接ます形（説得しつつも），且语义为逆接让步，不能与「何度」构成全面让步条件。"]},
{"label":"近义辨析","q":"賛否は＿＿、計画を実行に移そう。","options":["はもとより","に先立って","はともかく","にひきかえ"],"answer":2,"explain":["【近义混同】「〜はもとより」表示「…自不必说（更…）」，用于递进列举，与「搁置争议先行动手」的语义不合。","【近义混同】「〜に先立って」表示「在…之前先…」，与搁置评价无关。","正解。「〜はともかく」表示「…暂且不论」，「賛否はともかく、実行に移そう」即「赞成反对姑且不论，先干起来」。","【接续不合】「〜にひきかえ」用于他人他物的鲜明对照，不能用于搁置同一计划的争议。"]},
{"label":"接续制约","q":"詳しくは＿＿、概要だけでも説明しよう。","options":["説明しようが","説明しがたい","説明したとたん","説明しないまでも"],"answer":3,"explain":["【时态肯否错位】「〜(よ)うが」接意志形表示全面让步，「説明しようが、説明しよう」自身重复且语义不通。","【近义混同】「〜がたい」表示「难以…」，「詳しくは説明しがたい」后无法接「概要だけでも」的让步推进。","【近义混同】「〜たとたん」表示「刚…就（突发）」，与让步退让的语境不合。","正解。「〜ないまでも」接ない形，表示「即便不到…程度，（至少）…」，「詳しくは説明しないまでも、概要だけでも」是标准的「退一步」结构。"]},
]},
{"id":"b1-07","typeKey":"bun1","title":"模拟⑦ 契約・時点の型","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"新学期を＿＿、学習計画を立てた。","options":["にあたって","に沿って","に応じて","にひきかえ"],"answer":0,"explain":["正解。「〜にあたって」表示「值此（重要行动开始）之际」，「新学期にあたって、計画を立てた」即「值新学期之际制定计划」。","【近义混同】「〜に沿って」表示遵循（方针・路线），与制定计划的时点无关。","【近义混同】「〜に応じて」表示「根据…相应变化」，与计划制定的时点不合。","【接续不合】「〜にひきかえ」表示他人他物的对照，此处无对照对象。"]},
{"label":"近义辨析","q":"会長の退任を＿＿、記念式典が開かれた。","options":["に際して","につれて","に応じて","に限って"],"answer":0,"explain":["正解。「〜に際して」表示「当…之际」，「退任に際して式典が開かれた」即「在会长退任之际举行了典礼」。","【近义混同】「〜につれて」表示「随着…（自然变化）」，式典并非随退任自然发生的变化。","【近义混同】「〜に応じて」表示「根据…相应调整」，与举行式典的时点无关。","【近义混同】「〜に限って」表示「唯独…偏偏」，与举行式典的时点无关。"]},
{"label":"近义辨析","q":"合併を＿＿、社名が変わった。","options":["契機に","にあたって","に沿って","をよそに"],"answer":0,"explain":["正解。「〜を契機に」表示「以…为转机（发生重大转变）」，「合併を契機に社名が変わった」是企业重大变更的标准表述。","【近义混同】「〜にあたって」表示主体「在行动之际」的意志，社名变更并非在合并「之际」有意为之的动作。","【接续不合】「〜に沿って」表示遵循，「合併に沿って」不成立。","【近义混同】「〜をよそに」表示「不顾…」，与社名随合并而变更的因果关系相反。"]},
{"label":"呼应制约","q":"彼はニュースを見る＿＿、あの停電の夜を思い出した。","options":["につけ","に際して","を契機に","にひきかえ"],"answer":0,"explain":["正解。「動辞書形＋につけ」表示「每逢…就（不由得）」，「見るにつけ、思い出した」与「何かにつけ」同型，情感的自然涌起正是其用法。","【接续不合】「〜に際して」表示「当…之际」的行动时点，看新闻并非某一正式行动。","【近义混同】「〜を契機に」表示重大转机，「想起往事」不是由看新闻引发的转变。","【接续不合】「〜にひきかえ」表示对照，此处无对照对象。"]},
{"label":"近义辨析","q":"第一次オイルショックを＿＿、省エネ技術が急速に発達した。","options":["をきっかけに","をめぐって","をはじめ","にわたって"],"answer":0,"explain":["正解。「〜をきっかけに」表示「以…为契机（引发后续变化）」，石油危机引发节能技术发展正是转机关系。","【近义混同】「〜をめぐって」表示围绕话题展开争论，与技术的发展无关。","【接续不合】「〜をはじめ」表示列举之首，与单一事件作转机不合。","【接续不合】「〜にわたって」表示范围持续，不接事件名词作转机。"]},
]},
{"id":"b1-08","typeKey":"bun1","title":"模拟⑧ 敬語の型","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"敬語","q":"部長はもう帰宅＿＿。","options":["なさった","もうされた","おっしゃった","拝借した"],"answer":0,"explain":["正解。「〜なさる」是「する」的尊敬语，「帰宅なさった」表示对部长行为的尊敬。","【接续不合】「〜(ら)れる」的尊敬形不能直接接「帰宅もう」，「帰宅もうされた」不成立。","【近义混同】「おっしゃる」是「言う」的尊敬语，「帰宅おっしゃった」将两个动词错误拼接。","【近义混同】「拝借する」是「借」的谦让语，方向与尊敬语境相反。"]},
{"label":"敬語","q":"先生は先ほど校門の前に＿＿。","options":["おいでになった","おっしゃった","伺った","拝見した"],"answer":0,"explain":["正解。「おいでになる」是「いる・行く・来る」的尊敬语，「校門の前においでになった」即「（老师）来到了校门前」。","【近义混同】「おっしゃる」是「言う」的尊敬语，与「来到校门前」的动作不符。","【近义混同】「伺う」是「尋ねる・行く」的谦让语，用于己方动作，不能用于老师。","【近义混同】「拝見する」是「見る」的谦让语，方向相反。"]},
{"label":"敬語","q":"資料は後ほど＿＿。","options":["お送りいたします","お送りになられます","お送りください","お送り願えます"],"answer":0,"explain":["正解。「お〜いたす」是谦让语大形式，「（私が）お送りいたします」表示说话人郑重承诺稍后发送。","【敬語误用】「お〜になる」是尊敬语，「なられます」再叠「れる」构成双重敬语，且方向（对方送）与承诺发送的语境不符。","【敬語误用】「お送りください」是请对方发送，与「我方稍后发送」的方向相反。","【敬語误用】「お送り願えます」不成立，「願える」不能如此接续使用。"]},
{"label":"敬語","q":"課長が先ほどこの報告書を＿＿。","options":["ご覧になりました","拝見しました","お目にかけました","伺いました"],"answer":0,"explain":["正解。「ご覧になる」是「見る」的尊敬语，课长是上级（他人动作），用尊敬语「ご覧になりました」正确。","【敬語误用】「拝見する」是谦让语（我看），用于课长的动作方向错误。","【敬語误用】「お目にかける」是谦让语（给对方看），主语应为说话人。","【近义混同】「伺う」是「问／拜访」的谦让语，与「看报告」的动作不符。"]},
{"label":"敬語","q":"社長、明日の会議の時間を＿＿か。","options":["ご存知でしょうか","存じておりますか","ご覧になっておりますか","おっしゃっていますか"],"answer":0,"explain":["正解。「ご存知だ」是「知っている」的尊敬语，「ご存知でしょうか」是礼貌地询问上级是否知晓。","【敬語误用】「存じております」是谦让语（我知道），用于上级「知道」的方向错误。","【近义混同】「ご覧になる」是「看」的尊敬语，与询问「是否知道」不合。","【近义混同】「おっしゃる」是「说」的尊敬语，与询问「是否知道」不合。"]},
]},
{"id":"b1-09","typeKey":"bun1","title":"模拟⑨ 感情・程度の型","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"合格の通知を受け取り、喜び＿＿で跳び上がった。","options":["の極み","極まりない","に堪えない","てやまない"],"answer":0,"explain":["正解。「〜の極み」接情感名词，表示「…之极」，「喜びの極みで跳び上がった」即「欣喜若狂地跳了起来」。","【接续不合】「〜きわまりない」接な形容词词干（失礼極まりない），表属性评价，「喜びきわまりないで」不成立。","【近义混同】「〜に堪えない」多接「悲しみ・痛み」等消极情感，「喜びに堪えないで」接续与语义皆不合。","【接续不合】「〜てやまない」接动词て形（祈ってやまない），表示心愿持续，「喜びてやまないで」不成立。"]},
{"label":"近义辨析","q":"恩師の死を聞き、悲しみ＿＿。","options":["に堪えない","てやまない","きわまりない","を余儀なくされた"],"answer":0,"explain":["正解。「〜に堪えない」接「悲しみ・痛み」等消极情感名词，表示「不堪…」，「悲しみに堪えない」为标准搭配。","【接续不合】「〜てやまない」接「祈る・願う」等愿望动词的て形，「悲しみてやまない」不成立。","【接续不合】「〜きわまりない」接な形容词词干表属性评价，「悲しみきわまりない」不成立。","【近义混同】「〜を余儀なくされる」前接行为名词表被迫，「悲しみを余儀なくされた」搭配不当。"]},
{"label":"接续制约","q":"惨状を目の当たりにして、憤りを＿＿。","options":["禁じ得ない","余儀なくされた","堪えない","てやまない"],"answer":0,"explain":["正解。「〜を禁じ得ない」接「怒り・憤り・涙」等情感名词＋を，表示「禁不住…」，「憤りを禁じ得ない」为惯用搭配。","【近义混同】「〜を余儀なくされる」表被迫做某行为，不能搭配情感名词「憤り」。","【接续不合】「〜に堪えない」接情感名词＋に，「憤りを堪えない」格助词不合。","【接续不合】「〜てやまない」接动词て形，「憤りてやまない」不成立。"]},
{"label":"近义辨析","q":"先生のご健康を＿＿。","options":["祈ってやまない","祈りかねない","祈らんばかりに","祈るまでのことだ"],"answer":0,"explain":["正解。「〜てやまない」接「祈る・願う・尊敬する」等动词て形，表示「衷心…不已」，「ご健康を祈ってやまない」是书信・贺词的惯用表达。","【近义混同】「〜かねない」表示「很可能发生（坏事）」，与祝愿语境相反。","【近义混同】「〜んばかりに」表示「几乎要…的样子」，描述情态动作，不能用于持续的心愿。","【近义混同】「〜までのことだ」表示「大不了…罢了」，与郑重祝愿的语气不合。"]},
{"label":"文末表现","q":"仕事が立て込んでいて、旅行に行く＿＿。","options":["どころではない","ものではない","といったらない","というものだ"],"answer":0,"explain":["正解。「〜どころではない」表示「哪里谈得上…」，「忙しくて旅行どころではない」即「忙得哪有工夫旅行」。","【近义混同】「〜ものではない」表示「不该…（说教）」，与「忙しくて」的原因语境不合。","【近义混同】「〜といったらない」表示「…得难以形容（多用于好的感慨）」，与无法成行的语义相反。","【近义混同】「〜というものだ」表示「这才真是…」的断言，此处无断言对象。"]},
]},
{"id":"b1-10","typeKey":"bun1","title":"模拟⑩ 対比・限界の型","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"兄の活発さ＿＿、弟はおとなしい。","options":["にひきかえ","のかたわら","のあまり","に先立って"],"answer":0,"explain":["正解。「〜にひきかえ」表示「与…正相反」，前接名词，用于兄弟性格的鲜明对照。","【接续制约】「〜かたわら」表示身份并立，「兄の活発さのかたわら」不成立。","【接续制约】「〜のあまり」前接感情・状态名词表「因过分而」，「活発さのあまり」与后句对照语义不合。","【近义混同】「〜に先立って」表示「在…之前」，与对照关系无关。"]},
{"label":"近义辨析","q":"彼は教師＿＿、詩人としても知られている。","options":["のかたわら","にひきかえ","に応じて","わりには"],"answer":0,"explain":["正解。「〜かたわら」表示「在从事本职的同时兼做…」，「教師のかたわら、詩人としても知られる」正合双身份并立。","【接续不合】「〜にひきかえ」表示对照，此处是并立而非对照。","【近义混同】「〜に応じて」表示「根据…相应变化」，与并立身份无关。","【近义混同】「〜わりには」表示「与…不相称」，「教師わりには」后应接对教师而言出乎意料的评价，语义不合。"]},
{"label":"近义辨析","q":"輸出が伸びた＿＿、内需は伸び悩んだ。","options":["とあれば","ならでは","一方で","ともなると"],"answer":2,"explain":["【近义混同】「〜とあれば」表示「如果是…的话就…」，与对照关系无关。","【接续不合】「〜ならでは」接名词表示「独有的」，「伸びたならでは」不成立。","正解。「〜一方で」表示「一方面…另一方面…」，用于两个领域相反动向的对照。","【近义混同】「〜ともなると」表示「一到…（就自然…）」，与两者的对照无关。"]},
{"label":"文末表现","q":"有名大学を出たからといって、必ずしも優秀＿＿。","options":["とは限らない","限りではない","し得ない","しがたい"],"answer":0,"explain":["正解。「〜とは限らない」接「必ずしも」呼应，表示「未必…」，「必ずしも優秀とは限らない」为标准的部分否定。","【接续不合】「〜限りではない」不成立，正确形式应为「とは限らない」或「限らない」。","【接续不合】「〜得ない」接动词ます形（成り得ない），不能接な形容词「優秀」。","【接续不合】「〜がたい」接动词ます形表示「难以…」，不能接「優秀」。"]},
{"label":"近义辨析","q":"散歩＿＿、買い物をしてきた。","options":["がてら","あげく","次第","ぬきで"],"answer":0,"explain":["正解。「〜がてら」接ます形 stem，表示「顺便、捎带」，「散歩がてら買い物」即「借着散步顺便购物」。","【近义混同】「〜あげく」接た形表示「…的结果（多为消极）」，与顺便购物的语境不合。","【近义混同】「〜次第」接名词表示「一…立刻／全凭」，「散歩次第」不成立。","【近义混同】「〜抜きで」表示「省去…、去掉…」，「散歩抜きで買い物」语义与句意相反。"]},
]},
{"id":"b1-11","typeKey":"bun1","title":"模拟⑪ 限定・範囲の型","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"この味は地元＿＿ものだ。","options":["にすぎない","を問わず","をおいて","ならではの"],"answer":3,"explain":["【近义混同】「〜にすぎない」表示「不过是…（贬低）」，与夸赞当地风味的语境相反。","【接续不合】「〜を問わず」接「国・年齢」等无差别的范围名词，「地元を問わず」与「独有的」语义相反。","【接续不合】「〜をおいて」接人名词用于「除了…（别无）」的强调，「地元をおいてのものだ」不成立。","正解。「〜ならではの」接名词，表示「唯有…才有的」，「地元ならではの味」即「本地独有的味道」。"]},
{"label":"近义辨析","q":"君＿＿、この任務を任せられる人はいない。","options":["をおいて","ならでは","に限って","に沿って"],"answer":0,"explain":["正解。「〜をおいて」接人名词＋否定，表示「除了…别无…」，「君をおいて…いない」是「非你莫属」的强调。","【接续不合】「〜ならでは」须以「〜ならではの＋名词」或「〜ならでは（の）＋ない」的形式出现，「君ならでは…いない」不成立。","【近义混同】「〜に限って」表示「唯独…偏偏（用于消极意外）」，与「非你莫属」的信赖语境相反。","【接续不合】「〜に沿って」表示遵循，与任务的唯一性无关。"]},
{"label":"近义辨析","q":"経験＿＿、人は成長できない。","options":["なくしては","ないまでも","も同然で","まみれで"],"answer":0,"explain":["正解。「〜なくしては」接名词，表示「如果没有…（就）」，与否定谓语呼应：「没有经验，人无法成长」。","【近义混同】「〜ないまでも」接动词ない形，表示「即便不到…程度（至少）」，与「経験」的名词接续不合。","【近义混同】「〜も同然だ」表示「和…一样」，「経験も同然で」后无法接「成長できない」的必要条件。","【近义混同】「〜まみれ」接名词表示「沾满（血・汗・泥）」，与抽象的「経験」搭配不当。"]},
{"label":"近义辨析","q":"土曜と日曜＿＿、図書館は毎日開館している。","options":["に限り","にわたって","をもって","を除き"],"answer":3,"explain":["【近义混同】「〜に限り」表示「仅限于…（给优惠等）」，「土日に限り開館」与「毎日開館」矛盾。","【接续不合】「〜にわたって」表示范围持续，「土日にわたって」与「毎日」的时间逻辑冲突。","【近义混同】「〜をもって」表示「以…（期限・手段）」，「土日をもって開館」语义不通。","正解。「〜を除き」表示「除…之外」，「土日を除き、毎日開館」即「除周末外每日开放」，与后句「毎日」逻辑一致。"]},
{"label":"近义辨析","q":"国や年齢＿＿、誰でも応募できる。","options":["に限って","をもとに","にかこつけて","を問わず"],"answer":3,"explain":["【近义混同】「〜に限って」表示「唯独…偏偏」，与「谁都能报名」的开放条件相反。","【近义混同】「〜をもとに」表示「以…为素材」，与报名条件无关。","【近义混同】「〜にかこつけて」表示「借口…（做坏事）」，语义完全不合。","正解。「〜を問わず」接「国・年齢・性別」等范围名词，表示「不限…」，与「誰でも応募できる」的开放语境契合。"]},
]},
{"id":"b1-12","typeKey":"bun1","title":"模拟⑫ 文末・評価の型","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"文末表现","q":"この不調の原因は、単なる疲労ではなく、慢性的な睡眠不足＿＿。","options":["にすぎない","とは限らない","にほかならない","に及ばない"],"answer":2,"explain":["【近义混同】「〜にすぎない」表示「不过是…」，带贬低视角，与「単なる…ではなく」揭示真正原因的强调语气相抵。","【呼应冲突】「〜とは限らない」表示「未必…」，与前句「…ではなく」的断定方向矛盾。","正解。「〜にほかならない」表示「正是…、无非是…」的强断定，与纠正误判、点明真因的句式契合。","【接续不合】「〜に及ばない」表示「不必…／达不到…」，此处无比较或必要性的语境。"]},
{"label":"文末表现","q":"わざわざ行く＿＿。電話で十分だ。","options":["までもない","ものでもない","に決まっている","ままだ"],"answer":0,"explain":["正解。「〜までもない」接动词辞书形，表示「没必要…」，「わざわざ行くまでもない」即「没必要特意跑一趟」。","【近义混同】「〜ものでもない」接动词辞书形，表示「也不是不…」的委婉肯定，与「电话即可」的否定判断不合。","【时态肯否错位】「〜に決まっている」表示「肯定是…」的强断定，「わざわざ行くに決まっている」与后句「電話で十分」矛盾。","【接续不合】「〜ままだ」接た形表示状态持续，「行くままだ」不成立。"]},
{"label":"文末表现","q":"勝てる＿＿。相手は優勝候補だ。","options":["ものだ","わけにはいかない","ものか","とおりだ"],"answer":2,"explain":["【文语气】「〜ものだ」接可能形后无法构成反问，「勝てるものだ」与「相手は優勝候補」的悲观判断不合。","【近义混同】「〜わけにはいかない」表示「碍于情理不能…」，「赢不了」并非情理上的禁止。","正解。「〜ものか」接可能形＋否定判断，表示反问「怎么可能…」，「勝てるものか」即「怎么可能赢」。","【近义混同】「〜とおりだ」表示「正如…那样」，此处无从引用先例。"]},
{"label":"文末表现","q":"そんな言い方は聞いていられない。失礼＿＿。","options":["極まりない","に堪えない","を禁じ得ない","ずにはすまない"],"answer":0,"explain":["正解。「〜きわまりない」接な形容词词干（失礼），表示「极其…（贬义）」，「失礼極まりない」为固定评价。","【接续制约】「〜に堪えない」接消极情感名词（悲しみに堪えない），「失礼に堪えない」搭配不当。","【接续制约】「〜を禁じ得ない」接情感名词＋を，「失礼を禁じ得ない」不成立。","【接续不合】「〜ずにはすまない」接动词ない形（謝らずにはすまない），不能直接接な形容词「失礼」。"]},
{"label":"近义辨析","q":"努力した＿＿、結果が出ないこともある。","options":["するが早いか","したそばから","するうちに","したところで"],"answer":3,"explain":["【近义混同】「〜が早いか」表示「刚…就…」，描述紧接着的动作，「努力するが早いか」不成立。","【近义混同】「〜たそばから」表示「刚…就（被…）」，多用于反复发生的无效化，与单次让步不合。","【近义混同】「〜うちに」表示「在…期间」，「努力するうちに、結果が出ない」语义矛盾（期间内应发生某变化）。","正解。「〜たところで」接た形，表示「即使…（也无济于事）」，「努力したところで、結果が出ないこともある」即「即便努力也未必有结果」。"]},
]},
{"id":"b1-13","typeKey":"bun1","title":"模拟⑬ 原因・理由の型（上）","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"一点の差で合格を逃した＿＿、彼はもう一年勉強を続けることにした。","options":["だけあって","ばかりに","あまり","おかげで"],"answer":1,"explain":["【近义混同】「〜だけあって」＝「不愧是…」，表示名实相符的称赞，与本句「落榜」的消极因果相反。","正解。「〜ばかりに」接た形，表示「只因…（引发负面结果）」，与「合格を逃した→继续苦读」的悔恨因果契合。","【接续不合】「〜のあまり」前接感情·状态名词（喜びのあまり），不能直接接「逃した」的た形。","【近义混同】「〜おかげで」表示得益于的正面因果，与落榜的语境相反（负面应说「せいで」）。"]},
{"label":"近义辨析","q":"さすが有名店＿＿、開店前から長い行列ができていた。","options":["だけあって","ばかりに","のあまり","せいで"],"answer":0,"explain":["正解。「〜だけあって」＝「不愧是…」，「さすが＋だけあって」为固定呼应，表示名实相符。","【近义混同】「〜ばかりに」表示负面结果的归因，与排队盛况的正面语境相反。","【接续不合】「〜のあまり」前接感情·状态名词表「因过分而」，与「有名店」不搭。","【近义混同】「〜せいで」把结果归咎于原因（负面评价），与盛况相反。"]},
{"label":"近义辨析","q":"湖の形が琵琶に似ている＿＿、「琵琶湖」という名が付いた。","options":["ばかりに","だけあって","ことから","あまり"],"answer":2,"explain":["【接续不合】「〜ばかりに」接た形·な形，接辞书形「似ている」不能构成该归因。","【近义混同】「〜だけあって」表示名实相符，与命名的客观依据无关。","正解。「〜ことから」表示客观缘由，是「由来源·依据命名」的典型用法。","【接续不合】「〜のあまり」前接感情名词，不能接「似ている」。"]},
{"label":"近义辨析","q":"寝る前にスマホを見続ける＿＿、最近まったく眠れなくなってしまった。","options":["おかげで","だけあって","ばかりに","せいで"],"answer":3,"explain":["【近义混同】「おかげで」表示得益于（正面），与失眠的负面结果方向相反。","【近义混同】「〜だけあって」表示名实相符的称赞，无此义。","【接续不合】「〜ばかりに」接た形（見続けたばかりに），接辞书形「見続ける」不成立。","正解。「〜せいで」把负面结果归咎于原因，含责怪语气，与「睡不着的坏结果」契合。"]},
{"label":"近义辨析","q":"彼は悲しみの＿＿、しばらく言葉を失った。","options":["あまり","ばかりに","だけあって","ことから"],"answer":0,"explain":["正解。「〜のあまり」前接感情·状态名词，表示「因过分…而」引发极端状态，「悲しみのあまり」为惯用搭配。","【接续不合】「〜ばかりに」接た形·な形，不能接「悲しみの」。","【近义混同】「〜だけあって」表示名实相符，与失语的极端反应无关。","【接续不合】「〜ことから」接句子的普通形表示客观缘由，「悲しみのことから」不成立。"]},
]},
{"id":"b1-14","typeKey":"bun1","title":"模拟⑭ 原因・理由の型（下）","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"期待が大きかった＿＿、不合格のショックも大きかった。","options":["だけあって","ばかりに","だけに","のあまり"],"answer":2,"explain":["【近义混同】「〜だけあって」＝名实相符的称赞（さすが〜だけあって），无法表达「期待大→失望也大」的正负相乘。","【接续制约】「〜ばかりに」表示负面结果的单一归因，无法表达程度相乘的呼应。","正解。「〜だけに」表示「正因为…所以更加…」，前后程度互相呼应，「期待が大きかっただけに、ショックも大きい」是典型句式。","【接续不合】「〜のあまり」前接感情名词（の＋あまり），不能接た形「大きかった」。"]},
{"label":"近义辨析","q":"本気で君の将来を思えば＿＿、言いにくいことも言うのだ。","options":["だけ","こそ","ばかり","まで"],"answer":1,"explain":["【呼应冲突】「思えばだけ」不成立；「だけ」不与ば形呼应构成因果强调。","正解。「〜ばこそ」（思えばこそ）表示「正因为…才」，是ば形强调因果的固定呼应，多用于郑重说明真心。","【接续不合】「〜ばかりに」须整体接在た形·な形后（思ったばかりに），不能拆成「思えば＋ばかり」。","【近义混同】「〜までだ」表示「大不了…罢了」，与强调真心动机的语气不合。"]},
{"label":"近义辨析","q":"過疎と高齢化＿＿、この村の小学校はついに閉校を迎えた。","options":["ばかりに","せいで","こととて","ゆえに"],"answer":3,"explain":["【接续不合】「〜ばかりに」接た形·な形，不能直接接名词「過疎と高齢化」。","【近义混同】「〜せいで」把负面结果归咎于具体的人·物的责任，用于社会结构性原因则语气不当。","【接续不合】「〜こととて」须接「名词＋の＋こととて」，直接接名词不成立。","正解。「〜ゆえに」接名词，表示「因…（文语）」，客观陈述结构性原因，书面语气与閉校的郑重表述契合。"]},
{"label":"近义辨析","q":"三年に一度の大祭＿＿、町は普段見られない活気に満ちていた。","options":["とあって","とあれば","のことだから","ときたら"],"answer":0,"explain":["正解。「〜とあって」表示「因为处于…特殊状况」，描述特殊时点带来的客观景象，与后句的盛况描写契合。","【近义混同】「〜とあれば」表示「如果是…（就愿意做）」，接意愿·决心，不能描写既成的盛况。","【接续不合】「〜のことだから」前接人名词，表示对熟悉之人的推断，不能用于活动。","【近义混同】「〜ときたら」表示把对象当作抱怨的话题，与盛况的正面描写相反。"]},
{"label":"近义辨析","q":"「遅れてすみません。朝から子どもが熱を出した＿＿、家を出るのが遅れてしまったのです。」","options":["とあって","ものですから","ばかりに","だけあって"],"answer":1,"explain":["【近义混同】「〜とあって」客观描述特殊状况引发的景象，不用于个人的道歉辩解。","正解。「〜ものですから」表示「因为…（辩解语气）」，是道歉·解释场合的礼貌表达，与前后句的道歉语体契合。","【文体不合】「〜ばかりに」为书面强调归因，不能用于会话中的礼貌辩解。","【近义混同】「〜だけあって」表示名实相符的称赞，与辩解无关。"]},
]},
{"id":"b1-15","typeKey":"bun1","title":"模拟⑮ 条件・仮定の型","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"会議で少しでもミスを＿＿、厳しく追及される。","options":["しない限り","しだい","しかねる","しようものなら"],"answer":3,"explain":["【近义混同】「〜ない限り」表示「只要不…就（不）」，后句须为否定，与「追及される」的肯定断定不合。","【近义混同】「〜次第」接ます形表示「一…立刻（随即做）」，是主动承担的动作，与受惩罚的被动结果不合。","【接续不合】「〜かねる」接ます形表示「难以做到（婉拒）」，主语是说话人的意愿行为，与「被追及」不合。","正解。「〜(よ)うものなら」接意志形，表示「一旦…的话（后果严重）」，与「少しでも＋受身的结果」的警告语气契合。"]},
{"label":"接续制约","q":"実際に住んで＿＿、この街のよさは分からない。","options":["みるそばから","みたなり","みないことには","みるうちに"],"answer":2,"explain":["【近义混同】「〜そばから」表示「刚…就（被抵消）」，描述徒劳的反复，与本句「不体验就无法理解」的条件关系不合。","【接续不合】「〜たなり」表示「以…状态（一去不返）」，接续与语义均不合。","正解。「〜ないことには」接ない形，与后句否定「分からない」呼应，表示「不…就不…」。","【近义混同】「〜うちに」表示「在…期间（趁着）」，与本句的必要条件关系不合。"]},
{"label":"近义辨析","q":"引き受けた＿＿、最後まで責任を持ちます。","options":["以上は","上に","うえで","ものだから"],"answer":0,"explain":["正解。「〜以上(は)」接た形，表示「既然…就（必须）」，引出责任·决心，与后句的表态契合。","【近义混同】「〜上に」表示「在…基础上添加」，为递进关系，与决心句不合。","【近义混同】「〜うえで」表示「在…之后再做下一步」，是动作的先后，与「既然…就」的义务句不合。","【近义混同】「〜ものだから」表示辩解的原因，与表决心的后句无关。"]},
{"label":"呼应制约","q":"眠ろう＿＿、眠れない。","options":["にも","ものの","がてら","かたわら"],"answer":0,"explain":["正解。「〜(よ)うにも＋否定」表示「想…也不能…」，意志形＋にも＋可能动词的否定是固定呼应。","【接续不合】「〜ものの」接た形（眠ったものの），且表示逆接让步，与本句的不可能关系不合。","【接续不合】「〜がてら」接ます形（眠りがてら），表示「顺便」，与本句无关。","【接续不合】「〜かたわら」接辞书形·名词（眠るかたわら），表示身份并立，与本句不合。"]},
{"label":"近义辨析","q":"子ども＿＿、言われたことをそのまま信じてしまうな。","options":["ともあれ","ならでは","ではあるまいし","に限って"],"answer":2,"explain":["【近义混同】「〜はともあれ」表示「姑且不论」，用于搁置话题，与本句的责备不合。","【接续不合】「〜ならでは」表示「唯有…才有的」，后须接名词（ならではの＋名词），与训诫句不合。","正解。「〜ではあるまいし」表示「又不是…（没必要／不该…）」，与对成年人的责备语境契合。","【近义混同】「〜に限って」表示「唯独…偏偏（发生消极意外）」，与本句的训诫不合。"]},
]},
{"id":"b1-16","typeKey":"bun1","title":"模拟⑯ 強調・断定の型","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"文末表现","q":"十年前の機械が新品同様＿＿。","options":["とは","とはいえ","というものだ","にほかならない"],"answer":0,"explain":["正解。「〜とは」接句子表示「竟然…（惊愕）」，句尾省略感叹，与意外发现的语境契合。","【近义混同】「〜とはいえ」表示「虽说如此」，为部分让步，须接后续评价，不能独立结句表惊愕。","【近义混同】「〜というものだ」表示「这才真是…」的断言，与惊愕语气不合。","【接续不合】「〜にほかならない」接名词，表示「正是…」的强断定，不能接句子后表惊愕。"]},
{"label":"近义辨析","q":"筆跡から見て、これは本人が書いたもの＿＿。","options":["に限る","に越したことはない","に決まっている","に相違ない"],"answer":3,"explain":["【近义混同】「〜に限る」表示「最好（莫过于）」，是建议的语气，与本句的推断不合。","【近义混同】「〜に越したことはない」表示「没有比…更好」，同样为建议·愿望语气。","【文体不合】「〜に決まっている」为主观断定（口语），与本句「筆跡から見て」的书面推断语体不合。","正解。「〜に相違ない」接普通形，表示「必是…」的书面断定，与依据客观线索推断的语体契合。"]},
{"label":"文末表现","q":"誤りを認めるのは弱さではない。むしろ誠実さの表れ＿＿。","options":["どころではない","というものだ","ものか","にすぎない"],"answer":1,"explain":["【近义混同】「〜どころではない」表示「哪里谈得上」，用于忙乱无暇的语境，与本句的正面断言相反。","正解。「〜というものだ」表示「这才真是…」，对事物本质下断言，与前句的翻案论证契合。","【近义混同】「〜ものか」为反问「怎么可能」，与正面断言的语气相反。","【近义混同】「〜にすぎない」表示「不过是…」的贬低，与抬升评价的语境相反。"]},
{"label":"近义辨析","q":"彼の突拍子もない計画は、周囲の強い反発を買わ＿＿。","options":["ないことだ","ずにはすまない","ずにはおかない","ずにはいられない"],"answer":2,"explain":["【接续不合】「〜ことだ」接辞书形（謝ることだ），表示对个人的建议，不能接ない形后表示必然结果。","【近义混同】「〜ずにはすまない」表示「不…就（自己）过意不去／难免被追究」，主语是负有义务的行为者；本句主语是「计划」，指事态必然引发反应。","正解。「〜ずにはおかない」表示「必然会引起…」，主语可为事态，与「计划招致反発」的客观必然契合。","【近义混同】「〜ずにはいられない」表示说话人感情上「禁不住…」，主语是人的情感冲动，不能用于计划。"]},
{"label":"文末表现","q":"十年ぶりに実家の母の味を味わった。その喜び＿＿。","options":["というところだ","というものだ","とはいえ","といったらなかった"],"answer":3,"explain":["【近义混同】「〜というところだ」表示「大概也就…的程度」，与喜悅的极端感叹不合。","【近义混同】「〜というものだ」是冷静的断言「这才真是…」，无法表达难以言表的激动。","【近义混同】「〜とはいえ」表示「虽说如此」，为部分让步，与本句的感叹不合。","正解。「〜といったらない（といったらなかった）」表示「…得难以形容」，是极端感叹的固定表达。"]},
]},
{"id":"b1-17","typeKey":"bun1","title":"模拟⑰ 契約・時点の型（第二弾）","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"接续制约","q":"エアコンのスイッチを入れた＿＿、奇妙な音がし始めた。","options":["や否や","とたん","なり","が早いか"],"answer":1,"explain":["【接续不合】「〜や否や」接辞书形（入るや否や），不能接た形「入れた」。","正解。「〜たとたん（に）」接た形，表示「刚一…就（发生了突发状况）」，与异响的意外性契合。","【接续不合】「〜なり」接辞书形（入るなり），不能接た形。","【接续不合】「〜が早いか」接辞书形（入るが早いか），不能接た形。"]},
{"label":"近义辨析","q":"彼はオフィスに入ってくる＿＿、皆に挨拶もせずパソコンに向かった。","options":["なり","や否や","とたん","そばから"],"answer":0,"explain":["正解。「〜なり」接辞书形，表示同一主体的动作「刚一…就（紧接着）」，与无挨拶直接工作的连贯动作及批判语气契合。","【近义混同】「〜や否や」虽也接辞书形，但偏重客观报道突发事态，不带「同一主体紧接着做某事」的连贯性。","【接续不合】「〜たとたん」接た形，且后句多为突发外部事件。","【近义混同】「〜そばから」表示「刚…就（被抵消）」的徒劳反复，与本句的一次性连贯动作不合。"]},
{"label":"近义辨析","q":"彼の影響は、隣の県＿＿及んでいる。","options":["に限って","を皮切りに","に至るまで","に際して"],"answer":2,"explain":["【近义混同】「〜に限って」表示「唯独…偏偏」，与本句的范围扩展不合。","【近义混同】「〜を皮切りに」表示「以…为开端」，指后续发展的起点，与本句「连邻县都波及」的范围极限不合。","正解。「〜に至るまで」表示「直到…（范围推到极端）」，与影响范围的扩展契合。","【近义混同】「〜に際して」表示「当…之际」，是行动时点，与范围不合。"]},
{"label":"近义辨析","q":"昨日＿＿、彼はこの町を出ていった。もう会えないだろう。","options":["をもって","に至って","を皮切りに","を限りに"],"answer":3,"explain":["【近义混同】「〜をもって」表示中性时点（公告体「本日をもって」），无「以此为最后」的诀别语气。","【接续不合】「〜に至って」表示事态恶化到极端地步（事ここに至って），不能接「昨日」的时点。","【近义混同】「〜を皮切りに」表示「以…为开端（此后展开）」，与「此后不再见」的方向相反。","正解。「〜を限りに」表示「以…为最后（时限）」，含诀别·悲壮语气，与「再也见不到」的续句契合。"]},
{"label":"近义辨析","q":"彼は一度ゲームを始めた＿＿、呼んでも返事がない。","options":["からには","が最後","たびに","に至って"],"answer":1,"explain":["【近义混同】「〜からには」表示「既然…就（必须）」，后句应为决心义务，与本句的失控状态不合。","正解。「〜たが最後」表示「一旦…就（不可挽回）」，与「叫也不应」的失控状态契合。","【近义混同】「〜たびに」表示「每当…就」，与本句的一次性状态变化不合。","【接续不合】「〜に至って」表示事态发展到极端（事ここに至って），接续与语义均不合。"]},
]},
{"id":"b1-18","typeKey":"bun1","title":"模拟⑱ 文語・残存表現の型","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"接客業の者が客に怒鳴るなど、＿＿行為だ。","options":["あるべからず","あるまい","あるまじき","あろう"],"answer":2,"explain":["【近义混同】「〜べからず」直接结句表示「禁止…」（立ち入るべからず），作连体修饰须用「べからざる」；「あるべからず行為」不成立。","【近义混同】「〜まい」表示「大概不…／决不…」的推量·否定意志，不能作连体修饰表示「不相称」。","正解。「〜まじき」（ある→あるまじき）表示「与身份不相称的…」，是「行為」前最典型的谴责性连体修饰。","【接续不合】「〜う（意志形）」表示意志·推量，不能作连体修饰。"]},
{"label":"近义辨析","q":"選手＿＿、審判の判定に口を出すべきではない。","options":["たるもの","ならでは","たりとも","ともあれ"],"answer":0,"explain":["正解。「〜たるもの」表示「身为…（就该…）」，与身份义务的训诫契合。","【接续不合】「〜ならでは」表示「唯有…才有的」，后须接名词（ならではの＋名词），与训诫句不合。","【接续不合】「〜たりとも」与最小量名词（一日たりとも）搭配，表示「哪怕…也不」，接续不合。","【近义混同】「〜はともあれ」表示「姑且不论」，与本句的训诫不合。"]},
{"label":"近义辨析","q":"名医＿＿、死を防ぐことはできない。","options":["にしても","ならでは","において","といえども"],"answer":3,"explain":["【近义混同】「〜にしても」表示一般让步「即使…也」，语气平淡，无法强调「连名医这样的人物也…」的极端让步。","【接续不合】「〜ならでは」表示「唯有…独有的」，与让步句不合。","【接续不合】「〜において」表示「在…（场所·领域）」，与本句的让步关系不合。","正解。「〜といえども」表示「即便是…（也）」，多与极端例（名医・天才）搭配，构成让步强调。"]},
{"label":"近义辨析","q":"ここは貴重な遺跡の保存区域だ。立ち入る＿＿。","options":["まじき","べからず","ごとく","がたい"],"answer":1,"explain":["【接续不合】「〜まじき」作连体修饰（あるまじき行為），不能直接结句表示禁止。","正解。「〜べからず」接辞书形，直接结句表示「不可…」，是告示·看板的固定文语。","【接续不合】「〜ごとく」表示「如…一般」的比况，与本句的禁止不合。","【接续不合】「〜がたい」接ます形（入りがたい），表示心理上的「难以…」，且为陈述而非告示禁止。"]},
{"label":"近义辨析","q":"ご挨拶＿＿、お邪魔いたしました。","options":["かたがた","がてら","ながら","が早いか"],"answer":0,"explain":["正解。「〜かたがた」接ます形·名词，表示「兼作…（顺便）」，郑重的拜访寒暄场景正是其典型用法。","【文体不合】「〜がてら」同样表示「顺便」，但语感轻松日常，与本句郑重的拜访语体不合。","【接续不合】「〜ながら」接名词表示「保持…原状」（昔ながら），与本句的兼作目的不合。","【接续不合】「〜が早いか」表示「刚…立刻」，与本句的目的兼作不合。"]},
]},
{"id":"b1-19","typeKey":"bun1","title":"模拟⑲ 複合助詞の型","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"式典は市の大講堂＿＿行われた。","options":["にとって","にかけて","にわたって","において"],"answer":3,"explain":["【近义混同】「〜にとって」表示「对…而言」的评价角度，与本句的举行场所不合。","【近义混同】「〜にかけては」表示「在…方面（首屈一指）」，评价技能领域，与场所不合。","【近义混同】「〜にわたって」表示范围·期间的持续（三日間にわたって），不接具体场馆名词。","正解。「〜において」表示「在…（场所·场合）」，书面体，与式典举行的正式场合契合。"]},
{"label":"近义辨析","q":"疲れ果てていて、立ち上がる力＿＿なかった。","options":["だに","すら","たりとも","のみ"],"answer":1,"explain":["【接续不合】「〜だに」多与「夢にだに思わぬ」等惯用搭配，不能替代格助词接「力」。","正解。「〜すら」表示「连…都」，可替代格助词（力すらなかった），书面语感与极端化契合。","【近义混同】「〜たりとも」与最小量（一日・一秒）搭配表示「哪怕…也不」，与「力」不搭。","【近义混同】「〜のみ」表示「唯有…」（ただ〜のみ），与本句的极端例举不合。"]},
{"label":"近义辨析","q":"一日＿＿無駄にできない。今日から学習計画を立て直そう。","options":["もさることながら","のみならず","たりとも","を問わず"],"answer":2,"explain":["【接续不合】「〜もさることながら」表示「…自不必说，更…」，接续与语义均不合。","【近义混同】「〜のみならず」表示「不仅…而且」，后项应为更大的范围，与本句的最小量强调不合。","正解。「〜たりとも」与最小量名词搭配（一日たりとも），表示「哪怕一天也…（不能）」。","【接续不合】「〜を問わず」表示「不限…」（国・年齢を問わず），与最小量强调不合。"]},
{"label":"近义辨析","q":"顧客＿＿のビジネスだ。顧客を裏切る会社は必ず衰退する。","options":["あって","に基づく","にかかわる","をめぐる"],"answer":0,"explain":["正解。「〜あっての＋名词」表示「有…才有…」，「顧客あってのビジネス」是经典表述。","【近义混同】「〜に基づく」表示「基于…（依据）」，与本句的存在依存关系不合。","【近义混同】「〜にかかわる」表示「关系到…」，方向与本句相反（非「影响顾客」而是「依存顾客」）。","【接续不合】「〜をめぐる」表示「围绕…」，修饰争论·对立的话题，与「ビジネス」不搭。"]},
{"label":"近义辨析","q":"昨年度の事故多発＿＿、安全教育を全面的に見直すこととした。","options":["に応じて","に限り","に鑑み","に則って"],"answer":2,"explain":["【近义混同】「〜に応じて」表示「根据…相应变化」，与本句的郑重检讨不合。","【接续不合】「〜に限り」表示「仅限于…（优惠对象）」，与本句的决策缘由不合。","正解。「〜に鑑み」表示「鉴于…」，是公文·报告体中陈述决策缘由的固定文语。","【近义混同】「〜に則って」表示「依照（惯例·先例）」，与本句「鉴于事故」的缘由不合。"]},
]},
{"id":"b1-20","typeKey":"bun1","title":"模拟⑳ 対比・添加の型（第二弾）","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"彼は漢字＿＿、ひらがなもあやしい。","options":["はもとより","はおろか","のみならず","もさることながら"],"answer":1,"explain":["【近义混同】「〜はもとより」用于中性·正面的递进列举（英語はもとより仏語も），与本句贬低的语境不合。","正解。「〜はおろか」表示「…自不必说，连…也（多接消极评价）」，与连假名都靠不住的贬低契合。","【近义混同】「〜のみならず」为中性递进，不承载「连基础都不会」的消极语感。","【接续不合】「〜もさることながら」表示「…自不必说，更…」，用于对两个优点的并置褒扬，与本句相反。"]},
{"label":"近义辨析","q":"性能の高さ＿＿、デザインの美しさも際立っている。","options":["はおろか","に反して","に限らず","もさることながら"],"answer":3,"explain":["【近义混同】「〜はおろか」用于「前者尚且不足，遑论后者」的消极递进，与本句的两点并置褒扬不合。","【接续不合】「〜に反して」表示「与…相反」，与本句的递进褒扬不合。","【近义混同】「〜に限らず」表示「不限于…」，是范围扩展，非两项并置。","正解。「〜もさることながら」表示「…自不必说，更…」，与「性能之外设计也突出」的并置褒扬契合。"]},
{"label":"近义辨析","q":"この技術は国内＿＿、海外からも高い評価を受けている。","options":["のみならず","を問わず","ならでは","をおいて"],"answer":0,"explain":["正解。「〜のみならず」表示「不仅…而且…」，书面递进，与国内外评价的展开契合。","【接续不合】「〜を問わず」须接一对并列范畴（国・年齢を問わず），单个「国内」不成立。","【接续不合】「〜ならでは」表示「唯有…才有的」，与本句的递进不合。","【接续不合】「〜をおいて」接人名词表示「除了…别无」，与范围递进不合。"]},
{"label":"近义辨析","q":"彼を＿＿、若手だけで新製品を作り上げた。","options":["をきっかけに","をはじめ","を中心に","を皮切りに"],"answer":2,"explain":["【近义混同】「〜をきっかけに」表示「以…为契机（转机）」，与本句的核心人物不合。","【近义混同】「〜をはじめ」表示「以…为首（列举代表）」，强调他也是众多成员之一，与本句「以他为核心」不同。","正解。「〜を中心に」表示「以…为中心」，与核心人物的表述契合。","【近义混同】「〜を皮切りに」表示「以…为开端」，指时间起点，与核心地位不合。"]},
{"label":"近义辨析","q":"機械の修理＿＿、彼の右に出る者はいない。","options":["に際して","にかけては","に限り","に比べて"],"answer":1,"explain":["【近义混同】「〜に際して」表示「当…之际」，是行动时点，与技能评价不合。","正解。「〜にかけては」表示「在…方面（首屈一指）」，与「右に出る者はいない」的评价句式固定呼应。","【接续不合】「〜に限り」表示「仅限于…（优惠对象）」，与本句不合。","【近义混同】「〜に比べて」表示「与…相比」，是比较句，与最高级评价不合。"]},
]},
{"id":"b1-21","typeKey":"bun1","title":"模拟㉑ 様態・傾向の型（第二弾）","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"三十歳になっても、彼にはどこか子ども＿＿ところがある。","options":["がちな","気味の","げな","っぽい"],"answer":3,"explain":["【近义混同】「〜がち」表示频度倾向（动辄），「子どもがち」不成立（がち多接不理想的行为状态）。","【近义混同】「〜気味」表示程度略高（多接不理想状态：風邪気味），不能接「子ども」表示气质。","【接续不合】「〜げ」多接形容词词干·动词ます形（言いたげ），名词仅限「大人げ」等极少数惯用，「子どもげ」不成立。","正解。「〜っぽい」接名词，表示「有…的味道」，「子どもっぽい」为惯用表达。"]},
{"label":"近义辨析","q":"空も風も、すっかり春＿＿。","options":["っぽくなってきた","がちになってきた","めいてきた","げになってきた"],"answer":2,"explain":["【近义混同】「〜っぽい」接名词表示「有…味道」，但「春っぽい」多为静态评价，与「すっかり…てきた」的季节推移感不合。","【接续不合】「〜がち」表示频度倾向（常常），与季节推移不合。","正解。「〜めく」接名词表示「带有…气息」，「春めいてきた」是季节推移的典型表达。","【接续不合】「〜げ」不能接名词「春」。"]},
{"label":"近义辨析","q":"卒業、就職、結婚——この一年、彼はいいこと＿＿だった。","options":["ずくめ","だらけ","まみれ","っぽい"],"answer":0,"explain":["正解。「〜ずくめ」表示「净是…（清一色系列）」，与列举出的系列好事契合，「いいことずくめ」为惯用表达。","【近义混同】「〜だらけ」表示「满是…」，多接脏污·缺点等负面事物，且无「系列接连不断」的系列感。","【接续不合】「〜まみれ」表示「沾满（液体·粉末）」（汗まみれ），不能接抽象名词「いいこと」。","【接续不合】「〜っぽい」接名词表示气质倾向，不能用于「いいこと」的系列列举。"]},
{"label":"近义辨析","q":"徹夜が続いて、最近は少し疲れ＿＿だ。","options":["がち","気味","っぽい","げ"],"answer":1,"explain":["【近义混同】「〜がち」表示频度倾向（常常如此），本句「最近稍微」描述的是当下状态的程度。","正解。「〜気味」表示「略带…状态」，与「少し」的轻度及当下状态契合。","【接续制约】「〜っぽい」接ます形表示易…的性格倾向（忘れっぽい），「疲れっぽい」与本句的当下状态不合。","【接续不合】「〜げ」接ます形·形容词词干表示神情，不能接「疲れ」表示状态。"]},
{"label":"近义辨析","q":"このまま放置すれば、個人情報が流出する＿＿。","options":["しまつだ","きらいがある","がちだ","おそれがある"],"answer":3,"explain":["【时态肯否错位】「〜始末だ」表示事态已实际恶化到某地步（已发生），与「放置すれば」的假设警告不合。","【近义混同】「〜きらいがある」表示「有…的倾向（贬义委婉，指惯常习性）」，与本句的潜在风险警告不合。","【近义混同】「〜がちだ」表示频度倾向，与本句「一旦放置就恐将…」的假设不合。","正解。「〜おそれがある」接辞书形，表示「恐怕会…」，是公告·报道体中对负面可能性的正式警告。"]},
]},
{"id":"b1-22","typeKey":"bun1","title":"模拟㉒ 敬語の型（第二弾）","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"敬語","q":"本日より、この部署を担当＿＿。どうぞよろしくお願いいたします。","options":["させていただきます","していただきます","なさっております","して差し上げます"],"answer":0,"explain":["正解。「〜(さ)せていただく」表示「承蒙（对方）允许我做…」，就任·担当场合的郑重自谦表达。","【敬語误用】「〜ていただく」表示「请对方为我做…」，方向与本句（我方承担工作）相反。","【敬語误用】「〜なさる」是尊敬语（对方做），不能用于自己的行为。","【敬語误用】「〜て差し上げる」表示「我为对方做…（提供恩惠）」，用于就任场合显得傲慢不合时宜。"]},
{"label":"敬語","q":"課長は、忙しい中、わざわざ資料の要点をていねいに説明＿＿。","options":["していただきました","してさしあげました","してくださいました","拝見いたしました"],"answer":2,"explain":["【敬語误用】「〜ていただく」表示「请对方做」，与「课长为我说明」的方向相反。","【敬語误用】「〜てさしあげる」表示「我（方）为对方做」，与主语「課長」的方向相反。","正解。「〜てくださる」是尊敬语，表示「对方为我（方）做…」，与感激的语境契合。","【近义混同】「拝見する」是「看」的谦让语，主语应为说话人，与「課長が説明する」不合。"]},
{"label":"敬語","q":"山田先生の御高名は、かねてより＿＿。","options":["存じております","お知りになっております","存じ上げております","拝見しております"],"answer":2,"explain":["【敬語误用】「存じる」同为谦让语，但用于一般事物·事项（その件は存じております）；对个人的学问·名声表示敬意时用「存じ上げる」。","【敬語误用】「お知りになる」是尊敬语（对方知道），方向与主语「私」相反。","正解。「存じ上げる」是「知っている」的谦让语，用于对特别值得尊敬之人，与「御高名」「かねてより」的仰慕语体契合。","【近义混同】「拝見する」是「看」的谦让语，与「知道其名声」不合。"]},
{"label":"敬語","q":"お手紙、確かに＿＿。ご依頼の件、早急に対応いたします。","options":["拝借しました","拝送いたしました","お目にかかりました","拝読いたしました"],"answer":3,"explain":["【近义混同】「拝借する」是「借」的谦让语，与「收到来信」不合。","【敬語误用】「拝送」表示「（我方）恭敬奉上」，与「收到」的方向相反。","【近义混同】「お目にかかる」是「会面」的谦让语，与「读信」不合。","正解。「拝読する」是「读」的谦让语（拝＋読），与「收到并拜读来信」的商务书函场景契合。"]},
{"label":"敬語","q":"三年ぶりに恩師に＿＿、近況をご報告した。","options":["お目にかけて","ご覧になって","お目にかかって","お会いになられて"],"answer":2,"explain":["【敬語误用】「お目にかける」表示「（我方）给对方看」，「拜见恩师」应用「お目にかかる」。","【敬語误用】「ご覧になる」是「看」的尊敬语，主语应为对方；「我去拜见」须用谦让语。","正解。「お目にかかる」是「会面·拜见」的谦让语，与「拜访恩师」的方向契合。","【敬語误用】「お会いになる」是尊敬语（对方会面），且「なられて」构成双重敬语误用。"]},
]},
{"id":"b1-23","typeKey":"bun1","title":"模拟㉓ 逆接・让步の残部（上）","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"彼は体験がない＿＿、偉そうな口を利く。","options":["くせに","にしては","わりには","ばかりに"],"answer":0,"explain":["正解。「〜くせに」表示「明明…却（指责）」，与「无体验却摆架子」的谴责语气契合。","【近义混同】「〜にしては」表示「与预期相比」的客观评价，不带指责。","【近义混同】「〜わりには」表示「与程度不相称」的中性评价，无谴责语气。","【接续不合】「〜ばかりに」接た形（なかったばかりに），接辞书形否定不成立。"]},
{"label":"呼应制约","q":"どちらを選ぶ＿＿、責任は自分にある。","options":["とあれば","にせよ","につけ","ともあれ"],"answer":1,"explain":["【近义混同】「〜とあれば」表示「如果是…（就愿意）」，接意愿，与本句的让步不合。","正解。「〜にせよ」接辞书形，表示「无论…都（也）」，与「どちらを選ぶ＋責任」的全面让步契合。","【近义混同】「〜につけ」表示「每逢…就（情感涌起）」，与本句的让步不合。","【近义混同】「〜はともあれ」表示「姑且不论」，用于搁置话题，与本句不合。"]},
{"label":"近义辨析","q":"良いこと＿＿悪いこと＿＿、彼のことを思い出す。","options":["やら　やら","だの　だの","につけ　につけ","といい　といい"],"answer":2,"explain":["【近义混同】「〜やら〜やら」表示纷杂列举（物的杂多），不能与「思い出す」的每逢义衔接。","【近义混同】「〜だの〜だの」表示列举不满（牢骚），与「想起某人」的情感涌起不合。","正解。「〜につけ〜につけ」表示「无论…还是…（都）」，与「逢事便想起」的情感自然涌起契合。","【近义混同】「〜といい〜といい」表示对两方面并列评价，与「想起」的每逢义不合。"]},
{"label":"近义辨析","q":"見た目＿＿味＿＿、文句のつけようがない。","options":["やら　やら","につけ　につけ","だの　だの","といい　といい"],"answer":3,"explain":["【近义混同】「〜やら〜やら」表示纷杂列举，与并列评价不合。","【近义混同】「〜につけ〜につけ」表示「每逢…就」，与静态的并列评价不合。","【近义混同】「〜だの〜だの」表示列举不满，与「无可挑剔」的褒扬相反。","正解。「〜といい〜といい」表示「无论…还是…（都）」，对两方面并列评价，与「无可挑剔」契合。"]},
{"label":"近义辨析","q":"被害は深刻で、復旧＿＿の状態だ。","options":["どころの騒ぎではない","わりには","にすぎない","というものだ"],"answer":0,"explain":["正解。「〜どころの騒ぎではない」表示「远非…的状态（程度严重）」，与「受害深刻」契合。","【近义混同】「〜わりには」表示「与程度不相称」，与本句的严重性强调不合。","【近义混同】「〜にすぎない」表示「不过是」，用于贬低，与本句不合。","【近义混同】「〜というものだ」表示「这才真是」的断言，与本句不合。"]},
]},
{"id":"b1-24","typeKey":"bun1","title":"模拟㉔ 逆接・让步の残部（下）","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"簡単に終わる＿＿、三時間もかかった。","options":["ものの","と思いきや","とあって","ばかりに"],"answer":1,"explain":["【接续制约】「〜ものの」表逆接，前项须为既成事实（た形），与推量内容「終わる」不合。","正解。「〜と思いきや」接辞书形，表示「原以为…不料」，与「以为很快却花三小时」的意外契合。","【近义混同】「〜とあって」表示「因为处于特殊状况」，与本句的意外转折不合。","【近义混同】「〜ばかりに」表示负面结果的归因，与本句的时间落差不合。"]},
{"label":"近义辨析","q":"彼は足のけが＿＿、全行程を走り抜けた。","options":["を問わず","をよそに","をものともせず","にひきかえ"],"answer":2,"explain":["【接续不合】「〜を問わず」表示「不分…（并列范畴）」，与本句不合。","【近义混同】「〜をよそに」表示「无视（外界的声音·期待）」，不用于自身的伤痛。","正解。「〜をものともせず」表示「不把…放在眼里（强者姿态）」，与「忍着脚伤跑完全程」契合。","【接续不合】「〜にひきかえ」表示对照，接续与语义均不合。"]},
{"label":"近义辨析","q":"部長＿＿、そう簡単には辞められない。","options":["ときたら","とあれば","としたら","ともなると"],"answer":3,"explain":["【近义混同】「〜ときたら」表示把对象当作抱怨的话题，与本句不合。","【近义混同】「〜とあれば」表示「如果是…（就愿意）」，接意愿，与本句不合。","【近义混同】「〜としたら」表示假定「假如…」，与本句的必然性不合。","正解。「〜ともなると」表示「一到…（程度自然伴随）」，与「身居高位便难以抽身」的必然契合。"]},
{"label":"近义辨析","q":"日本語ができる＿＿、挨拶程度だ。","options":["といっても","とはいえ","というものだ","といえども"],"answer":0,"explain":["正解。「〜といっても」表示「虽说…（程度大打折扣）」，对同句内容打折扣，与会话体契合。","【近义混同】「〜とはいえ」承接前文做部分让步，多独立成句的书面表达。","【近义混同】「〜というものだ」表示「这才真是」的断言，与本句的贬降不合。","【近义混同】「〜といえども」表示「即便是…也」的极端让步，与本句的程度打折扣不合。"]},
{"label":"近义辨析","q":"週末と快晴＿＿、野外コンサートは大盛況だった。","options":["とあって","も手伝って","に加えて","をはじめ"],"answer":1,"explain":["【近义混同】「〜とあって」以单一特殊状况为因，不能叠加两个并列原因。","正解。「〜も手伝って」表示「加上…的影响（复数原因叠加）」，「週末＋快晴」两因叠加正是其用法。","【近义混同】「〜に加えて」表示「加之（递进列举）」，与「盛况」的结果句不合。","【接续不合】「〜をはじめ」表示「以…为首（列举）」，与本句的因果不合。"]},
]},
{"id":"b1-25","typeKey":"bun1","title":"模拟㉕ 対比・程度の残部","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"彼は医者＿＿、健康には無頓着だ。","options":["ものの","といっても","とはいえ","ながらも"],"answer":2,"explain":["【接续制约】「〜ものの」须接た形·である（医者であるものの），直接接名词不成立。","【近义混同】「〜といっても」接名词时表示「说是…其实（名不副实）」，与本句「身为其人却…」不合。","正解。「〜とはいえ」可直接接名词，表示「虽说是…（也）」，与「身为医生却不顾健康」的部分让步契合。","【接续不合】「〜ながらも」接ます形·名词＋ながらも，接续不合。"]},
{"label":"近义辨析","q":"彼は彼＿＿、家族のことを考えている。","options":["もとより","ながらに","だけに","なりに"],"answer":3,"explain":["【近义混同】「〜もとより」表示「本来就·自不必说」，与本句不合。","【近义混同】「〜ながらに」表示「保持…原状（状态持续）」，与本句不合。","【近义混同】「〜だけに」表示「正因为…更加」，与本句的「各自方式」不合。","正解。「〜なりに」表示「以…相应的方式」，「彼は彼なりに」是惯用呼应，与「各有各的考虑方式」契合。"]},
{"label":"近义辨析","q":"彼は以前＿＿、研究に打ち込んでいる。","options":["にもまして","にひきかえ","に限らず","に反して"],"answer":0,"explain":["正解。「〜にもまして」表示「比…更甚」，与「比以往更投入」的程度递进契合。","【近义混同】「〜にひきかえ」表示「与…正相反」的对照，与本句的同向递进不合。","【近义混同】「〜に限らず」表示「不限于…」，与本句不合。","【近义混同】「〜に反して」表示「与…相反」，与本句不合。"]},
{"label":"近义辨析","q":"この薬はよく効く＿＿、強い眠気を催す。","options":["一方だ","反面","にひきかえ","ものの"],"answer":1,"explain":["【接续制约】「〜一方だ」接辞书形表示单方向变化（悪くなる一方），与本句的两面性不合。","正解。「〜反面」表示同一事物的两面（药效与副作用同属一物），书面且契合。","【接续不合】「〜にひきかえ」用于他人他物的对照，不能用于同一药物。","【接续制约】「〜ものの」须接た形（効いたものの），接辞书形「効く」不成立。"]},
{"label":"近义辨析","q":"姉が社交的なの＿＿、弟は内向的だ。","options":["に比べて","にひきかえ","に対して","一方で"],"answer":2,"explain":["【近义混同】「〜に比べて」表示单纯比较（量·程度），与性格对照的句式不合。","【接续不合】「〜にひきかえ」接名词（社交性にひきかえ），「社交的なの＋にひきかえ」不成立。","正解。「〜のに対して」接「の＋に対して」，表示两者的中性对照。","【接续制约】「〜一方で」接辞书形·た形，接「の」后不成立。"]},
]},
{"id":"b1-26","typeKey":"bun1","title":"模拟㉖ 変化・様態の残部","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"蛇口を＿＿、出かけてしまった。","options":["出したままに","出したきりに","出すそばから","出しっぱなしに"],"answer":3,"explain":["【近义混同】「〜たまま」表示「保持…状态（中性）」，不承载「放任不管」的负面语感。","【近义混同】「〜たきり」表示「一去不返（此后再无）」，与本句的放任状态不合。","【近义混同】「〜そばから」表示「刚…就（被抵消）」的徒劳反复，与本句不合。","正解。「〜っぱなし」接ます形，表示「一直…着（该收尾的没收尾）」，与「开着水龙头出门」的放任契合。"]},
{"label":"近义辨析","q":"それは十分起こり＿＿ことだ。","options":["うる","かねない","がちな","そうな"],"answer":0,"explain":["正解。「〜うる」接ます形，表示「有可能（中性）」，与「完全可能发生」的中性语境契合。","【近义混同】「〜かねない」限定负面结果（可能酿成坏事），与本句的中性评价不合。","【近义混同】「〜がち」表示频度倾向，与本句的可能性不合。","【近义混同】「〜そうだ」表様態（快要发生），与本句的客观可能性不合。"]},
{"label":"文末表现","q":"彼が裏切るなんて、信じ＿＿。","options":["かねる","がたい","かねない","ずにはいられない"],"answer":1,"explain":["【近义混同】「〜かねる」表示「难以做到（婉拒他者的要求）」，主语是说话人的意愿行为。","正解。「〜がたい」接ます形，表示「心理上难以…」，「信じがたい」为固定搭配。","【近义混同】「〜かねない」表示「很可能（坏事）」，与本句的不可能相反。","【近义混同】「〜ずにはいられない」表示「禁不住（感情冲动）」，与本句的不相信不合。"]},
{"label":"近义辨析","q":"間違い＿＿のレポートを出してしまった。","options":["まみれ","ずくめ","だらけ","っぽい"],"answer":2,"explain":["【接续不合】「〜まみれ」限液体·粉末附着（汗まみれ），不能接抽象名词。","【近义混同】「〜ずくめ」表示「清一色系列」的接连感，此处强调「错误充斥」。","正解。「〜だらけ」表示「满是…（缺点·脏污）」，「間違いだらけ」为固定搭配。","【接续不合】「〜っぽい」表示气质倾向，「間違いっぽい」与本句的充斥义不合。"]},
{"label":"近义辨析","q":"建設現場で汗＿＿になって働いた。","options":["気味","ずくめ","っぽい","まみれ"],"answer":3,"explain":["【接续不合】「〜気味」表示「略带…状态」（疲れ気味），「汗気味」不自然。","【接续不合】「〜ずくめ」表示清一色系列，「汗ずくめ」不成立。","【接续不合】「〜っぽい」表示「有…味道」的气质倾向，不能表示附着状态。","正解。「〜まみれ」接名词，表示「沾满（液体·粉末）」，「汗まみれ」为其典型用法。"]},
]},
{"id":"b1-27","typeKey":"bun1","title":"模拟㉗ 基準・対応の残部","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"現実＿＿考えれば、この計画は甘い。","options":["に即して","に限って","に応じて","に際して"],"answer":0,"explain":["正解。「〜に即して」表示「紧扣…（现实·具体事例）」，「現実に即して考える」为惯用搭配。","【近义混同】「〜に限って」表示「唯独…偏偏」，与本句不合。","【近义混同】「〜に応じて」表示「根据…相应变化」，与本句的思考方式不合。","【近义混同】「〜に際して」表示「当…之际」，是行动时点，与本句不合。"]},
{"label":"近义辨析","q":"法律＿＿罰則を定める。","options":["に限り","に照らして","に応じて","に先立って"],"answer":1,"explain":["【近义混同】「〜に限り」表示「仅限于…（优惠对象）」，与本句不合。","正解。「〜に照らして」表示「对照…（法规·先例）」，「法律に照らして」为固定搭配。","【近义混同】「〜に応じて」表示「根据…相应变化」，与法规对照不合。","【近义混同】「〜に先立って」表示「在…之前」，与本句不合。"]},
{"label":"近义辨析","q":"市場の変化＿＿、戦略を見直した。","options":["をはじめ","をきっかけに","を踏まえて","をめぐって"],"answer":2,"explain":["【接续不合】「〜をはじめ」表示「以…为首（列举）」，与本句不合。","【近义混同】「〜をきっかけに」表示「以…为契机（转机）」，与本句的依据关系不合。","正解。「〜を踏まえて」表示「立足于…（考虑·判断）」，与「基于市场变化调整战略」契合。","【接续不合】「〜をめぐって」表示「围绕…（争论）」，与本句不合。"]},
{"label":"近义辨析","q":"証拠＿＿捜査を進めた。","options":["に際して","に沿って","に限り","に基づいて"],"answer":3,"explain":["【近义混同】「〜に際して」表示「当…之际」，与本句不合。","【近义混同】「〜に沿って」表示「遵循…（方针·路线）」，与证据的依据义不合。","【接续不合】「〜に限り」表示「仅限于…」，与本句不合。","正解。「〜に基づいて」表示「基于…（事实·依据）」，「証拠に基づいて」为固定搭配。"]},
{"label":"近义辨析","q":"物流コストの変化＿＿、送料を見直す。","options":["に応じて","につれて","に伴って","にしたがって"],"answer":0,"explain":["正解。「〜に応じて」表示「根据…相应调整（政策性）」，与「调整运费」的主动应对契合。","【近义混同】「〜につれて」表示自然联动（一方变另一方随之变），不用于政策调整。","【近义混同】「〜に伴って」表示伴随发生，与本句的对应措施不合。","【近义混同】「〜にしたがって」表示自然递进或遵从，与本句的政策性调整不合。"]},
]},
{"id":"b1-28","typeKey":"bun1","title":"模拟㉘ 契約・時点の残部","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"接续制约","q":"出かけようとした＿＿、電話が鳴った。","options":["とたん","矢先に","ばかりに","たびに"],"answer":1,"explain":["【接续不合】「〜たとたん」须接实际动作的た形，「ようとした＋とたん」不成立。","正解。「〜た矢先に」接意志形＋とした，表示「正要…时」，与突发的来电契合。","【近义混同】「〜ばかりに」表示负面归因，与本句的时点不合。","【近义混同】「〜たびに」表示「每当…就」，与本句的一次性突发不合。"]},
{"label":"近义辨析","q":"卒業して＿＿、彼の消息をまったく知らない。","options":["たびに","たとたん","て以来","たなり"],"answer":2,"explain":["【近义混同】「〜たびに」表示「每当…就」，与本句不合。","【近义混同】「〜たとたん」表示「刚一…就（突发）」，与本句的持续状态不合。","正解。「〜て以来」表示「自从…之后（状态持续至今）」，与「再无音信」的持续否定契合。","【近义混同】「〜たなり」表示「以…状态（一去不返）」，与本句的持续否定语感有别。"]},
{"label":"近义辨析","q":"会議の＿＿、停電が起きた。","options":["たびに","うちに","あいだに","最中に"],"answer":3,"explain":["【近义混同】「〜たびに」表示「每当…就」，与本句不合。","【近义混同】「〜うちに」重「趁…期间（做）」的窗口义，不用于事件突发的时点。","【近义混同】「〜あいだに」表示期间内完成某事，与本句的突发不合。","正解。「〜最中に」表示「正当…高潮时」，与「会议进行中突发停电」契合。"]},
{"label":"近义辨析","q":"公演＿＿、記者発表が行われた。","options":["に先立って","に際して","にあたって","に限り"],"answer":0,"explain":["正解。「〜に先立って」表示「在…之前（先行）」，与「发布会先于公演」契合。","【近义混同】「〜に際して」表示「当…之际」与事件同时，与本句的先后关系不合。","【近义混同】「〜にあたって」表示「值此…之际（主体意志）」，与本句的先后不合。","【接续不合】「〜に限り」表示「仅限于…」，与本句不合。"]},
{"label":"文末表现","q":"上記の理由＿＿、本日は早退させていただきます。","options":["というものだ","という次第で","といったら","といえども"],"answer":1,"explain":["【近义混同】「〜というものだ」表示「这才真是」的断言，与本句的缘由说明不合。","正解。「〜という次第で」表示「情况就是这样（说明缘由）」，是公文·邮件收尾的固定表达。","【近义混同】「〜といったら」表示「…得难以形容」的感叹，与本句不合。","【近义混同】「〜といえども」表示「即便是…也」的让步，与本句不合。"]},
]},
{"id":"b1-29","typeKey":"bun1","title":"模拟㉙ 限定・範囲の残部","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"彼の身長は二メートル＿＿。","options":["に及ばない","にすぎない","からある","に足る"],"answer":2,"explain":["【近义混同】「〜に及ばない」表示「比不上／不必」，与本句不合。","【近义混同】「〜にすぎない」表示「不过是」的贬低，与强调相反。","正解。「〜からある」接数量词，表示「足足有…」，与身高的数量强调契合。","【近义混同】「〜に足る」表示「值得…」，与本句不合。"]},
{"label":"近义辨析","q":"感謝＿＿、手紙を書いた。","options":["をめぐって","をもって","をはじめ","をこめて"],"answer":3,"explain":["【接续不合】「〜をめぐって」表示「围绕…（争论）」，与本句不合。","【近义混同】「〜をもって」表示「以…（手段·时限）」，与情感的寄托不合。","【接续不合】「〜をはじめ」表示「以…为首（列举）」，与本句不合。","正解。「〜をこめて」接情感名词，表示「满怀…」，「感謝をこめて」为固定搭配。"]},
{"label":"近义辨析","q":"一人＿＿二冊まで。","options":["につき","ごとに","につけ","に限り"],"answer":0,"explain":["正解。「〜につき」表示「每…（告示体的定额分配）」，与借阅上限的告示契合。","【近义混同】「〜ごとに」表示间隔反复（一駅ごとに），告示的定额惯用「につき」。","【近义混同】「〜につけ」表示「每逢…就」，与本句不合。","【近义混同】「〜に限り」表示「仅限于…（对象）」，与本句的分配不合。"]},
{"label":"近义辨析","q":"失敗は若者＿＿。","options":["に限り","に限ったことではない","に限って","を問わず"],"answer":1,"explain":["【近义混同】「〜に限り」表示「仅限于…（告示优惠）」，与本句相反。","正解。「〜に限ったことではない」表示「并非仅限于…」，与「失败并非年轻人专利」契合。","【近义混同】「〜に限って」表示「唯独…偏偏」，与本句相反。","【接续不合】「〜を問わず」须接一对并列范畴（国・年齢を問わず），单个「若者」不成立。"]},
{"label":"近义辨析","q":"皆さんの協力＿＿、この企画は実現しなかった。","options":["をこめて","にもかかわらず","なしには","をよそに"],"answer":2,"explain":["【近义混同】「〜をこめて」表示「满怀…」，与本句不合。","【近义混同】「〜にもかかわらず」表示「尽管…却」，与本句的必要条件不合。","正解。「〜なしには」接名词＋否定，表示「没有…就（不）」，与「没有协作便无法实现」契合。","【近义混同】「〜をよそに」表示「无视…」，与本句的方向相反。"]},
]},
{"id":"b1-30","typeKey":"bun1","title":"模拟㉚ 強調・断定の残部①","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"文末表现","q":"時が経つのは早い＿＿。","options":["ことだ","ものか","わけだ","ものだ"],"answer":3,"explain":["【近义混同】「〜ことだ」表示对个人的建议，与本句的感慨不合。","【近义混同】「〜ものか」为反问「怎么可能」，语气相反。","【近义混同】「〜わけだ」表示「难怪（归结）」，与本句的感慨不合。","正解。「〜ものだ」（感慨用法）表示「真是…啊」的普遍感慨，与「时光飞逝」的感叹契合。"]},
{"label":"文末表现","q":"人の悪口を言う＿＿。","options":["ものではない","わけではない","どころではない","ものがある"],"answer":0,"explain":["正解。「〜ものではない」表示「不该…（普遍说教）」，与「不说人坏话」的训诫契合。","【近义混同】「〜わけではない」表示「并非…（部分否定）」，与本句的禁止不合。","【近义混同】「〜どころではない」表示「哪里谈得上」，与本句不合。","【近义混同】「〜ものがある」表示「确有…之处」的感叹，与本句的禁止不合。"]},
{"label":"文末表现","q":"二度と同じ失敗はする＿＿と心に誓った。","options":["ものか","まい","ものだ","わけにはいかない"],"answer":1,"explain":["【近义混同】「〜ものか」为反问句，不能与「誓う」的意志呼应。","正解。「〜まい」表示「决不再…」的意志否定，与「誓う」的意志呼应契合。","【近义混同】「〜ものだ」表示感慨·本性·忠告，与本句的否定意志不合。","【近义混同】「〜わけにはいかない」表示「碍于情理不能」，与本句的誓言不合。"]},
{"label":"文末表现","q":"一言謝ればいい＿＿、意地を張った。","options":["ものか","ものだ","ものを","ものがある"],"answer":2,"explain":["【近义混同】「〜ものか」为反问「怎么可能」，与本句不合。","【近义混同】「〜ものだ」表示感慨·本性·忠告，与本句的责难不合。","正解。「〜ものを」表示「要是…就好了（责难未做）」，与「不肯道歉」的惋惜·责难契合。","【近义混同】「〜ものがある」表示「确有…之处」的感叹，与本句不合。"]},
{"label":"文末表现","q":"上達したいなら、毎日練習する＿＿。","options":["はずだ","ものだ","わけだ","ことだ"],"answer":3,"explain":["【近义混同】「〜はずだ」表示「理应（推断）」，与本句的建议不合。","【近义混同】「〜ものだ」表示普遍的道理·本性，不针对个人的当下处境。","【近义混同】「〜わけだ」表示「难怪（归结）」，与本句的建议不合。","正解。「〜ことだ」表示「最好…（对个人的具体建议）」，与「なら＋个人目标」的语境契合。"]},
]},
{"id":"b1-31","typeKey":"bun1","title":"模拟㉛ 強調・断定の残部②","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"待っていました＿＿、客が店になだれ込んだ。","options":["とばかりに","として","といえども","とあって"],"answer":0,"explain":["正解。「〜とばかりに」表示「仿佛在说…地（情态夸张）」，与「迫不及待涌入」的神态契合。","【近义混同】「〜として」表示「作为（身份）」，与本句的情态不合。","【近义混同】「〜といえども」表示「即便是…也」的让步，与本句不合。","【近义混同】「〜とあって」表示「因为处于特殊状况」，与本句的情态不合。"]},
{"label":"文末表现","q":"雨は止む＿＿、ますます激しくなった。","options":["どころではない","どころか","どころの騒ぎではない","ところが"],"answer":1,"explain":["【近义混同】「〜どころではない」表示「哪里谈得上（无暇）」，与本句的递进不合。","正解。「〜どころか」表示「非但…反而（更甚）」，与「雨越下越大」的递进契合。","【近义混同】「〜どころの騒ぎではない」同样表「远非…的状态」，不接逆接递进。","【近义混同】「ところが」为接续词（可是），不能接在动词后。"]},
{"label":"文末表现","q":"彼の演奏には人を引きつける＿＿。","options":["わけだ","ものだ","ものがある","というものだ"],"answer":2,"explain":["【近义混同】「〜わけだ」表示「难怪（归结）」，与本句不合。","【近义混同】「〜ものだ」表示感慨·本性·忠告，与本句的「具有某特质」不合。","正解。「〜ものがある」表示「确有…之处（由衷感叹）」，与「确有魅力」的赞叹契合。","【近义混同】「〜というものだ」表示「这才真是」的断言，与本句不合。"]},
{"label":"近义辨析","q":"運転中に居眠りして、危なく衝突する＿＿。","options":["ところで","ところに","ところを","ところだった"],"answer":3,"explain":["【近义混同】「〜ところで」接た形表示「即使…也」，与本句不合。","【近义混同】「〜ところに」表示「正当…时（外部事件）」，与本句的未遂不合。","【近义混同】「〜ところを」表示「正当…之际（致谢·免于）」，与本句不合。","正解。「〜ところだった」接辞书形，表示「差点就…」，与「险些撞上」的后怕契合。"]},
{"label":"文末表现","q":"十年も住んでいたのか。道に詳しい＿＿。","options":["わけだ","わけがない","わけではない","ものだ"],"answer":0,"explain":["正解。「〜わけだ」表示「难怪（合情合理地归结）」，与「住了十年自然熟路」契合。","【近义混同】「〜わけがない」表示「不可能」，与本句相反。","【近义混同】「〜わけではない」表示「并非…（部分否定）」，与本句相反。","【近义混同】「〜ものだ」表示感慨·本性·忠告，与本句的归结不合。"]},
]},
{"id":"b1-32","typeKey":"bun1","title":"模拟㉜ 条件・仮定の残部①","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"海外勤務＿＿、家族の協力が不可欠だ。","options":["とあれば","となると","としたら","とあって"],"answer":1,"explain":["【近义混同】「〜とあれば」表示「如果是…（就愿意）」，接意愿，与本句的后果陈述不合。","正解。「〜となると」表示「一旦要…的话（局面随之变化）」，与「事涉驻外则需配合」的必然契合。","【近义混同】「〜としたら」表示假定「假如…」，与本句的现实推演不合。","【近义混同】「〜とあって」表示「因为处于特殊状况」，描述既成景象，与本句不合。"]},
{"label":"近义辨析","q":"毎日遊んでいる＿＿、合格は夢だ。","options":["ようだ","ように","ようでは","ものの"],"answer":2,"explain":["【近义混同】「〜ようだ」表示推量「似乎」，与本句的条件预判不合。","【接续不合】「〜ように」表示目的·例示，与本句的预判不合。","正解。「〜ようでは」表示「照…这样下去（消极预判）」，与「贪玩则无望」的警告契合。","【接续制约】「〜ものの」须接た形·である，接续与语义均不合。"]},
{"label":"文末表现","q":"どんな名品も、壊れてしまえば＿＿。","options":["どころではない","というものだ","にすぎない","それまでだ"],"answer":3,"explain":["【近义混同】「〜どころではない」表示「哪里谈得上」，与本句不合。","【近义混同】「〜というものだ」表示「这才真是」的断言，与本句的归零感不合。","【近义混同】「〜にすぎない」表示「不过是」，与本句不合。","正解。「〜ばそれまでだ」表示「一旦…就全完了」，与「坏了便一无是处」契合。"]},
{"label":"文末表现","q":"条件次第で、できない＿＿。","options":["ないものでもない","ものだ","わけがない","ないまでも"],"answer":0,"explain":["正解。「〜ないものでもない」表示「并非不…（有条件地认可）」，与「视条件或可」的留有余地契合。","【近义混同】「〜ものだ」表示感慨·本性·忠告，与本句的委婉认可不合。","【近义混同】「〜わけがない」表示「不可能」，与本句相反。","【接续制约】「〜ないまでも」表示「即便不到…至少」，后项须为让步推进，与本句不合。"]},
{"label":"近义辨析","q":"三日＿＿、一ヶ月も放置するのは問題だ。","options":["どころか","ならまだしも","どころではない","に限って"],"answer":1,"explain":["【近义混同】「〜どころか」表示「非但…反而」，与本句的比较让步不合。","正解。「〜ならまだしも」表示「如果是…倒还罢了」，与「三天尚可，一月不可」的递进责难契合。","【近义混同】「〜どころではない」表示「哪里谈得上」，与本句不合。","【近义混同】「〜に限って」表示「唯独…偏偏」，与本句不合。"]},
]},
{"id":"b1-33","typeKey":"bun1","title":"模拟㉝ 条件・列挙の型","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"品物が悪い＿＿値段が高い＿＿、文句ばかりだ。","options":["につけ　につけ","やら　やら","だの　だの","といい　といい"],"answer":2,"explain":["【近义混同】「〜につけ〜につけ」表示「每逢…就」，与本句不合。","【近义混同】「〜やら〜やら」表示纷杂列举（中性），不承载不满的语气。","正解。「〜だの〜だの」表示「…啦…啦（列举不满）」，与「牢骚不断」契合。","【近义混同】「〜といい〜といい」表示并列评价，与本句的抱怨不合。"]},
{"label":"近义辨析","q":"部屋は本＿＿服＿＿で散らかり放題だ。","options":["につけ　につけ","だの　だの","といい　といい","やら　やら"],"answer":3,"explain":["【近义混同】「〜につけ〜につけ」表示「每逢…就」，与本句不合。","【近义混同】「〜だの〜だの」表示列举不满（牢骚），与杂乱的中性列举不合。","【近义混同】「〜といい〜といい」表示并列评价，与本句不合。","正解。「〜やら〜やら」表示「又是…又是…（纷杂列举）」，与「乱成一团」契合。"]},
{"label":"近义辨析","q":"賛成＿＿反対＿＿、まず意見を述べるべきだ。","options":["であれ　であれ","だの　だの","やら　やら","といい　といい"],"answer":0,"explain":["正解。「〜であれ〜であれ」表示「无论…还是…（都）」，与「先表态」的全面让步契合。","【近义混同】「〜だの〜だの」表示列举不满（牢骚），与本句的郑重建议不合。","【近义混同】「〜やら〜やら」表示纷杂列举，与本句不合。","【近义混同】「〜といい〜といい」表示并列评价，与本句的让步不合。"]},
{"label":"呼应制约","q":"考えれば考える＿＿、分からなくなる。","options":["につけ","ほど","うちに","そばから"],"answer":1,"explain":["【近义混同】「〜につけ」表示「每逢…就」，与本句的比例变化不合。","正解。「〜ば〜ほど」表示「越…越…」，ば形＋辞书形＋ほど是固定呼应。","【近义混同】「〜うちに」表示「在…期间」，与本句的增减联动不合。","【近义混同】「〜そばから」表示「刚…就（被抵消）」，与本句不合。"]},
{"label":"近义辨析","q":"練習する＿＿、上達はない。","options":["ことか","ことだから","ことなしに","こととて"],"answer":2,"explain":["【近义混同】「〜ことか」接疑问词表示感叹「多么…啊」，与本句不合。","【近义混同】「〜ことだから」前接人名词，表示对熟悉之人的推断，与本句不合。","正解。「〜ことなしに」接辞书形＋否定，表示「不…就（不）」，文语色彩与本句契合。","【近义混同】「〜こととて」表示「因为是…（辩解）」，须「の＋こととて」，与本句不合。"]},
]},
{"id":"b1-34","typeKey":"bun1","title":"模拟㉞ 義務・感情の残部","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"文末表现","q":"寝坊して式に遅刻するとは、まったくの赤面＿＿。","options":["どころではない","にすぎない","にほかならない","の至りだ"],"answer":3,"explain":["【近义混同】「〜どころではない」表示「哪里谈得上」，与本句不合。","【近义混同】「〜にすぎない」表示「不过是」的贬低，与本句的自嘲不合。","【近义混同】「〜にほかならない」表示「正是…」的强断定，与本句不合。","正解。「〜の至りだ」接名词，表示「…至极（自身的窘迫·感激）」，「赤面の至りだ」为固定表达。"]},
{"label":"近义辨析","q":"彼は飛び上がら＿＿喜んだ。","options":["んばかりに","んばかりだ","まじき","ごとくに"],"answer":0,"explain":["正解。「〜んばかりに」接未然形，表示「几乎要…地」，作连用修饰与「喜んだ」衔接。","【时态肯否错位】「〜んばかりだ」为结句形，后接「喜んだ」则接续断裂。","【接续不合】「〜まじき」作连体修饰（あるまじき行為），与本句不合。","【接续不合】「〜ごとく」表示比况「如…一般」，接续与本句的夸张情态不合。"]},
{"label":"近义辨析","q":"一目会いたい＿＿、片道三時間もかけた。","options":["だけあって","ばかりに","あまり","ことから"],"answer":1,"explain":["【近义混同】「〜だけあって」表示名实相符的称赞，与本句的极端行为不合。","正解。「〜たいばかりに」表示「只因太想…（引发极端行为）」，与「单程三小时」的极端契合。","【接续不合】「〜のあまり」须「の＋あまり」（会いたいのあまり），本句空格不含の。","【近义混同】「〜ことから」表示客观缘由，与本句的个人执着不合。"]},
{"label":"近义辨析","q":"その姿を見ると、笑わない＿＿。","options":["ではおかない","ではすまない","ではいられない","ざるを得ない"],"answer":2,"explain":["【近义混同】「〜ないではおかない」表示「必然引起／不…不罢休」，与本句的自发情感不合。","【近义混同】「〜ないではすまない」表示「不…就过意不去（义务）」，与本句的冲动不合。","正解。「〜ないではいられない」表示「禁不住（感情冲动）」，与「忍不住笑」契合。","【近义混同】「〜ざるを得ない」表示「迫于外部不得不」，与本句的内心冲动不合。"]},
{"label":"近义辨析","q":"悪いと知っているなら、謝らない＿＿。","options":["どころではない","ではいられない","ではおかない","ではすまない"],"answer":3,"explain":["【近义混同】「〜どころではない」表示「哪里谈得上」，与本句不合。","【近义混同】「〜ないではいられない」表示「禁不住（感情冲动）」，与本句的义务不合。","【近义混同】「〜ないではおかない」表示「必然引起」，与本句的义务不合。","正解。「〜ないではすまない」表示「不…就过意不去（社会义务）」，与「有错须道歉」契合。"]},
]},
{"id":"b1-35","typeKey":"bun1","title":"模拟㉟ 複合助詞の残部①","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"幾多の困難＿＿、ついに大橋は完成した。","options":["を経て","をもって","をはじめ","をめぐって"],"answer":0,"explain":["正解。「〜を経て」表示「经过…（到达终点）」，与「历经困难终建成」契合。","【近义混同】「〜をもって」表示「以…（手段·时限）」，与本句的经过不合。","【接续不合】「〜をはじめ」表示「以…为首（列举）」，与本句不合。","【接续不合】「〜をめぐって」表示「围绕…（争论）」，与本句不合。"]},
{"label":"近义辨析","q":"先生のご指導＿＿、三年間研究を続けた。","options":["をこめて","のもとで","に沿って","をもって"],"answer":1,"explain":["【近义混同】「〜をこめて」表示「满怀…（情感）」，与本句不合。","正解。「〜のもとで」表示「在…之下」，与「在指导下研究」契合。","【近义混同】「〜に沿って」表示「遵循…（方针）」，与本句不合。","【近义混同】「〜をもって」表示「以…（手段·时限）」，与本句不合。"]},
{"label":"近义辨析","q":"彼の才能と幸運＿＿、大成功を収めた。","options":["において","とともに","と相まって","にかけて"],"answer":2,"explain":["【接续不合】「〜において」表示「在…（场所·领域）」，与本句不合。","【近义混同】「〜とともに」表示「与…同时·随着」，与本句的相乘效果不合。","正解。「〜と（が）相まって」表示「与…相辅相成（效果加剧）」，与「才能加幸运造就成功」契合。","【近义混同】「〜にかけて」表示「覆盖（范围）」，与本句不合。"]},
{"label":"近义辨析","q":"退職した部長＿＿、私が担当いたします。","options":["に比べて","にとって","に応じて","にかわって"],"answer":3,"explain":["【近义混同】「〜に比べて」表示「与…相比」，与本句不合。","【近义混同】「〜にとって」表示「对…而言」的评价角度，与本句不合。","【近义混同】「〜に応じて」表示「根据…相应变化」，与本句不合。","正解。「〜にかわって」表示「代替…（接任）」，与「接替退休部长」契合。"]},
{"label":"近义辨析","q":"慣例＿＿、式を執り行った。","options":["に則って","に沿って","に基づいて","に鑑み"],"answer":0,"explain":["正解。「〜に則って」表示「依照（惯例·先例）」，「慣例に則って」为固定搭配。","【近义混同】「〜に沿って」表示「遵循…（方针·指示）」，与惯例的沿袭义有别。","【近义混同】「〜に基づいて」表示「基于…（事实·数据）」，与惯例不同。","【接续不合】「〜に鑑み」表示「鉴于…（缘由）」，与本句的依照不合。"]},
]},
{"id":"b1-36","typeKey":"bun1","title":"模拟㊱ 複合助詞の残部②","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"彼の実力＿＿、一人では解決できなかった。","options":["において","をもってしても","に限らず","をこめて"],"answer":1,"explain":["【接续不合】「〜において」表示「在…（场所·领域）」，与本句的让步不合。","正解。「〜をもってしても」表示「即便凭借…也（不）」，与「即使有实力也难解决」契合。","【近义混同】「〜に限らず」表示「不限于…」，与本句不合。","【近义混同】「〜をこめて」表示「满怀…（情感）」，与本句不合。"]},
{"label":"近义辨析","q":"この不況下＿＿、利益を伸ばした。","options":["に限って","においても","にあって","をめぐって"],"answer":2,"explain":["【近义混同】「〜に限って」表示「唯独…偏偏」，与本句相反。","【近义混同】「〜においても」表示「在…也（场所）」，与处境义有差。","正解。「〜にあって」表示「处于…（之中）」，书面体，与「身处不景气仍增收」契合。","【接续不合】「〜をめぐって」表示「围绕…」，与本句不合。"]},
{"label":"近义辨析","q":"危険＿＿、火の中へ飛び込んだ。","options":["を問わず","をよそに","をものともせず","を顧みず"],"answer":3,"explain":["【接续不合】「〜を問わず」表示「不分…（并列范畴）」，与本句不合。","【近义混同】「〜をよそに」表示「无视（外界的反对·期待）」，不用于自身安危。","【近义混同】「〜をものともせず」表示「不把…放在眼里」的强者姿态，与「奋不顾身」的义理有别。","正解。「〜を顧みず」表示「不顾…（自身安危）」，与「冲进火海」契合。"]},
{"label":"近义辨析","q":"理由のいかん＿＿、遅刻は認められない。","options":["にかかわらず","にもかかわらず","を問わず","にもとづかず"],"answer":0,"explain":["正解。「〜のいかんにかかわらず」表示「不论…与否（公文语）」，与「无论理由」的公文体契合。","【近义混同】「〜にもかかわらず」表示「尽管…却」，与本句的公文让步不合。","【接续制约】「〜を問わず」须接并列范畴（昼夜を問わず），「いかん」不可。","【接续不合】「〜にもとづかず」非固定文型，与本句不合。"]},
{"label":"近义辨析","q":"これは会社の存続＿＿問題だ。","options":["にとっての","に関わる","による","に基づく"],"answer":1,"explain":["【接续不合】「〜にとっての」表示「对…而言的」，与本句的利害关系不合。","正解。「〜に関わる」表示「关系到…（存亡）」，与「事关存亡」契合。","【近义混同】「〜による」表示「由…（引起·进行）」，与本句的利害不合。","【近义混同】「〜に基づく」表示「基于…（依据）」，与本句不合。"]},
]},
{"id":"b1-37","typeKey":"bun1","title":"模拟㊲ 原因・理由の残部","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"週末ということも＿＿、店は大混雑だった。","options":["ばかりに","とあって","あって","ことから"],"answer":2,"explain":["【近义混同】「〜ばかりに」表示负面归因，与「客流盛况」相反。","【接续不合】「〜とあって」与「ということもあって」的既定搭配不可互换。","正解。「〜もあって」表示「也因为…（原因之一）」，「ということもあって」为惯用呼应。","【近义混同】「〜ことから」表示命名的客观缘由，与本句不合。"]},
{"label":"近义辨析","q":"慣れない土地のこと＿＿、道に迷ってしまった。","options":["ゆえに","だから","ばかりに","とて"],"answer":3,"explain":["【接续不合】「〜ゆえに」直接接名词，「のことゆえに」不成立。","【接续不合】「〜だから」为口语接续，「のことだから」前接人名词表推断。","【接续不合】「〜ばかりに」接た形·な形，与本句的名词接续不合。","正解。「〜こととて」表示「因为是…（所以，书面辩解）」，「慣れない土地のこととて」为其典型形态（「とて」承接「こととて」的省略形）。"]},
{"label":"近义辨析","q":"隣の犬＿＿、昼夜鳴いてうるさい。","options":["ときたら","にとって","とあって","にしては"],"answer":0,"explain":["正解。「〜ときたら」表示「说起…（抱怨的话题）」，与「抱怨狗吠」的语感契合。","【近义混同】「〜にとって」表示「对…而言」，与本句的抱怨不合。","【近义混同】「〜とあって」表示「因为处于特殊状况」，与本句不合。","【近义混同】「〜にしては」表示「与预期相比」的评价，与本句不合。"]},
{"label":"近义辨析","q":"夜更かしが続いた＿＿、朝起きられなくなった。","options":["おかげで","せいで","ばかりに","だけあって"],"answer":1,"explain":["【近义混同】「〜おかげで」表示得益于（正面），方向相反。","正解。「〜せいで」表示「都怪…（归咎负面原因）」，与「熬夜致早起不能」契合。","【近义混同】「〜ばかりに」重「只因…（一次极端归因）」，惯常行为的归咎宜用「せいで」。","【近义混同】「〜だけあって」表示名实相符，与本句相反。"]},
{"label":"近义辨析","q":"形が手のひらに似ている＿＿、「手のひら島」と呼ばれている。","options":["せいで","だけあって","ことから","あまり"],"answer":2,"explain":["【近义混同】「〜せいで」表示归咎负面原因，与本句不合。","【近义混同】「〜だけあって」表示名实相符的称赞，与本句的命名依据不合。","正解。「〜ことから」表示客观缘由，是「由来源命名」的典型用法。","【接续不合】「〜のあまり」前接感情名词，接续不合。"]},
]},
{"id":"b1-38","typeKey":"bun1","title":"模拟㊳ 接続詞・文脈の型","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"接续词","q":"三日間雨が続いた。＿＿、祭りは予定どおり開かれた。","options":["なぜなら","そのため","つまり","しかし"],"answer":3,"explain":["【文脉断裂】「なぜなら」引出理由，后句须接「からだ」。","【文脉断裂】「そのため」表示因果，雨与如期举行之间无因果关系。","【文脉断裂】「つまり」表示要约，与前后的概括关系不合。","正解。「しかし」表示逆接，与前句「连雨」和后句「如期举行」的转折契合。"]},
{"label":"接续词","q":"彼は朝三時間、夜三時間勉強した。＿＿、一日六時間だ。","options":["つまり","しかし","ただし","ところが"],"answer":0,"explain":["正解。「つまり」表示要约换算，与前句的合计契合。","【文脉断裂】「しかし」表示逆接，两句间无转折。","【文脉断裂】「ただし」表示附加限制（但书），与本句不合。","【文脉断裂】「ところが」表示意外逆接，与本句不合。"]},
{"label":"接续词","q":"引っ越すことにした。＿＿、職場が遠くなるからだ。","options":["そのため","なぜなら","すると","そもそも"],"answer":1,"explain":["【文脉断裂】「そのため」表示前句引发的结果，与本句的理由说明不合。","正解。「なぜなら」引出理由，与后句「からだ」的呼应是固定结构。","【文脉断裂】「すると」表示承接（于是），与本句不合。","【文脉断裂】「そもそも」表示追根溯源，与本句的理由不合。"]},
{"label":"接续词","q":"図書館は誰でも利用できる。＿＿、貸出は会員に限る。","options":["つまり","しかし","ただし","ところが"],"answer":2,"explain":["【文脉断裂】「つまり」表示要约，与本句不合。","【近义混同】「しかし」表示全面转折，与「补充例外」的但书义不合。","正解。「ただし」表示附加限制（但书），与「开放但外借受限」契合。","【文脉断裂】「ところが」表示意外逆接，与本句的但书不合。"]},
{"label":"接续词","q":"必ず来ると言っていた。＿＿、来なかった。","options":["そのため","すると","つまり","ところが"],"answer":3,"explain":["【文脉断裂】「そのため」表示因果，与本句不合。","【文脉断裂】「すると」表示承接（于是发生新事），与本句的违背预期不合。","【文脉断裂】「つまり」表示要约，与本句不合。","正解。「ところが」表示「可是（结果出乎意料）」，与「说好却没来」的意外契合。"]},
]},
{"id":"b1-39","typeKey":"bun1","title":"模拟㊴ 接続詞の型（第二弾）","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"接续词","q":"事故で線路が塞がれた。＿＿、全線で運転を見合わせた。","options":["そのため","ただし","ところが","なぜなら"],"answer":0,"explain":["正解。「そのため」表示因果推进，与「事故→停运」的因果链契合。","【文脉断裂】「ただし」表示但书，与本句的因果不合。","【文脉断裂】「ところが」表示意外逆接，与本句的顺承因果不合。","【文脉断裂】「なぜなら」后须接「からだ」的说明。"]},
{"label":"接续词","q":"値上げが続いた。＿＿、客足は減らなかった。","options":["そのため","それでも","つまり","すると"],"answer":1,"explain":["【文脉断裂】「そのため」表示因果，与「未减」的方向相反。","正解。「それでも」表示「即便如此」，与「涨价客流未减」的让步契合。","【文脉断裂】「つまり」表示要约，与本句不合。","【文脉断裂】「すると」表示承接，与本句的逆接不合。"]},
{"label":"接续词","q":"この計画、＿＿無理があったのではないか。","options":["ただし","もっとも","そもそも","つまり"],"answer":2,"explain":["【文脉断裂】「ただし」表示但书，与本句不合。","【近义混同】「もっとも」表示附加理由的保留（不过），与本句的回溯不合。","正解。「そもそも」表示「说到底（追根溯源）」，与「计划本身有硬伤」的回溯质疑契合。","【文脉断裂】「つまり」表示要约，与本句的质疑不合。"]},
{"label":"接续词","q":"彼は、＿＿「会社に生きる」人生を選んだのだ。","options":["もっとも","すると","それでも","言い換えれば"],"answer":3,"explain":["【文脉断裂】「もっとも」表示保留（不过），与本句不合。","【文脉断裂】「すると」表示承接，与本句的换述不合。","【文脉断裂】「それでも」表示让步，与本句不合。","正解。「言い換えれば」表示「换言之（换述）」，与同一内涵的重新表述契合。"]},
{"label":"接续词","q":"十年住んでいる。＿＿、方言が下手だ。","options":["それにしては","それでも","そこで","つまり"],"answer":0,"explain":["正解。「それにしては」表示「就…而言却（预期落差）」，与「住十年却方言差」契合。","【近义混同】「それでも」表示让步（即便如此），与本句的落差评价不合。","【文脉断裂】「そこで」表示于是·转换话题，与本句不合。","【文脉断裂】「つまり」表示要约，与本句不合。"]},
]},
{"id":"b1-40","typeKey":"bun1","title":"模拟㊵ 敬語の残部","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"敬語","q":"ご意見は喜んで＿＿。","options":["お聞きになります","承ります","申し上げます","拝見いたします"],"answer":1,"explain":["【敬語误用】「お聞きになる」是尊敬语（对方听），方向相反。","正解。「承る」是「受け賜る」的谦让语，与「恭听意见」的商务书函契合。","【敬語误用】「申し上げる」是「言う」的谦让语（我方说），与「听」不合。","【近义混同】「拝見する」是「看」的谦让语，与「听意见」不合。"]},
{"label":"敬語","q":"先生にわかりやすく解説して＿＿。","options":["さしあげました","くださりました","いただきました","なさいました"],"answer":2,"explain":["【敬語误用】「〜てさしあげる」表示「我方为对方做」，方向相反。","【敬語误用】「〜てくださる」须以「先生が」为主语，与「先生に」不合。","正解。「〜ていただく」表示「承蒙（先生为我）做…」，与「先生に」的授受方向契合。","【敬語误用】「〜なさる」是尊敬语（对方做），与谦让语境不合。"]},
{"label":"敬語","q":"受付は二階＿＿。","options":["でなさいます","でいらっしゃいます","でおります","でございます"],"answer":3,"explain":["【敬語误用】「〜なさる」是尊敬语，与本句不合。","【敬語误用】「〜でいらっしゃる」是尊敬语（人的存在），不用于场所。","【敬語误用】「〜ておる」是「ている」的谦让语，接续不合。","正解。「〜でございます」是「です」的郑重语，用于场所·事物的郑重说明。"]},
{"label":"敬語","q":"私は毎日、店番を＿＿。","options":["しております","していらっしゃいます","してくださいます","してさしあげます"],"answer":0,"explain":["正解。「〜ておる」是「ている」的谦让语，用于陈述己方行为。","【敬語误用】「〜ていらっしゃる」是尊敬语（对方正在…），方向相反。","【敬語误用】「〜てくださる」表示「对方为我做」，方向相反。","【敬語误用】「〜てさしあげる」表示「我为对方做（施恩）」，与日常店务不合。"]},
{"label":"敬語","q":"先生は教室に＿＿。","options":["伺いました","いらっしゃいました","お目にかかりました","まいりました"],"answer":1,"explain":["【敬語误用】「伺う」是谦让语（我方去·问），方向相反。","正解。「いらっしゃる」是「行く·来る·いる」的尊敬语，与主语「先生」契合。","【敬語误用】「お目にかかる」是「会面」的谦让语（我方拜见），方向相反。","【敬語误用】「まいる」是「行く·来る」的谦让语（我方），方向相反。"]},
]},
{"id":"b1-41","typeKey":"bun1","title":"模拟㊶ 呼応の型","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"呼应制约","q":"＿＿何もなかったかのように振る舞っていた。","options":["あまり","たとえ","まるで","もし"],"answer":2,"explain":["【呼应冲突】「あまり」与否定呼应表示「过度…」，与本句不合。","【呼应冲突】「たとえ」与「〜ても／としても」呼应，与本句的比况不合。","正解。「まるで〜かのように」表示「仿佛…一般」，与「装作无事」的比况契合。","【呼应冲突】「もし」与条件句呼应，与本句的比况不合。"]},
{"label":"呼应制约","q":"＿＿合格できないとしても、最後まで戦おう。","options":["決して","まるで","あまり","たとえ"],"answer":3,"explain":["【呼应冲突】「決して」与否定呼应表示全面否定，与本句的让步不合。","【呼应冲突】「まるで」与比况呼应，与本句的让步不合。","【呼应冲突】「あまり」与否定呼应，与本句不合。","正解。「たとえ〜としても」表示「即便…也」，让步呼应与「戦おう」契合。"]},
{"label":"呼应制约","q":"彼は＿＿自分の過ちを認めようとしない。","options":["決して","必ずしも","たとえ","あまり"],"answer":0,"explain":["正解。「決して〜ない」表示「决不（全面否定）」，与「拒不认错」契合。","【呼应冲突】「必ずしも〜ない」表示「未必（部分否定）」，与本句的全面否定不合。","【呼应冲突】「たとえ」与让步呼应，与本句不合。","【呼应冲突】「あまり」与程度否定呼应，与本句的意志否定不合。"]},
{"label":"呼应制约","q":"値段が高いものが＿＿いいとは限らない。","options":["決して","必ずしも","まるで","たとえ"],"answer":1,"explain":["【呼应冲突】「決して〜ない」为全面否定，与「部分否定」的「とは限らない」不合。","正解。「必ずしも〜ない」表示「未必（部分否定）」，与「〜とは限らない」固定呼应。","【呼应冲突】「まるで」与比况呼应，与本句不合。","【呼应冲突】「たとえ」与让步呼应，与本句不合。"]},
{"label":"呼应制约","q":"＿＿無理をすると、体を壊すよ。","options":["たとえ","決して","あまり","まるで"],"answer":2,"explain":["【呼应冲突】「たとえ」与让步呼应，本句无条件让步。","【呼应冲突】「決して」与否定呼应，本句无否定。","正解。「あまり〜と」表示「过度…的话（会）」，与「过劳伤身」的告诫契合。","【呼应冲突】「まるで」与比况呼应，本句无比况。"]},
]},
{"id":"b1-42","typeKey":"bun1","title":"模拟㊷ 変化・傾向の第三弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"この十年、都会の人口は減る＿＿。","options":["がちだ","ばかりだ","つつある","一方だ"],"answer":3,"explain":["【接续制约】「〜がち」接ます形（減りがち），接辞书形不成立。","【近义混同】「〜ばかりだ」重「越发（负面感叹）」的语感，单纯的方向性持续惯用「一方だ」。","【近义混同】「〜つつある」表示「变化途中（渐进）」，与本句的总量趋势表述有别。","正解。「〜一方だ」接辞书形，表示「不断地朝一个方向变化」，与人口的持续减少契合。"]},
{"label":"近义辨析","q":"彼のいたずらがエスカレートすれば、大けがにつながり＿＿。","options":["かねない","かねる","がたい","えない"],"answer":0,"explain":["正解。「〜かねない」接ます形，表示「很可能（酿成坏事）」，与「恐致重伤」的警告契合。","【近义混同】「〜かねる」表示「难以（婉拒）」，方向相反。","【近义混同】「〜がたい」表示「心理上难以」，与本句的可能性不合。","【近义混同】「〜えない」表示「不可能」，与本句相反。"]},
{"label":"文末表现","q":"その要求には応じ＿＿。","options":["かねません","かねます","えます","がたいです"],"answer":1,"explain":["【近义混同】「〜かねない」表示「很可能（坏事）」，与本句的婉拒相反。","正解。「〜かねる」表示「难以…（婉拒）」，「応じかねます」是商务场合的固定婉拒表达。","【近义混同】「〜える」表示「可能」，与本句相反。","【近义混同】「〜がたい」表示「难以」的书面评价，「応じかねます」为商务惯用形。"]},
{"label":"近义辨析","q":"彼は最近、会議を休み＿＿だ。","options":["げ","気味","がち","まみれ"],"answer":2,"explain":["【接续不合】「〜げ」表示神情，接续与本句不合。","【近义混同】「〜気味」表示「略带…的当下状态」，与本句的频度不合。","正解。「〜がち」表示「经常、动辄」的频度倾向，与「时常缺席」契合。","【接续不合】「〜まみれ」表示「沾满（液体·粉末）」，接续与语义均不合。"]},
{"label":"近义辨析","q":"彼は最近、忘れ＿＿になってきた。","options":["まみれ","げ","気味","っぽい"],"answer":3,"explain":["【接续不合】「〜まみれ」表示「沾满」，接续与语义均不合。","【接续不合】「〜げ」表示神情，接续与本句的倾向不合。","【近义混同】「〜気味」表示「略带…的当下状态」，与本句的性格倾向不合。","正解。「〜っぽい」接ます形，表示「容易…」，「忘れっぽい」为固定表达。"]},
]},
{"id":"b1-43","typeKey":"bun1","title":"模拟㊸ 契約・時点の第三弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"詳細が分かり＿＿、ご連絡いたします。","options":["次第","次第で","かと思うと","たびに"],"answer":0,"explain":["正解。「〜次第」接ます形，表示「一…立刻（随即做）」，商务承诺的固定表达。","【接续不合】「〜次第で」接名词表示「全凭…」，接续与语义均不合。","【接续不合】「〜かと思うと」须た形（分かったかと思うと）。","【近义混同】「〜たびに」表示「每当…就」的反复习惯，非郑重承诺。"]},
{"label":"近义辨析","q":"長時間悩んだ＿＿、申し込みを取り消した。","options":["うえで","あげく","に先立って","ばかりに"],"answer":1,"explain":["【近义混同】「〜うえで」表示「在…之后再做下一步」的中性先后，无消极色彩。","正解。「〜あげく」接た形，表示「…的结果（多消极收场）」，与「取消报名」契合。","【近义混同】「〜に先立って」表示「在…之前」，与本句相反。","【近义混同】「〜ばかりに」表示「只因…（极端归因）」，与本句的收场义不合。"]},
{"label":"近义辨析","q":"協議を重ねた＿＿、ついに合意に至った。","options":["たびに","あげく","末に","に至るまで"],"answer":2,"explain":["【近义混同】「〜たびに」表示「每当…就」，与本句的一次性达成不合。","【近义混同】「〜あげく」带消极收场色彩，与「合意」的积极结果不合。","正解。「〜末(に)」接た形，表示「经过…最终（中性）」，与「达成积极合意」契合。","【近义混同】「〜に至るまで」表示「直到…（范围极限）」，与本句不合。"]},
{"label":"近义辨析","q":"両親と相談した＿＿、進学を決めた。","options":["に先立って","あげく","からには","うえで"],"answer":3,"explain":["【近义混同】「〜に先立って」表示「在…之前」，先后关系相反。","【近义混同】「〜あげく」表示消极收场，与本句的中性先后不合。","【接续制约】「〜からには」接辞书形（相談するからには），接续不合且表义务。","正解。「〜たうえで」表示「在…之后（再进行下一步）」，与「商量之后再决定」契合。"]},
{"label":"接续制约","q":"会長が退室する＿＿、報道陣が詰め寄った。","options":["や否や","なり","とたん","そばから"],"answer":0,"explain":["正解。「〜や否や」接辞书形，表示「一…立刻（书面，主语可不同）」，与「会长刚退场记者围上」契合。","【近义混同】「〜なり」表示同一主体紧接着的动作，此处主体已换成报道陣。","【接续不合】「〜たとたん」须た形（退室したとたん）。","【近义混同】「〜そばから」表示「刚…就（被抵消）」的徒劳反复，与本句不合。"]},
]},
{"id":"b1-44","typeKey":"bun1","title":"模拟㊹ 契約・時点の第四弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"接续制约","q":"ベルが鳴った＿＿、彼は教室を飛び出した。","options":["や否や","かと思うと","なり","ばかりに"],"answer":1,"explain":["【接续不合】「〜や否や」须辞书形（鳴るや否や）。","正解。「〜たかと思うと」接た形，表示「刚…就（出乎说话人意料）」。","【接续不合】「〜なり」须辞书形（鳴るなり）。","【接续不合】「〜ばかりに」表归因，接续与语义均不合。"]},
{"label":"近义辨析","q":"彼は三十＿＿、自社を立ち上げた。","options":["にとって","において","にして","に限って"],"answer":2,"explain":["【近义混同】「〜にとって」表示「对…而言」的评价角度，与本句不合。","【近义混同】「〜において」表示「在…（场所·领域）」，与本句的年龄阶段不合。","正解。「〜にして」接时点·年龄，表示「在…阶段（竟／才）」，与「三十岁便创业」的强调契合。","【近义混同】「〜に限って」表示「唯独…偏偏」，与本句不合。"]},
{"label":"近义辨析","q":"片付ける＿＿散らかされて、母はため息ばかりだ。","options":["につけ","たびに","うちに","そばから"],"answer":3,"explain":["【近义混同】「〜につけ」表示「每逢…就（情感涌起）」，与本句不合。","【近义混同】「〜たびに」表示中性的反复习惯，缺「徒劳被抵消」的语感。","【近义混同】「〜うちに」表示「在…期间（趁着）」，与本句不合。","正解。「〜そばから」表示「刚…就（被抵消）」的徒劳反复，与「白收拾」的无奈契合。"]},
{"label":"近义辨析","q":"退職して＿＿、毎朝釣りに出かけている。","options":["てからというもの","てから","たびに","たとたん"],"answer":0,"explain":["正解。「〜てからというもの」表示「自从…之后（一直）」，强调持续的状态变化。","【近义混同】「〜てから」仅表动作的先后顺序，无「自那以后一直」的强调。","【近义混同】「〜たびに」表示「每当…就」，与本句的持续不合。","【近义混同】「〜たとたん」表示「刚一…就（一次性突发）」，与本句的持续习惯不合。"]},
{"label":"近义辨析","q":"君の努力＿＿、結果は変わる。","options":["次第","次第で","のおかげで","に限らず"],"answer":1,"explain":["【接续不合】「〜次第」接ます形表示「一…立刻」，接名词不成立。","正解。「〜次第で」接名词，表示「全凭…、取决于…」，与「结果因努力而变」契合。","【近义混同】「〜のおかげで」表示得益于（正面归因），与本句的条件关系不合。","【近义混同】「〜に限らず」表示「不限于…」，与本句不合。"]},
]},
{"id":"b1-45","typeKey":"bun1","title":"模拟㊺ 原因・理由の第三弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"時間に厳しい彼の＿＿、遅れることはない。","options":["ときたら","ことから","ことだから","だけあって"],"answer":2,"explain":["【接续不合】「〜ときたら」直接接名词，「彼の＋ときたら」不成立。","【近义混同】「〜ことから」表示客观缘由（多用于命名·依据），不用于对人的推断。","正解。「〜のことだから」前接人名词，表示「因为是…（对熟悉之人的推断）」。","【近义混同】「〜だけあって」表示名实相符的称赞，与本句的推断不合。"]},
{"label":"近义辨析","q":"さすが一流ホテル＿＿。","options":["どころではない","にすぎない","にほかならない","だけのことはある"],"answer":3,"explain":["【近义混同】「〜どころではない」表示「哪里谈得上」，与本句相反。","【近义混同】「〜にすぎない」表示「不过是」的贬低，与本句相反。","【近义混同】「〜にほかならない」表示「正是…」的强断定，与本句的感叹不合。","正解。「〜だけのことはある」表示「果然名不虚传」，与「さすが」呼应表示实力相称。"]},
{"label":"近义辨析","q":"甘いものばかり食べている＿＿、最近体重が増えた。","options":["せいで","おかげで","だけあって","ことから"],"answer":0,"explain":["正解。「〜せいで」表示「都怪…（归咎负面原因）」，与「体重增加」的抱怨契合。","【近义混同】「〜おかげで」表示得益于（正面归因），方向相反。","【近义混同】「〜だけあって」表示名实相符，与本句不合。","【近义混同】「〜ことから」表示客观缘由，与本句的归咎不合。"]},
{"label":"近义辨析","q":"心配の＿＿、眠れなくなってしまった。","options":["ばかりに","あまり","だけあって","ことから"],"answer":1,"explain":["【接续不合】「〜ばかりに」接た形·な形，接「心配の」不成立。","正解。「〜のあまり」前接感情·状态名词，表示「因过分…而」引发极端状态。","【近义混同】「〜だけあって」表示名实相符，与本句不合。","【接续不合】「〜ことから」接句子的普通形，「心配のことから」不成立。"]},
{"label":"近义辨析","q":"うそをついた＿＿、彼女に嫌われてしまった。","options":["おかげで","だけあって","ばかりに","ことから"],"answer":2,"explain":["【近义混同】「〜おかげで」表示得益于，方向相反。","【近义混同】「〜だけあって」表示名实相符，与本句相反。","正解。「〜ばかりに」接た形，表示「只因…（引发极端负面结果）」，与「一句谎话被讨厌」的悔恨契合。","【近义混同】「〜ことから」表示客观缘由，与本句不合。"]},
]},
{"id":"b1-46","typeKey":"bun1","title":"模拟㊻ 逆接・让步の第三弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"接续制约","q":"予約はした＿＿、来られなくなった。","options":["がてら","つつも","ながらも","ものの"],"answer":3,"explain":["【接续不合】「〜がてら」接ます形表示「顺便」，与本句的逆接不合。","【接续不合】「〜つつも」接ます形（予約しつつも），接た形不成立。","【接续不合】「〜ながらも」接ます形·名词，接た形不成立。","正解。「〜ものの」接た形，表示「虽然…但是」，与「订了却来不了」契合。"]},
{"label":"接续制约","q":"小さい会社＿＿、技術力には定評がある。","options":["ながらも","ものの","つつも","わりには"],"answer":0,"explain":["正解。「〜ながらも」接名词，表示「虽然…但是」，与「公司虽小却有名」契合。","【接续不合】「〜ものの」须た形·である（会社であるものの），直接接な形容词不成立。","【接续不合】「〜つつも」接ます形，接续不合。","【接续不合】「〜わりには」接名词の（値段のわりには），接续与语义均不合。"]},
{"label":"近义辨析","q":"確かに値段は高い。＿＿、品質は保証されている。","options":["といっても","とはいうものの","というものだ","とは"],"answer":1,"explain":["【近义混同】「〜といっても」对同句内容打折扣，不用于承接前句的书面让步。","正解。「〜とはいうものの」承接前句并部分推翻，与「贵是贵但品质有保证」契合。","【近义混同】「〜というものだ」表示「这才真是」的断言，与本句不合。","【近义混同】「〜とは」表示惊愕（句尾省略），与本句不合。"]},
{"label":"近义辨析","q":"有名だから＿＿、いいとは限らない。","options":["からして","からには","からといって","にしては"],"answer":2,"explain":["【近义混同】「〜からして」表示「从…来看（判断依据）」，与本句的让步不合。","【近义混同】「〜からには」表示「既然…就（必须）」，与本句的让步不合。","正解。「〜からといって」表示「不能仅因…就」，与「〜とは限らない」的否定呼应契合。","【近义混同】「〜にしては」表示「与预期相比」的评价，与本句不合。"]},
{"label":"近义辨析","q":"大学教員の＿＿、コンサルタントも務める。","options":["反面","がてら","ながら","かたわら"],"answer":3,"explain":["【接续不合】「〜反面」接辞书形·である，接「教員の」不成立。","【接续不合】「〜がてら」接ます形（散歩がてら），接「教員の」不成立。","【接续不合】「〜ながら」接名词表示「保持…原状」（昔ながら），与本句不合。","正解。「〜かたわら」接名词の，表示「在从事本职的同时兼做…」，与「教员兼职顾问」契合。"]},
]},
{"id":"b1-47","typeKey":"bun1","title":"模拟㊼ 逆接・让步の第四弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"値段の＿＿、品質がいい。","options":["わりには","くせに","にしては","だけあって"],"answer":0,"explain":["正解。「〜わりには」接名词の，表示「与…程度相比并不相称」。","【近义混同】「〜くせに」表示「明明…却（指责）」，与本句的中性评价不合。","【接续不合】「〜にしては」直接接名词，「値段のにしては」不成立。","【近义混同】「〜だけあって」表示名实相符，与本句的「不符预期」相反。"]},
{"label":"近义辨析","q":"冬＿＿、暖かい日が続いている。","options":["にしても","にしては","わりには","に限って"],"answer":1,"explain":["【近义混同】「〜にしても」表示「即使…也」的让步，与本句的评价不合。","正解。「〜にしては」表示「与预期相比（按其身份却）」，与「冬天却暖和」契合。","【接续不合】「〜わりには」须「の＋わりには」，接续不合。","【近义混同】「〜に限って」表示「唯独…偏偏（消极意外）」，与本句不合。"]},
{"label":"近义辨析","q":"できない＿＿、偉そうに指図する。","options":["にしては","わりには","くせに","ものの"],"answer":2,"explain":["【近义混同】「〜にしては」表示客观评价，无谴责。","【近义混同】「〜わりには」表示「与程度不相称」的中性评价，无谴责。","正解。「〜くせに」表示「明明…却（指责）」，与「不会却瞎指挥」的谴责契合。","【接续不合】「〜ものの」须た形·である，接辞书形不成立。"]},
{"label":"近义辨析","q":"住民の反対＿＿、開発が進められた。","options":["にかかわらず","をものともせず","を顧みず","をよそに"],"answer":3,"explain":["【近义混同】「〜にかかわらず」表示「不论…」，与本句不合。","【近义混同】「〜をものともせず」表示「不把…放在眼里」的强者姿态，多接自身的困难。","【近义混同】「〜を顧みず」多接自身的安危·利益，不用于他人的意见。","正解。「〜をよそに」表示「无视（外界的声音·期待）」，与「无视反对推进开发」契合。"]},
{"label":"近义辨析","q":"昨年の不振＿＿、今年の活躍は目覚ましい。","options":["にひきかえ","に反して","に限って","に限らず"],"answer":0,"explain":["正解。「〜にひきかえ」接名词，表示「与…正相反（落差鲜明）」。","【近义混同】「〜に反して」接予想·期待·ルール，「昨年の不振に反して」不成立。","【近义混同】「〜に限って」表示「唯独…偏偏」，与本句不合。","【近义混同】「〜に限らず」表示「不限于…」，与本句不合。"]},
]},
{"id":"b1-48","typeKey":"bun1","title":"模拟㊽ 義務・感情の第四弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"一日も早い回復を願って＿＿。","options":["おかない","やまない","いられない","すまない"],"answer":1,"explain":["【接续不合】「〜(ず)にはおかない」接ない形，接续不合。","正解。「〜てやまない」接祈愿类动词て形，表示「衷心…不已」，书信贺词的惯用表达。","【接续不合】「〜(ず)にはいられない」接ない形，接续不合。","【接续不合】「〜(ず)にはすまない」接ない形，接续不合。"]},
{"label":"近义辨析","q":"その報道には驚きを＿＿。","options":["ものともせず","余儀なくされた","禁じ得なかった","かまわず"],"answer":2,"explain":["【近义混同】「〜をものともせず」表示「不把…放在眼里」，与本句相反。","【近义混同】「〜を余儀なくされる」表示被迫做某行为，不接情感名词。","正解。「〜を禁じ得ない」接情感名词＋を，表示「禁不住…」。","【接续不合】「〜もかまわず」接名词も，「驚きをかまわず」不成立。"]},
{"label":"近义辨析","q":"合格のお知らせをいただき、感激＿＿です。","options":["てやまない","に堪えない","きわまりない","の極み"],"answer":3,"explain":["【接续不合】「〜てやまない」接动词て形，「感激てやまない」不成立。","【接续制约】「〜に堪えない」多接消极情感（悲しみ），与「感激」不合。","【接续制约】「〜きわまりない」接な形容词词干表贬义评价，不接积极情感。","正解。「〜の極み」接情感名词，表示「…之极」，「感激の極みです」为书信·致辞的惯用表达。"]},
{"label":"近义辨析","q":"恩師の訃報に接し、悲しみ＿＿。","options":["に堪えない","きわまりない","にすぎない","てやまない"],"answer":0,"explain":["正解。「〜に堪えない」接消极情感名词，表示「不堪…」，「悲しみに堪えない」为标准搭配。","【接续制约】「〜きわまりない」接な形容词词干（失礼極まりない），不接「悲しみ」。","【近义混同】「〜にすぎない」表示「不过是」的贬低，与本句相反。","【接续不合】「〜てやまない」接祈愿类动词て形，「悲しみてやまない」不成立。"]},
{"label":"近义辨析","q":"彼の言い方は失礼＿＿。","options":["の至りだ","極まりない","に堪えない","ずにはすまない"],"answer":1,"explain":["【接续制约】「〜の至りだ」多接赤面·恐縮等特定名词，与「失礼」不合。","正解。「〜極まりない」接な形容词词干，表示「极其…（贬义评价）」。","【接续制约】「〜に堪えない」接消极情感名词，「失礼に堪えない」搭配不当。","【接续不合】「〜ずにはすまない」接动词ない形，「失礼ずにはすまない」不成立。"]},
]},
{"id":"b1-49","typeKey":"bun1","title":"模拟㊾ 変化・様態の第三弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"少しずつ変わり＿＿、今の形になった。","options":["ばかりだ","一方だ","つつある","がちだ"],"answer":2,"explain":["【近义混同】「〜ばかりだ」重「越发（负面感叹）」，与本句的中性过程不合。","【近义混同】「〜一方だ」表示单方向的加速变化，与「少しずつ」的渐进感不合。","正解。「〜つつある」接ます形，表示「变化正在渐进进行」，与「少しずつ」的过程呼应。","【接续制约】「〜がち」接ます形 stem（変わりがち），接续不合。"]},
{"label":"近义辨析","q":"彼は食べ＿＿のまま、居眠りを始めた。","options":["げ","がち","気味","かけ"],"answer":3,"explain":["【接续不合】「〜げ」表示神情，「食べげ」不成立。","【近义混同】「〜がち」表示频度倾向，与本句的中途状态不合。","【近义混同】「〜気味」表示「略带…状态」，与本句的中途不合。","正解。「〜かけ」接ます形，表示「开始…但未完成」，「食べかけのまま」为惯用表达。"]},
{"label":"近义辨析","q":"少し風邪＿＿だ。","options":["気味","がち","げ","っぽい"],"answer":0,"explain":["正解。「〜気味」接名词·ます形 stem，表示「略带…的当下状态」，「風邪気味」为惯用搭配。","【接续制约】「〜がち」接ます形 stem（ひきがち），「風邪がち」不成立。","【接续不合】「〜げ」表示神情，接续不合。","【接续不合】「〜っぽい」接ます形·名词表示倾向，「風邪っぽい」与本句的当下状态有别。"]},
{"label":"近义辨析","q":"冬は運動不足＿＿になる。","options":["気味","がち","っぽい","げ"],"answer":1,"explain":["【近义混同】「〜気味」表示当下略带的状态，与本句的季节倾向不合。","正解。「〜がち」接名词·ます形 stem，表示「经常处于某状态」，与冬天的惯常倾向契合。","【接续不合】「〜っぽい」接ます形表示性格倾向（忘れっぽい），「運動不足っぽい」不自然。","【接续不合】「〜げ」表示神情，接续不合。"]},
{"label":"近义辨析","q":"六十過ぎても、彼は年寄り＿＿ところがない。","options":["がち","げ","っぽい","気味"],"answer":2,"explain":["【接续不合】「〜がち」表示频度倾向，与本句的气质不合。","【接续不合】「〜げ」接形容词词干·ます形，接「年寄り」不成立。","正解。「〜っぽい」接名词，表示「有…的味道」，「年寄りっぽい」为惯用表达。","【接续不合】「〜気味」表示当下状态，接续与语义均不合。"]},
]},
{"id":"b1-50","typeKey":"bun1","title":"模拟㊿ 基準・経由の第三弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"アンケートの結果＿＿、新メニューを開発した。","options":["をめぐって","をきっかけに","に応じて","をもとに"],"answer":3,"explain":["【接续不合】「〜をめぐって」表示「围绕…（争论）」，与本句不合。","【近义混同】「〜をきっかけに」表示「以…为契机（转机）」，与本句的依据关系不合。","【近义混同】「〜に応じて」表示「根据…相应变化」，与本句不合。","正解。「〜をもとに」表示「以…为素材·参考」，与「据调查结果开发」契合。"]},
{"label":"近义辨析","q":"マニュアル＿＿操作してください。","options":["に沿って","に基づいて","に応じて","に即して"],"answer":0,"explain":["正解。「〜に沿って」表示「沿着…（规程·流程进行）」，「マニュアルに沿って」为固定搭配。","【近义混同】「〜に基づいて」重「依据事实·数据」，操作规程的沿袭用「に沿って」。","【近义混同】「〜に応じて」表示「根据…相应变化」，与本句不合。","【近义混同】「〜に即して」表示「紧扣现实·具体事例」，与本句不合。"]},
{"label":"近义辨析","q":"内輪のつて＿＿、仕事を紹介された。","options":["をはじめ","を通じて","をめぐって","にわたって"],"answer":1,"explain":["【接续不合】「〜をはじめ」表示「以…为首（列举）」，与本句不合。","正解。「〜を通じて」表示「经由…（中介）」，与「经熟人介绍」契合。","【接续不合】「〜をめぐって」表示「围绕…（争论）」，与本句不合。","【接续不合】「〜にわたって」表示范围持续，与本句不合。"]},
{"label":"近义辨析","q":"社長＿＿、社員全員が清掃に参加した。","options":["をこめて","を中心に","をはじめ","をもとに"],"answer":2,"explain":["【近义混同】「〜をこめて」表示「满怀…（情感）」，与本句不合。","【近义混同】「〜を中心に」表示「以…为核心（围绕其展开）」，与「全员并列参加」不合。","正解。「〜をはじめ」表示「以…为首（列举代表，含全体）」，与「全员参加」契合。","【近义混同】「〜をもとに」表示「以…为素材」，与本句不合。"]},
{"label":"近义辨析","q":"遺産相続＿＿、兄弟が争った。","options":["をもとに","を通じて","にわたって","をめぐって"],"answer":3,"explain":["【近义混同】「〜をもとに」表示「以…为素材」，与本句不合。","【近义混同】「〜を通じて」表示「经由…（中介）」，与本句不合。","【接续不合】「〜にわたって」表示范围持续，不接话题名词。","正解。「〜をめぐって」表示「围绕…（展开争论·对立）」，与「兄弟相争」契合。"]},
]},
{"id":"b1-51","typeKey":"bun1","title":"模拟51 基準・対応の第四弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"工事は一年＿＿続いた。","options":["にわたって","に伴って","につれて","に限って"],"answer":0,"explain":["正解。「〜にわたって」接期间名词，表示「持续…、跨越…」。","【近义混同】「〜に伴って」表示「伴随…（随之发生）」，与本句的持续不合。","【近义混同】「〜につれて」表示「随着…（自然联动）」，与本句不合。","【近义混同】「〜に限って」表示「唯独…偏偏」，与本句不合。"]},
{"label":"近义辨析","q":"人口の増加＿＿、住宅需要が高まった。","options":["に応じて","に伴って","に限り","に先立って"],"answer":1,"explain":["【近义混同】「〜に応じて」表示「根据…相应调整（政策性）」，与本句的自然联动不合。","正解。「〜に伴って」表示「伴随…（大规模·书面）」，与「人口增加带动需求」契合。","【接续不合】「〜に限り」表示「仅限于…」，与本句不合。","【近义混同】「〜に先立って」表示「在…之前」，与本句的联动不合。"]},
{"label":"近义辨析","q":"時間がたつ＿＿、悲しみは薄らいでいった。","options":["に限り","に応じて","につれて","に先立って"],"answer":2,"explain":["【接续不合】「〜に限り」表示「仅限于…」，与本句不合。","【近义混同】「〜に応じて」表示政策性的相应调整，与本句的自然变化不合。","正解。「〜につれて」表示「随着…（个人的自然变化）」，与情感淡化契合。","【近义混同】「〜に先立って」表示「在…之前」，与本句不合。"]},
{"label":"近义辨析","q":"先生の指示＿＿、実験を進めた。","options":["に限って","に応じて","に基づいて","にしたがって"],"answer":3,"explain":["【接续不合】「〜に限って」表示「唯独…偏偏」，与本句不合。","【近义混同】「〜に応じて」表示「根据…相应变化」，与遵从义不合。","【近义混同】「〜に基づいて」表示「基于…（事实·依据）」，与遵从义有别。","正解。「〜にしたがって」表示「遵从…（服从指示）」，与「按指示推进」契合。"]},
{"label":"近义辨析","q":"都会＿＿、地方は物価が安い。","options":["に比べて","に対して","に限って","に応じて"],"answer":0,"explain":["正解。「〜に比べて」表示「与…相比」的单纯比较。","【接续制约】「〜に対して」表对照须「の＋に対して」或态度对象，接续与语义有别。","【近义混同】「〜に限って」表示「唯独…偏偏」，与本句不合。","【近义混同】「〜に応じて」表示「根据…相应变化」，与本句不合。"]},
]},
{"id":"b1-52","typeKey":"bun1","title":"模拟52 限定・範囲の第三弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"経験の有無＿＿、やる気のある人を募集する。","options":["に限らず","を問わず","はもとより","にかけては"],"answer":1,"explain":["【接续制约】「〜に限らず」多接单个范畴的扩展，「有無」的对立范畴惯用「を問わず」。","正解。「〜を問わず」接「有無·国·年齢」等范畴，表示「不限…」。","【接续不合】「〜はもとより」表示「…自不必说」的递进，与本句不合。","【近义混同】「〜にかけては」表示「在…方面（技能）」，与本句不合。"]},
{"label":"近义辨析","q":"英語＿＿、仏語も話せる。","options":["のみならず","はおろか","はもとより","ばかりか"],"answer":2,"explain":["【接续制约】「〜のみならず」接名词のみ，「英語のみならず」亦通但本句递进惯用「はもとより」的呼应感更典型。","【近义混同】「〜はおろか」多接消极评价的递进，与本句的正面褒扬不合。","正解。「〜はもとより」表示「…自不必说（中性·正面递进）」。","【接续制约】「〜ばかりか」多接消极递进，与本句不合。"]},
{"label":"近义辨析","q":"彼は演奏＿＿、作曲でも才能を発揮している。","options":["をおいて","はおろか","ならでは","のみならず"],"answer":3,"explain":["【接续不合】「〜をおいて」接人名词表示「除了…别无」，与本句不合。","【近义混同】「〜はおろか」多接消极递进，与本句的正面展开不合。","【接续不合】「〜ならでは」表示「唯有…才有的」，与本句不合。","正解。「〜のみならず」表示「不仅…而且…」的书面递进。"]},
{"label":"近义辨析","q":"彼は鉛筆＿＿、消しゴムも持ってこなかった。","options":["はおろか","はもとより","のみならず","もさることながら"],"answer":0,"explain":["正解。「〜はおろか」表示「…自不必说，连…也（消极递进）」，与「什么都没带」契合。","【近义混同】「〜はもとより」用于中性·正面递进，与本句的贬降不合。","【近义混同】「〜のみならず」为中性递进，不承载消极语感。","【接续不合】「〜もさることながら」用于两点并置褒扬，与本句相反。"]},
{"label":"近义辨析","q":"価格の安さ＿＿、品質の高さが評価されている。","options":["はおろか","もさることながら","に限らず","にひきかえ"],"answer":1,"explain":["【近义混同】「〜はおろか」用于消极递进，与本句相反。","正解。「〜もさることながら」表示「…自不必说，更…」的两点并置褒扬。","【近义混同】「〜に限らず」表示「不限于…」的范围扩展，与本句不合。","【接续不合】「〜にひきかえ」表示对照，与本句的并置不合。"]},
]},
{"id":"b1-53","typeKey":"bun1","title":"模拟53 条件・仮定の第三弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"呼应制约","q":"水＿＿飲めば、生きられる。","options":["こそ","でも","さえ","すら"],"answer":2,"explain":["【呼应冲突】「〜こそ」表示强调，与ば形条件呼应不合。","【近义混同】「〜でも」表示「比如…之类（轻列举）」，缺最小条件的强调。","正解。「〜さえ〜ば」表示「只要…就（最小充分条件）」，与「有水就能活」契合。","【呼应冲突】「〜すら」表示「连…都」的极端例，与ば形条件不合。"]},
{"label":"呼应制约","q":"本人が謝らない＿＿、許すわけにはいかない。","options":["ないまでも","ないことには","ようでは","ない限り"],"answer":3,"explain":["【接续制约】「〜ないまでも」表示「即便不到…至少」，接续与本句不合。","【接续不合】「〜ないことには」与「謝らない」重叠成双重否定，「謝らないないことには」不成立。","【近义混同】「〜ようでは」表示「照…这样下去」的预判，与本句的条件不合。","正解。「〜ない限り」表示「只要不…就（不）」，与「不道歉就不原谅」的意志·许可契合。"]},
{"label":"近义辨析","q":"もし自分が相手＿＿、どうしただろう。","options":["としたら","とあれば","となると","といえども"],"answer":0,"explain":["正解。「〜としたら」表示「假如…的话」的假定，与「もし」呼应契合。","【近义混同】「〜とあれば」表示「如果是…（就愿意）」，接意愿，与本句的假定不合。","【近义混同】「〜となると」表示「一旦要…（局面变化）」，与本句的纯假定不合。","【近义混同】「〜といえども」表示「即便是…也」的让步，与本句不合。"]},
{"label":"呼应制约","q":"練習すればする＿＿、上達していく。","options":["につけ","ほど","につれて","ばかり"],"answer":1,"explain":["【呼应冲突】「〜につけ」表示「每逢…就」，与ば形呼应不合。","正解。「〜ば〜ほど」表示「越…越…」，ば形＋辞书形＋ほど是固定呼应。","【接续制约】「〜につれて」接辞书形·名词，「するにつれて」亦通但本句为ば形呼应的固定句式。","【呼应冲突】「〜ばかり」与「するばかり」构成「净是…」，与本句不合。"]},
{"label":"近义辨析","q":"値上げしよう＿＿、客が離れる。","options":["ものか","ものの","ものなら","ものだ"],"answer":2,"explain":["【近义混同】「〜ものか」为反问「怎么可能」，与本句的警告不合。","【接续制约】「〜ものの」须た形·である，接意志形不成立。","正解。「〜(よ)うものなら」接意志形，表示「一旦…的话（后果严重）」。","【近义混同】「〜ものだ」表示感慨·本性·忠告，与本句不合。"]},
]},
{"id":"b1-54","typeKey":"bun1","title":"模拟54 文語・残存表現の第三弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"予定＿＿、式は滞りなく進んだ。","options":["べく","まじき","たる","ごとく"],"answer":3,"explain":["【接续不合】「〜べく」表示「为了…（文语目的）」，与本句不合。","【接续不合】「〜まじき」作连体修饰（あるまじき行為），与本句不合。","【接续不合】「〜たる」接名词表示「身为…的」，与本句不合。","正解。「〜ごとく」表示「如…一般（文语比況）」，「予定ごとく」为公告·书面惯用。"]},
{"label":"近义辨析","q":"彼は知ら＿＿顔で通り過ぎていった。","options":["ぬ","ない","ざる","まい"],"answer":0,"explain":["正解。「〜ぬ」（文语否定）残存于惯用，「知らぬ顔」为固定表达。","【近义混同】「〜ない」为口语否定，「知らぬ顔」的惯用形需文语残存形。","【接续不合】「〜ざる」接ない形-ない（知らざる），「知らざる顔」不成立。","【接续不合】「〜まい」表示否定意志·推量，不能作连体修饰。"]},
{"label":"近义辨析","q":"昔＿＿の製法で味噌をつくる。","options":["ながらも","ながらの","つつの","がてらの"],"answer":1,"explain":["【接续不合】「〜ながらも」表示逆接（狭いながらも），作连体修饰「ながらの」才是定语形。","正解。「〜ながらの」接名词，表示「保持…原状」，「昔ながらの製法」为固定表达。","【接续不合】「〜つつ」接ます形表示并行动作，「昔つつの」不成立。","【接续不合】「〜がてら」接ます形表示「顺便」，接续与语义均不合。"]},
{"label":"近义辨析","q":"見る＿＿、窓の外を眺めていた。","options":["わけなく","ことなく","ともなく","ものなく"],"answer":2,"explain":["【接续不合】「〜わけなく」表示「并非…（理由不存在）」，接续与本句不合。","【近义混同】「〜ことなく」表示「不…而（省去某动作）」，与本句的「无心」不合。","正解。「〜ともなく」接辞书形，表示「无意中…（无明确目的）」，「見るともなく」为惯用表达。","【接续不合】「〜ものなく」非固定文型。"]},
{"label":"近义辨析","q":"目標を達成＿＿、全員で知恵を絞っている。","options":["まい","べからず","べし","べく"],"answer":3,"explain":["【近义混同】「〜まい」表示否定意志·推量，与本句不合。","【近义混同】「〜べからず」表示「不可…（告示禁止）」，与本句相反。","【近义混同】「〜べし」表示「应当…」，接续与本句的目的义不合。","正解。「〜べく」接辞书形（する→すべく），表示「为了…（文语目的）」。"]},
]},
{"id":"b1-55","typeKey":"bun1","title":"模拟55 複合助詞の第三弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"会議は東京＿＿開かれた。","options":["において","にとって","にかけて","にわたって"],"answer":0,"explain":["正解。「〜において」表示「在…（场所·场合）」，书面体。","【近义混同】「〜にとって」表示「对…而言」的评价角度，与本句不合。","【近义混同】「〜にかけて」表示「覆盖（范围）」，与本句的场所不合。","【近义混同】「〜にわたって」表示范围·期间持续，不接场所名词。"]},
{"label":"接续制约","q":"人生＿＿の試練に、彼は负けなかった。","options":["において","における","にとっての","にかけての"],"answer":1,"explain":["【接续不合】「〜において」为连用形，「においての試練」不成立。","正解。「〜における」是「において」的连体形，直接修饰名词。","【接续不合】「〜にとっての」表示「对…而言的」，与本句不合。","【接续不合】「〜にかけての」表示「在…方面的」，与本句不合。"]},
{"label":"近义辨析","q":"専門家＿＿、原因を特定できていない。","options":["たりとも","だに","すら","のみ"],"answer":2,"explain":["【近义混同】「〜たりとも」与最小量（一日）搭配，与「専門家」不合。","【接续不合】「〜だに」多用于「夢にだに思わぬ」等惯用，与本句不合。","正解。「〜すら」表示「连…都（书面极端例）」，与「连专家都无法」契合。","【近义混同】「〜のみ」表示「唯有」，与本句不合。"]},
{"label":"近义辨析","q":"一秒＿＿無駄にできない。","options":["のみ","すら","だに","たりとも"],"answer":3,"explain":["【近义混同】「〜のみ」表示「唯有」，与本句不合。","【近义混同】「〜すら」表示「连…都」的极端例举，「一秒すら」亦通但最小量＋否定惯用「たりとも」。","【接续不合】「〜だに」多用于「夢にだに」等惯用，与本句不合。","正解。「〜たりとも」与最小量名词搭配，表示「哪怕一秒也…（不能）」。"]},
{"label":"近义辨析","q":"来月十五日＿＿、契約を終了する。","options":["をもって","を限りに","にわたって","をもとに"],"answer":0,"explain":["正解。「〜をもって」表示「自…（时限）」，公告体中性表述。","【近义混同】「〜を限りに」带「以此为最后」的诀别语气，中性契约惯用「をもって」。","【接续不合】「〜にわたって」表示范围持续，与时点不合。","【近义混同】「〜をもとに」表示「以…为素材」，与本句不合。"]},
]},
{"id":"b1-56","typeKey":"bun1","title":"模拟56 複合助詞の第四弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"ファン＿＿のプロスポーツだ。","options":["に基づく","あっての","にかかわる","をめぐる"],"answer":1,"explain":["【近义混同】「〜に基づく」表示「基于…（依据）」，与本句的存在依存不合。","正解。「〜あっての＋名词」表示「有…才有…」。","【近义混同】「〜にかかわる」表示「关系到…」，与本句相反。","【接续不合】「〜をめぐる」修饰争论·对立的话题，与「スポーツ」不搭。"]},
{"label":"近义辨析","q":"近年の少子化＿＿、学校の統廃合が進んだ。","options":["に則って","に応じて","に鑑み","に限り"],"answer":2,"explain":["【近义混同】「〜に則って」表示「依照（惯例·先例）」，与本句不合。","【近义混同】「〜に応じて」表示「根据…相应变化」，与本句的缘由不合。","正解。「〜に鑑み」表示「鉴于…（公文语决策缘由）」。","【接续不合】「〜に限り」表示「仅限于…」，与本句不合。"]},
{"label":"近义辨析","q":"駅＿＿、再開発が進んでいる。","options":["を皮切りに","をはじめ","をきっかけに","を中心に"],"answer":3,"explain":["【近义混同】「〜を皮切りに」表示「以…为开端（时间）」，与本句的空间核心不合。","【近义混同】「〜をはじめ」表示「以…为首（列举代表）」，与「核心展开」不合。","【近义混同】「〜をきっかけに」表示「以…为契机」，与本句不合。","正解。「〜を中心に」表示「以…为中心（围绕其展开）」。"]},
{"label":"近义辨析","q":"語学＿＿、姉の方が優れている。","options":["にかけては","において","にとって","に比べて"],"answer":0,"explain":["正解。「〜にかけては」表示「在…方面（首屈一指）」，与「姐姐更胜一筹」的评价契合。","【近义混同】「〜において」表示「在…（场所·领域）」，不带评价。","【近义混同】「〜にとって」表示「对…而言」，与本句不合。","【近义混同】「〜に比べて」表示「与…相比」的单纯比较，不承载「更胜一筹」的评价。"]},
{"label":"近义辨析","q":"彼は己の危険＿＿、子どもを救助した。","options":["をよそに","を顧みず","をものともせず","にかかわらず"],"answer":1,"explain":["【近义混同】「〜をよそに」表示「无视（外界的声音·期待）」，不用于自身的安危。","正解。「〜を顧みず」表示「不顾…（自身安危，奋不顾身）」。","【近义混同】「〜をものともせず」表示「不把…放在眼里」的强者姿态，与本句的奋不顾身有别。","【近义混同】「〜にかかわらず」表示「不论…」，与本句不合。"]},
]},
{"id":"b1-57","typeKey":"bun1","title":"模拟57 強調・断定の第三弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"文末表现","q":"彼の成功は、日々の努力の賜物＿＿。","options":["までもない","にすぎない","にほかならない","ものだ"],"answer":2,"explain":["【近义混同】「〜までもない」表示「没必要…」，与本句不合。","【近义混同】「〜にすぎない」表示「不过是」的贬低，与本句相反。","正解。「〜にほかならない」表示「正是…（强断定抬升）」，与「成功源于努力」的强调契合。","【近义混同】「〜ものだ」表示感慨·本性·忠告，与本句的断言不合。"]},
{"label":"文末表现","q":"それは一つの仮説＿＿。","options":["というものだ","にほかならない","までもない","にすぎない"],"answer":3,"explain":["【近义混同】「〜というものだ」表示「这才真是」的断言，与本句不合。","【近义混同】「〜にほかならない」表示「正是…」的抬升，与本句相反。","【近义混同】「〜までもない」表示「没必要…」，与本句不合。","正解。「〜にすぎない」表示「不过是…」的贬降，与「仅是假说」契合。"]},
{"label":"文末表现","q":"電話で済むなら、行く＿＿。","options":["までもない","まい","どころではない","ものではない"],"answer":0,"explain":["正解。「〜までもない」接辞书形，表示「没必要…」。","【近义混同】「〜まい」表示否定意志，与本句的「没必要」不合。","【近义混同】「〜どころではない」表示「哪里谈得上」，与本句不合。","【近义混同】「〜ものではない」表示「不该…」的说教，与本句不合。"]},
{"label":"文末表现","q":"あんな失礼な人と、二度と付き合う＿＿。","options":["ものだ","ものか","までもない","というものだ"],"answer":1,"explain":["【近义混同】「〜ものだ」表示感慨·本性·忠告，与本句的反问相反。","正解。「〜ものか」接辞书形，表示「怎么可能（强烈反问）」。","【近义混同】「〜までもない」表示「没必要…」，与本句不合。","【近义混同】「〜というものだ」表示「这才真是」的断言，与本句相反。"]},
{"label":"文末表现","q":"彼は歩く＿＿、立っているのもやっとだ。","options":["というものだ","どころではない","どころか","にすぎない"],"answer":2,"explain":["【近义混同】「〜というものだ」表示「这才真是」的断言，与本句不合。","【近义混同】「〜どころではない」表示「哪里谈得上（无暇）」，与本句的递进不合。","正解。「〜どころか」表示「非但…（更甚）」，与「别说走，站都难」契合。","【近义混同】「〜にすぎない」表示「不过是」，与本句不合。"]},
]},
{"id":"b1-58","typeKey":"bun1","title":"模拟58 敬語の第三弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"敬語","q":"先生はその本を読み＿＿。","options":["ご覧いただきました","お読みいたしました","拝読なさいました","お読みになりました"],"answer":3,"explain":["【敬語误用】「ご覧いただく」表示「请对方看」，与「老师读」的方向不合。","【敬語误用】「お〜いたす」是谦让语（我方做），方向相反。","【敬語误用】「拝読」已是谦让语，叠「なさる」构成双重敬语。","正解。「お〜になる」是尊敬语，与主语「先生」的方向契合。"]},
{"label":"敬語","q":"詳しい件は、追って＿＿。","options":["ご連絡いたします","ご連絡なさいます","ご連絡ください","ご連絡いただきます"],"answer":0,"explain":["正解。「お／ご〜いたす」是谦让语大形式，用于己方承诺行为。","【敬語误用】「〜なさる」是尊敬语（对方做），方向相反。","【敬語误用】「〜てください」表示「请对方做」，方向相反。","【敬語误用】「〜ていただく」表示「承蒙对方做」，方向相反。"]},
{"label":"敬語","q":"部長はもう出発＿＿。","options":["まいった","なさった","くださった","さしあげた"],"answer":1,"explain":["【敬語误用】「まいる」是「行く·来る」的谦让语（我方），方向相反。","正解。「〜なさる」是「する」的尊敬语，与主语「部長」契合。","【敬語误用】「〜てくださる」表示「对方为我（方）做…」，此处无授受受益义。","【敬語误用】「〜てさしあげる」表示「我方为对方做」，方向相反。"]},
{"label":"敬語","q":"先生が推薦状を書いて＿＿。","options":["さしあげた","いただいた","くださった","なさった"],"answer":2,"explain":["【敬語误用】「〜てさしあげる」表示「我方为对方做」，方向相反。","【敬語误用】「〜ていただく」表示「承蒙对方做」须我方受益主语，「先生が」不合。","正解。「〜てくださる」表示「对方为我（方）做…」，推薦状正是为我而写。","【敬語误用】「〜なさる」虽为尊敬语，但不承载「为我受益」的授受义，本句惯用「くださる」。"]},
{"label":"敬語","q":"課長に原稿を＿＿。","options":["お見せいたしました","ご覧になりました","拝見いたしました","ご覧いただきました"],"answer":3,"explain":["【敬語误用】「お見せする」表示「我方给对方看」，与「课长看原稿」相反。","【敬語误用】「ご覧になる」须以「課長が」为主语，与「課長に」不合。","【敬語误用】「拝見する」是「看」的谦让语（我方看），方向相反。","正解。「〜て／ご〜いただく」表示「承蒙（课长为我）看」，与「課長に」的授受方向契合。"]},
]},
{"id":"b1-59","typeKey":"bun1","title":"模拟59 接続詞の型（第三弾）","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"接续词","q":"勝ったというより、相手が負けた＿＿だ。","options":["むしろ","もっとも","とはいえ","そもそも"],"answer":0,"explain":["正解。「むしろ」表示「倒不如说」，与「与其说是赢不如说是输」的选択契合。","【近义混同】「もっとも」表示附加保留（不过），与本句不合。","【近义混同】「とはいえ」表示「虽说如此」的让步，与本句不合。","【近义混同】「そもそも」表示追根溯源，与本句不合。"]},
{"label":"接续词","q":"A案は費用が安い。＿＿、B案は工期が短い。","options":["しかし","一方","つまり","そのため"],"answer":1,"explain":["【文脉断裂】「しかし」表示逆接，两案为并列对照而非转折。","正解。「一方」表示两事项的中性对照，与「A便宜B快」的并置契合。","【文脉断裂】「つまり」表示要约，与本句不合。","【文脉断裂】「そのため」表示因果，与本句不合。"]},
{"label":"接续词","q":"＿＿、彼の方法は速い。しかし、正確さでは劣る。","options":["むしろ","もっとも","たしかに","そもそも"],"answer":2,"explain":["【文脉断裂】「むしろ」表示「倒不如说」，与本句的让步不合。","【近义混同】「もっとも」表示附加保留，不能开启让步反驳。","正解。「たしかに」表示「诚然（先让步）」，与后句「しかし」构成让步反驳的固定节奏。","【文脉断裂】「そもそも」表示追根溯源，与本句不合。"]},
{"label":"接续词","q":"手取りは月二十五万円。＿＿、年収にして三百万円強だ。","options":["ところが","ただし","もっとも","つまり"],"answer":3,"explain":["【文脉断裂】「ところが」表示意外逆接，与本句不合。","【文脉断裂】「ただし」表示但书，与本句的换算不合。","【文脉断裂】「もっとも」表示保留，与本句不合。","正解。「つまり」表示要约换算，与月薪到年收入的换算契合。"]},
{"label":"接续词","q":"本誌は毎週月曜に発行される。＿＿、祝日は翌日にずれる。","options":["ただし","しかし","つまり","ところが"],"answer":0,"explain":["正解。「ただし」表示附加限制（但书），与「例行规定＋例外」契合。","【近义混同】「しかし」表示全面转折，与本句的例外补充不合。","【文脉断裂】「つまり」表示要约，与本句不合。","【文脉断裂】「ところが」表示意外逆接，与本句的但书不合。"]},
]},
{"id":"b1-60","typeKey":"bun1","title":"模拟60 対比・添加の第三弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"輸出が伸びたの＿＿、内需は低迷している。","options":["に比べて","に対して","にひきかえ","一方で"],"answer":1,"explain":["【近义混同】「〜に比べて」表示单纯比较（量·程度），与结构性对照有别。","正解。「〜のに対して」表示两者的中性对照。","【接续不合】「〜にひきかえ」接名词，「伸びたの＋にひきかえ」不成立。","【接续不合】「〜一方で」接辞书形·た形，接「の」后不成立。"]},
{"label":"近义辨析","q":"経験＿＿、語学力もある彼が最適任だ。","options":["はもとより","をはじめ","に加えて","にかけては"],"answer":2,"explain":["【接续不合】「〜はもとより」表示递进列举，须前接名词は。","【近义混同】「〜をはじめ」表示「以…为首（列举）」，与本句的追加不合。","正解。「〜に加えて」表示「加之…（追加）」。","【近义混同】「〜にかけては」表示「在…方面（技能）」，与本句不合。"]},
{"label":"近义辨析","q":"この悩みは若者＿＿、全世代に共通する。","options":["に限って","を問わず","のみならず","に限らず"],"answer":3,"explain":["【近义混同】「〜に限って」表示「唯独…偏偏」，与本句相反。","【接续制约】「〜を問わず」须接一对并列范畴（昼夜·国），单个「若者」不成立。","【接续制约】「〜のみならず」多接名词のみ，「若者のみならず」亦通但「に限らず」更惯用于此处的范围扩展。","正解。「〜に限らず」表示「不限于…（扩展到更大范围）」。"]},
{"label":"近义辨析","q":"ダイエットの失敗は女性＿＿。","options":["に限ったことではない","に限り","に限って","に限らず"],"answer":0,"explain":["正解。「〜に限ったことではない」表示「并非仅限于…」，可独立结句。","【近义混同】「〜に限り」表示「仅限于…（告示优惠）」，与本句相反。","【近义混同】「〜に限って」表示「唯独…偏偏」，与本句相反。","【接续制约】「〜に限らず」须后接扩展范围，单独结句不自然。"]},
{"label":"近义辨析","q":"この仕事は田中さん＿＿には任せられない。","options":["をはじめ","をおいて","をめぐって","を込めて"],"answer":1,"explain":["【接续不合】「〜をはじめ」表示「以…为首（列举）」，与本句不合。","正解。「〜をおいて」接人名词＋否定，表示「除了…别无」。","【接续不合】「〜をめぐって」表示「围绕…」，与本句不合。","【接续不合】「〜を込めて」表示「满怀…（情感）」，与本句不合。"]},
]},
{"id":"b1-61","typeKey":"bun1","title":"模拟61 呼応の型（第二弾）","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"呼应制约","q":"＿＿夢のような景色だった。","options":["あまり","たとえ","まるで","決して"],"answer":2,"explain":["【呼应冲突】「あまり」与否定·程度呼应，本句无否定。","【呼应冲突】「たとえ」与让步呼应，本句无比况。","正解。「まるで〜ようだ」表示「仿佛…一般」的比况呼应。","【呼应冲突】「決して」与否定呼应，本句无否定。"]},
{"label":"呼应制约","q":"＿＿失敗しても、やり遂げるつもりだ。","options":["あまり","もし","まるで","たとえ"],"answer":3,"explain":["【呼应冲突】「あまり」与程度·否定呼应，本句无。","【呼应冲突】「もし」与「たら·ば」的条件呼应，与「ても」的让步不合。","【呼应冲突】「まるで」与比况呼应，本句无比况。","正解。「たとえ〜ても」表示「即便…也」，让步强调的固定呼应。"]},
{"label":"呼应制约","q":"難しいからといって、＿＿不可能ではない。","options":["必ずしも","まるで","たとえ","あまり"],"answer":0,"explain":["正解。「必ずしも〜ない」表示「未必（部分否定）」，与双重否定契合。","【呼应冲突】「まるで」与比况呼应，本句无比况。","【呼应冲突】「たとえ」与让步呼应，本句无条件让步。","【呼应冲突】「あまり」与程度呼应，本句无。"]},
{"label":"呼应制约","q":"秘密は＿＿人に話してはいけない。","options":["必ずしも","決して","あまり","たとえ"],"answer":1,"explain":["【呼应冲突】「必ずしも〜ない」表示部分否定，与本句的全面禁止不合。","正解。「決して〜ない」表示「决不（全面否定）」，与禁止的强语气契合。","【呼应冲突】「あまり」与程度呼应，本句无。","【呼应冲突】「たとえ」与让步呼应，本句无。"]},
{"label":"呼应制约","q":"彼は＿＿の悔しさに、涙をこらえた。","options":["たとえ","まるで","あまり","決して"],"answer":2,"explain":["【呼应冲突】「たとえ」与让步呼应，本句无。","【呼应冲突】「まるで」与比况呼应，本句无比况。","正解。「あまりの＋名词」表示「过分…（以致）」，「あまりの悔しさ」为惯用表达。","【呼应冲突】「決して」与否定呼应，本句无。"]},
]},
{"id":"b1-62","typeKey":"bun1","title":"模拟62 様態・傾向の第四弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"六十過ぎても、彼は年寄り＿＿ところがない。","options":["気味","げ","がち","っぽい"],"answer":3,"explain":["【接续不合】「〜気味」表示当下状态，接续与语义均不合。","【接续不合】「〜げ」接形容词词干·ます形，接「年寄り」不成立。","【接续不合】「〜がち」表示频度倾向，接续与本句不合。","正解。「〜っぽい」接名词，表示「有…的味道」。"]},
{"label":"近义辨析","q":"彼の演技はすっかり名人＿＿、見違えるようだ。","options":["めいて","っぽくなって","げになって","がちになって"],"answer":0,"explain":["正解。「〜めく」接名词，表示「带有…气息」，「名人めいてきた」表示气度渐成。","【近义混同】「〜っぽい」表示「有…味道」的静态评价，与本句的推移感不合。","【接续不合】「〜げ」接形容词词干·ます形，「名人げ」不成立。","【接续不合】「〜がち」表示频度倾向，与本句不合。"]},
{"label":"文末表现","q":"彼は徹夜続きで授業をサボる＿＿だ。","options":["おそれがある","始末だ","きらいがある","かぎりだ"],"answer":1,"explain":["【时态肯否错位】「〜おそれがある」表示「恐将…」的潜在风险，事态未发生。","正解。「〜始末だ」表示「落到…的地步（消极归結，已发生）」。","【近义混同】「〜きらいがある」表示「有…的倾向（惯常习性）」，与本句的恶化归結不合。","【近义混同】「〜かぎりだ」表示「…极了（感慨顶点）」，与本句相反。"]},
{"label":"文末表现","q":"この川は上流で氾濫する＿＿。","options":["きらいがある","しまつだ","おそれがある","がちだ"],"answer":2,"explain":["【近义混同】「〜きらいがある」表示惯常习性的贬义倾向，与本句的风险警告不合。","【时态肯否错位】「〜始末だ」表示事态已实际恶化，与本句的假设不合。","正解。「〜おそれがある」表示「恐怕会…（公告体风险警告）」，事态未发生。","【近义混同】「〜がちだ」表示频度倾向，与本句不合。"]},
{"label":"近义辨析","q":"彼は物事を悲観的に考えすぎる＿＿がある。","options":["かぎり","おそれ","しまつ","きらい"],"answer":3,"explain":["【近义混同】「〜かぎりだ」表示「…极了」的感慨，与本句不合。","【近义混同】「〜おそれがある」表示「恐将…」的潜在风险，与本句的习性不合。","【时态肯否错位】「〜始末だ」表示事态已恶化的归結，与本句的习性不合。","正解。「〜きらいがある」表示「有…的倾向（贬义委婉，惯常习性）」。"]},
]},
{"id":"b1-63","typeKey":"bun1","title":"模拟63 逆接・让步の第五弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"彼の話を聞く＿＿、故郷を思い出す。","options":["につけ","につれ","にあたって","にかけて"],"answer":0,"explain":["正解。「〜につけ」表示「每逢…就（情感自然涌起）」。","【近义混同】「〜につれ」表示「随着…（渐进变化）」，与本句的情感涌起不合。","【近义混同】「〜にあたって」表示「值此…之际」，与本句不合。","【近义混同】「〜にかけて」表示「在…方面（技能）」，与本句不合。"]},
{"label":"近义辨析","q":"運動をする＿＿、散歩程度だ。","options":["とはいえ","といっても","からといって","というものの"],"answer":1,"explain":["【近义混同】「〜とはいえ」承接前文做部分让步的书面表达，与本句的口语补充不合。","正解。「〜といっても」表示「虽说…（程度大打折扣）」，与「说运动其实只是散步」契合。","【近义混同】「〜からといって」表示「不能仅因…就」，后接否定，与本句不合。","【接续不合】「〜というものの」非固定文型（ものの直接接续）。"]},
{"label":"近义辨析","q":"台風直撃で、花見＿＿の状況だ。","options":["にすぎない","わりには","どころの騒ぎではない","をはじめ"],"answer":2,"explain":["【近义混同】「〜にすぎない」表示「不过是」，与本句不合。","【近义混同】「〜わりには」表示「与程度不相称」，与本句不合。","正解。「〜どころの騒ぎではない」表示「远非…的状态（程度严重）」，修饰名词时用「の」形。","【接续不合】「〜をはじめ」表示列举之首，与本句不合。"]},
{"label":"近义辨析","q":"自分では何もしない＿＿、文句ばかり言う。","options":["ものの","わりには","にしては","くせに"],"answer":3,"explain":["【接续不合】「〜ものの」须た形·である，接辞书形不成立。","【近义混同】「〜わりには」表示中性评价，无谴责。","【近义混同】「〜にしては」表示客观评价，无谴责。","正解。「〜くせに」表示「明明…却（指责）」，与「什么都不做却抱怨」契合。"]},
{"label":"近义辨析","q":"有名＿＿、批判の声も大きくなる。","options":["ともなると","とあれば","としたら","ときたら"],"answer":0,"explain":["正解。「〜ともなると」表示「一到…（程度自然伴随）」，与「出了名则毁誉并至」契合。","【近义混同】「〜とあれば」表示「如果是…（就愿意）」，与本句不合。","【近义混同】「〜としたら」表示假定，与本句的必然不合。","【近义混同】「〜ときたら」表示抱怨话题，与本句的中性描述不合。"]},
]},
{"id":"b1-64","typeKey":"bun1","title":"模拟64 原因・理由の第四弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"この島は松が茂る＿＿、「松島」と名付けられた。","options":["だけあって","ことから","せいで","あまり"],"answer":1,"explain":["【近义混同】「〜だけあって」表示名实相符的称赞，与本句的命名依据不合。","正解。「〜ことから」表示客观缘由，是「由来源命名」的典型用法。","【近义混同】「〜せいで」表示归咎负面原因，与本句不合。","【接续不合】「〜のあまり」前接感情名词，接续不合。"]},
{"label":"近义辨析","q":"さすが十年やってきた＿＿、手際が違う。","options":["せいで","ばかりに","だけあって","あまり"],"answer":2,"explain":["【近义混同】「〜せいで」表示归咎，与本句相反。","【近义混同】「〜ばかりに」表示负面归因，与本句的称赞相反。","正解。「〜だけあって」表示「不愧是…（名实相符）」，与「さすが」呼应契合。","【接续不合】「〜のあまり」前接感情名词，接续不合。"]},
{"label":"近义辨析","q":"夏休み＿＿、子どもたちでにぎわっている。","options":["ときたら","とあれば","ことだから","とあって"],"answer":3,"explain":["【近义混同】「〜ときたら」表示抱怨话题，与本句的正面描写相反。","【近义混同】「〜とあれば」表示「如果是…（就愿意）」，接意愿，与本句不合。","【接续不合】「〜ことだから」前接人名词の，与本句不合。","正解。「〜とあって」表示「因为处于…特殊状况」，与「暑假的热闹景象」契合。"]},
{"label":"近义辨析","q":"子どもが熱を出した＿＿、今日は休ませていただきます。","options":["ものですから","とあって","ばかりに","だけあって"],"answer":0,"explain":["正解。「〜ものですから」表示「因为…（辩解语气）」，与请假·道歉场合契合。","【近义混同】「〜とあって」客观描述特殊状况引发的景象，不用于个人辩解。","【文体不合】「〜ばかりに」为书面强调归因，不能用于礼貌辩解。","【近义混同】「〜だけあって」表示名实相符，与本句无关。"]},
{"label":"近义辨析","q":"若さ＿＿の過ちとして、許してやってほしい。","options":["ばかりに","ゆえに","せいで","あまり"],"answer":1,"explain":["【接续不合】「〜ばかりに」作连用修饰，「ゆえの」的定语形不合。","正解。「〜ゆえにの」表示「因…的（文语定语）」，「若さゆえの過ち」为惯用表达。","【近义混同】「〜せいで」表示归咎，与本句的辩解不合。","【接续不合】「〜のあまり」接续不合。"]},
]},
{"id":"b1-65","typeKey":"bun1","title":"模拟65 条件・仮定の第四弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"呼应制约","q":"実物を見＿＿、買うかどうか決められない。","options":["ようでは","ない限り","ないことには","ものなら"],"answer":2,"explain":["【近义混同】「〜ようでは」表示「照…这样下去」的预判，与本句的条件不合。","【近义混同】「〜ない限り」重「只要不…就（不）」的条件下的意志·许可，判断句惯用「ないことには」。","正解。「〜ないことには」接ない形，与「決められない」的判断不可能呼应，表示「不…就（无从）…」。","【近义混同】「〜ものなら」接意志形，接续不合。"]},
{"label":"近义辨析","q":"学生＿＿、学業を優先すべきだ。","options":["どころか","とはいえ","ならでは","である以上は"],"answer":3,"explain":["【近义混同】「〜どころか」表示「非但…反而」，与本句不合。","【近义混同】「〜とはいえ」表示「虽说如此」的让步，与本句的义务不合。","【接续不合】「〜ならでは」表示「唯有…才有的」，与本句不合。","正解。「〜以上(は)」接「である以上」，表示「既然是…就（必须）」。"]},
{"label":"呼应制约","q":"行こう＿＿、行けない。","options":["にも","とも","ものの","がてら"],"answer":0,"explain":["正解。「〜(よ)うにも＋否定」表示「想…也不能…」。","【呼应冲突】「〜ともなく」接辞书形表示「无意中」，与本句不合。","【接续不合】「〜ものの」接た形·である，接续不合。","【接续不合】「〜がてら」接ます形，接续不合。"]},
{"label":"近义辨析","q":"ベテラン＿＿、初めてでうまくいかなくて当然だ。","options":["ならまだしも","ではあるまいし","に限って","も同然だ"],"answer":1,"explain":["【近义混同】「〜ならまだしも」表示「如果是…倒还罢了」的递进责难，与本句相反。","正解。「〜ではあるまいし」表示「又不是…（理所当然）」，与「非老手自然生疏」契合。","【近义混同】「〜に限って」表示「唯独…偏偏」，与本句不合。","【近义混同】「〜も同然だ」表示「和…一样」，与本句不合。"]},
{"label":"近义辨析","q":"一週間＿＿、一ヶ月も待つのは無理だ。","options":["どころではない","どころか","ならまだしも","はともかく"],"answer":2,"explain":["【近义混同】「〜どころではない」表示「哪里谈得上」，与本句不合。","【近义混同】「〜どころか」表示「非但…反而」，与本句的比较让步不合。","正解。「〜ならまだしも」表示「如果是…倒还罢了」，与「一周尚可一月不可」契合。","【近义混同】「〜はともかく」表示「姑且不论」，与本句不合。"]},
]},
{"id":"b1-66","typeKey":"bun1","title":"模拟66 強調・断定の第四弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"文末表现","q":"優勝候補が一回戦で负ける＿＿。","options":["にほかならない","とはいえ","というものだ","とは"],"answer":3,"explain":["【接续不合】「〜にほかならない」接名词，接句子不成立。","【近义混同】「〜とはいえ」表示「虽说如此」的部分让步，与本句的惊愕不合。","【近义混同】「〜というものだ」表示「这才真是」的断言，与本句不合。","正解。「〜とは」接句子，表示「竟然…（惊愕，句尾省略）」。"]},
{"label":"近义辨析","q":"足跡の形から、大型犬＿＿。","options":["に相違ない","に限る","に越したことはない","にあたらない"],"answer":0,"explain":["正解。「〜に相違ない」接普通形，表示「必是…」的书面断定，与「据足迹推断」契合。","【近义混同】「〜に限る」表示「最好（莫过于）」的建议，与本句的推断不合。","【近义混同】「〜に越したことはない」表示「没有比…更好」，与本句不合。","【近义混同】「〜にはあたらない」表示「不值得…（惊讶）」，与本句不合。"]},
{"label":"文末表现","q":"困ったときに助け合うのが、本当の友情＿＿。","options":["というものではない","というものだ","というところだ","といったらない"],"answer":1,"explain":["【近义混同】「〜というものではない」表示「并非…就行」，方向相反。","正解。「〜というものだ」表示「这才真是…」的本质断言。","【近义混同】「〜というところだ」表示「大概也就…的程度」，与本句相反。","【近义混同】「〜といったらない」表示「难以形容」的感叹，与本句的断言不合。"]},
{"label":"文末表现","q":"初めての海外で一人、不安＿＿。","options":["というものだ","というところだ","といったらない","とはいえ"],"answer":2,"explain":["【近义混同】「〜というものだ」表示冷静的断言，与本句的激动不合。","【近义混同】「〜というところだ」表示「大概也就…的程度」，与本句相反。","正解。「〜といったらない」表示「…得难以形容」的极端感叹。","【近义混同】「〜とはいえ」表示部分让步，与本句不合。"]},
{"label":"近义辨析","q":"あの発言は、世間の議論を呼ば＿＿。","options":["ざるを得ない","ずにはすまない","ずにはいられない","ずにはおかない"],"answer":3,"explain":["【近义混同】「〜ざるを得ない」表示「迫于外部不得不」，与本句不合。","【近义混同】「〜ずにはすまない」表示「不…就过意不去（义务主体）」，与本句不合。","【近义混同】「〜ずにはいられない」表示「禁不住（情感冲动）」，与本句不合。","正解。「〜ずにはおかない」表示「必然会引起…（主语可为事态）」。"]},
]},
{"id":"b1-67","typeKey":"bun1","title":"模拟67 契約・時点の第五弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"接续制约","q":"信号が変わった＿＿、車が一斉に走り出した。","options":["とたん","や否や","なり","そばから"],"answer":0,"explain":["正解。「〜たとたん」接た形，表示「刚一…就（突发）」。","【接续不合】「〜や否や」须辞书形（変わるや否や）。","【接续不合】「〜なり」须辞书形（変わるなり）。","【近义混同】「〜そばから」表示徒劳反复，与本句的一次性突发不合。"]},
{"label":"近义辨析","q":"彼はベッドに飛び込む＿＿、寝息を立て始めた。","options":["とたん","なり","や否や","そばから"],"answer":1,"explain":["【接续不合】「〜たとたん」须た形，接续不合。","正解。「〜なり」接辞书形，表示同一主体动作「刚一…就（紧接着）」，与「倒头就睡」的连贯契合。","【近义混同】「〜や否や」重突发的客观事态，不带同一主体连续动作的连贯性。","【近义混同】「〜そばから」表示徒劳反复，与本句不合。"]},
{"label":"近义辨析","q":"細部＿＿、気が配られている。","options":["をもって","に限らず","に至るまで","を通じて"],"answer":2,"explain":["【近义混同】「〜をもって」表示「以…（手段·时限）」，与本句不合。","【近义混同】「〜に限らず」表示「不限于…」的扩展，与本句的极端化不合。","正解。「〜に至るまで」表示「直到…（范围推到极端）」。","【近义混同】「〜を通じて」表示「经由…（中介）」，与本句不合。"]},
{"label":"近义辨析","q":"昨日＿＿、彼とは縁を切った。","options":["を皮切りに","をもって","に至って","を限りに"],"answer":3,"explain":["【近义混同】「〜を皮切りに」表示「以…为开端」，与本句相反。","【近义混同】「〜をもって」表示中性时点（公告体），无诀别语感。","【接续不合】「〜に至って」表示事态恶化到极端（事ここに至って），与时点不合。","正解。「〜を限りに」表示「以…为最后（时限）」，含诀别语气，与「断绝往来」契合。"]},
{"label":"近义辨析","q":"一度坐り込んだ＿＿、二時間も動かなかった。","options":["が最後","からといって","たびに","に至って"],"answer":0,"explain":["正解。「〜たが最後」表示「一旦…就（不可挽回）」。","【近义混同】「〜からといって」表示「不能仅因…就」，与本句不合。","【近义混同】「〜たびに」表示「每当…就」，与本句的一次性不合。","【接续不合】「〜に至って」表示事态极端化，与本句不合。"]},
]},
{"id":"b1-68","typeKey":"bun1","title":"模拟68 対比・文語の第四弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"語学の上では、まだ彼＿＿。","options":["に限る","には及ばない","に足る","にあたらない"],"answer":1,"explain":["【近义混同】「〜に限る」表示「最好（莫过于）」的建议，与本句不合。","正解。「〜には及ばない」表示「比不上…」。","【近义混同】「〜に足る」表示「值得…」，与本句不合。","【近义混同】「〜にはあたらない」表示「不值得（惊讶）」，与本句不合。"]},
{"label":"呼应制约","q":"何を＿＿、決心は変わらない。","options":["言いたげに","言われんばかり","言われようが","言うにつけ"],"answer":2,"explain":["【近义混同】「〜げ」表示神情，接续与本句不合。","【近义混同】「〜んばかり」表示「几乎要…的样子」，与本句的让步不合。","正解。「〜(よ)うが」接意志形，与「何を」呼应表示「无论…都」。","【呼应冲突】「〜につけ」须「何かにつけ」的形式，「何を言うにつけ」不成立。"]},
{"label":"文末表现","q":"最近は文字を書く＿＿、名前を書くのさえ忘れる老人が増えている。","options":["にすぎない","ものか","どころではない","どころか"],"answer":3,"explain":["【近义混同】「〜にすぎない」表示「不过是」，与本句不合。","【近义混同】「〜ものか」为反问「怎么可能」，与本句不合。","【近义混同】「〜どころではない」表示「哪里谈得上（无暇）」，与本句的递进不合。","正解。「〜どころか」表示「非但…（更甚）」，与「别说写字，连名字都忘」契合。"]},
{"label":"近义辨析","q":"彼は寒さ＿＿、冬の海で泳いでいる。","options":["をものともせず","をよそに","を顧みず","にかかわらず"],"answer":0,"explain":["正解。「〜をものともせず」表示「不把…放在眼里（强者姿态）」，与「不畏寒冬」契合。","【近义混同】「〜をよそに」表示「无视（外界的声音·期待）」，不用于自身的体感。","【近义混同】「〜を顧みず」表示「不顾（自身安危）」的奋不顾身，与日常锻炼的从容有别。","【近义混同】「〜にかかわらず」表示「不论…」，与本句不合。"]},
{"label":"近义辨析","q":"散歩＿＿、新聞を買ってきた。","options":["かたわら","がてら","ながら","つつ"],"answer":1,"explain":["【接续不合】「〜かたわら」接名词の·辞书形，表示以某身份为本业的兼做，「散歩のかたわら」不成立。","正解。「〜がてら」接ます形，表示「顺便、捎带（主中带副）」。","【接续不合】「〜ながら」接名词表示「保持…原状」（昔ながら），与本句不合。","【接续不合】「〜つつ」接ます形表示并行动作（文语），与本句的主副关系有别。"]},
]},
{"id":"b1-69","typeKey":"bun1","title":"模拟69 敬語・方向の型①","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"敬語","q":"部長は本日、大阪へ出張＿＿。","options":["なさいます","いたします","さしあげます","いただきます"],"answer":0,"explain":["正解。「〜なさる」是「する」的尊敬语，与主语「部長」契合。","【敬語误用】「〜いたす」是「する」的谦让语（我方），方向相反。","【敬語误用】「〜てさしあげる」表示「我方为对方做」，方向相反。","【敬語误用】「〜ていただく」表示「承蒙对方做」，方向相反。"]},
{"label":"敬語","q":"先生、明日の会議に＿＿でしょうか。","options":["ご出席いたします","ご出席になります","ご出席くださいますか","ご出席さしあげます"],"answer":1,"explain":["【敬語误用】「ご〜いたす」是谦让语（我方做），方向相反。","正解。「ご〜になる」是尊敬语，与主语「先生」契合。","【敬語误用】「〜てくださる」表示「对方为我做」，此处无授受受益义且与「でしょうか」的推量不合。","【敬語误用】「〜てさしあげる」表示「我方为对方做」，方向相反。"]},
{"label":"敬語","q":"部長に企画書をご覧＿＿。","options":["さしあげました","になりました","いただきました","いたしました"],"answer":2,"explain":["【敬語误用】「お見せする」类「さしあげる」表示「我方给对方看」，方向相反。","【敬語误用】「ご覧になる」须以「部長が」为主语，与「部長に」不合。","正解。「〜て／ご〜いただく」表示「承蒙（部长为我）看」，与「部長に」的授受方向契合。","【敬語误用】「いたす」是谦让语（我方做），与「部长看」的方向不合。"]},
{"label":"敬語","q":"社長はその件をご＿＿でしょうか。","options":["おっしゃっておりますか","存じていらっしゃいますか","ご覧になっておりますか","存知でしょうか"],"answer":3,"explain":["【近义混同】「おっしゃる」是「说」的尊敬语，与「是否知道」不合。","【敬語误用】「存じる」是谦让语（我方知道），叠「いらっしゃる」方向混乱。","【近义混同】「ご覧になる」是「看」的尊敬语，与「是否知道」不合。","正解。「ご存知だ」是「知っている」的尊敬语，「ご存知でしょうか」为郑重询问。"]},
{"label":"敬語","q":"ご多用のところ恐れ入りますが、何卒よろしくお願い＿＿。","options":["申し上げます","なさいます","さしあげます","いただきます"],"answer":0,"explain":["正解。「〜申し上げる」是「言う」的谦让语，「お願い申し上げます」为郑重拜托的固定表达。","【敬語误用】「〜なさる」是尊敬语（对方做），与「我方拜托」相反。","【敬語误用】「〜さしあげる」表示「我方为对方做」，与本句不合。","【敬語误用】「〜いただく」表示「承蒙对方做」，与「お願いする」的搭配不合。"]},
]},
{"id":"b1-70","typeKey":"bun1","title":"模拟70 敬語・方向の型②","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"敬語","q":"課長が手伝って＿＿。","options":["いただきました","くださいました","さしあげました","まいりました"],"answer":1,"explain":["【敬語误用】「〜ていただく」须我方为主语，「課長が」不合。","正解。「〜てくださる」表示「对方为我（方）做…」，与「课长帮忙」契合。","【敬語误用】「〜てさしあげる」表示「我方为对方做」，方向相反。","【敬語误用】「まいる」是「行く·来る」的谦让语，与「手伝う」不合。"]},
{"label":"敬語","q":"私は同僚が荷物を運ぶのを手伝って＿＿。","options":["くださいました","いただきました","さしあげました","まいりました"],"answer":2,"explain":["【敬語误用】「〜てくださる」须对方为主语，「私は」不合。","【敬語误用】「〜ていただく」表示「承蒙对方做」，与主语「私」相反。","正解。「〜てさしあげる」表示「我方为对方做…」，与「我帮同事」契合。","【敬語误用】「まいる」是「行く·来る」的谦让语，与「手伝う」不合。"]},
{"label":"敬語","q":"先輩に教えて＿＿。","options":["やりました","さしあげました","くれました","いただきました"],"answer":3,"explain":["【敬語误用】「〜てやる」为对下级·动植物的给予，对前辈失礼。","【敬語误用】「〜てさしあげる」表示「我方为对方教」，方向相反。","【敬語误用】「〜てくれる」与「先輩に」不合（くれる须「先輩が」）。","正解。「〜ていただく」表示「承蒙（前辈为我）教」，与「先輩に」的授受方向契合。"]},
{"label":"敬語","q":"田中先生の御活躍は＿＿。","options":["存じ上げております","存じております","知っております","承っております"],"answer":0,"explain":["正解。「存じ上げる」是「知っている」的谦让语（对特别值得尊敬之人），与「御活躍」的敬意契合。","【敬語误用】「存じる」用于一般事物·事项，对个人的名声·成就用「存じ上げる」。","【敬語误用】「知っております」为一般谦让，对个人的敬意不足。","【近义混同】「承る」是「聞く·受ける」的谦让语，与「知道」不合。"]},
{"label":"敬語","q":"本日中にご回答＿＿。","options":["なさいます","いたします","くださいます","さしあげます"],"answer":1,"explain":["【敬語误用】「〜なさる」是尊敬语（对方做），方向相反。","正解。「お／ご〜いたす」是谦让语大形式，用于己方承诺行为。","【敬語误用】「〜てください」表示「请对方做」，方向相反。","【敬語误用】「〜さしあげる」表示「我方施惠」，与承诺语境不合。"]},
]},
{"id":"b1-71","typeKey":"bun1","title":"模拟71 敬語・方向の型③","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"敬語","q":"三年ぶりに社長に＿＿、ご挨拶しました。","options":["ご覧になって","お目にかけて","お目にかかって","お会いになられて"],"answer":2,"explain":["【敬語误用】「ご覧になる」是「看」的尊敬语，方向相反。","【敬語误用】「お目にかける」表示「（我方）给对方看」，方向相反。","正解。「お目にかかる」是「会面·拜见」的谦让语，与「拜见社长」契合。","【敬語误用】「お会いになる」是尊敬语（对方会面），且「なられて」为双重敬语。"]},
{"label":"敬語","q":"お手紙を＿＿、ご依頼の趣旨をくみ取りました。","options":["伺って","拝借して","お目にかかって","拝見して"],"answer":3,"explain":["【近义混同】「伺う」是「聞く·行く」的谦让语，与「读信」不合。","【近义混同】「拝借する」是「借」的谦让语，与「读信」不合。","【近义混同】「お目にかかる」是「会面」的谦让语，与本句不合。","正解。「拝見する」是「見る」的谦让语，与「读信」契合。"]},
{"label":"敬語","q":"ご意見は喜んで＿＿。","options":["承ります","伺います","存じます","拝見します"],"answer":0,"explain":["正解。「承る」是「聞く·受ける」的谦让语，与「恭听意见」的商务书函契合。","【敬語误用】「伺う」同为谦让语，但「喜んで伺います」多用于「前往·询问」，受理意见惯用「承る」。","【近义混同】「存じる」是「知道」的谦让语，与「听意见」不合。","【近义混同】「拝見する」是「看」的谦让语，与本句不合。"]},
{"label":"敬語","q":"その件は後日、担当の者より詳しく＿＿。","options":["ご説明なさいます","ご説明いたします","ご説明ください","ご説明いただきます"],"answer":1,"explain":["【敬語误用】「〜なさる」是尊敬语（对方做），方向相反。","正解。「お／ご〜いたす」是谦让语大形式，用于己方承诺行为。","【敬語误用】「〜てください」表示「请对方做」，方向相反。","【敬語误用】「〜ていただく」表示「承蒙对方做」，方向相反。"]},
{"label":"敬語","q":"母は毎日、店を＿＿。","options":["見てくださいます","見ていらっしゃいます","見ております","ご覧になっております"],"answer":2,"explain":["【敬語误用】「〜てくださる」表示「对方为我做」，方向相反。","【敬語误用】「〜ていらっしゃる」是尊敬语（对方正在…），方向相反。","正解。「〜ておる」是「ている」的谦让语，用于陈述己方（家人）行为。","【敬語误用】「ご覧になる」是「看」的尊敬语，方向相反。"]},
]},
{"id":"b1-72","typeKey":"bun1","title":"模拟72 混在・健康の型","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"最近残業が多くて、少し疲れ＿＿が溜まっている気がする。","options":["まみれ","がち","げ","気味"],"answer":3,"explain":["【接续不合】「〜まみれ」表示「沾满」，接续与语义均不合。","【近义混同】「〜がち」表示频度倾向，与本句的当下状态不合。","【接续不合】「〜げ」表示神情，接续与本句不合。","正解。「〜気味」表示「略带…的当下状态」，与「少し」的轻度契合。"]},
{"label":"近义辨析","q":"医者に止められているのに、タバコを吸わずには＿＿。","options":["いられない","おかない","すまない","ならない"],"answer":0,"explain":["正解。「〜ずにはいられない」表示「禁不住（感情冲动）」，与「忍不住要吸」契合。","【近义混同】「〜ずにはおかない」表示「必然引起」，与本句的冲动不合。","【近义混同】「〜ずにはすまない」表示「不…就过意不去（义务）」，与本句的冲动不合。","【接续不合】「〜ざるを得ない」接ない形-ない（吸わざるを得ない），接续不合。"]},
{"label":"文末表现","q":"この薬を長期で飲み続けると、副作用が出る＿＿。","options":["しまつです","おそれがあります","きらいがあります","かぎりです"],"answer":1,"explain":["【时态肯否错位】「〜始末だ」表示事态已实际恶化，与本句的假设不合。","正解。「〜おそれがある」表示「恐怕会…（风险警告）」，事态未发生。","【近义混同】「〜きらいがある」表示惯常习性的贬义倾向，与本句的风险不合。","【近义混同】「〜かぎりだ」表示「…极了」的感慨，与本句不合。"]},
{"label":"近义辨析","q":"健康のために、毎朝散歩を＿＿いる。","options":["ふりだしに","そばから","欠かさず","てあげて"],"answer":2,"explain":["【近义混同】「振り出しに戻る」为惯用句，接续与本句不合。","【近义混同】「〜そばから」表示「刚…就（被抵消）」的徒劳，与本句相反。","正解。「欠かさず～ている」表示「不间断地持续做」，与健康习惯契合。","【接续不合】「〜てあげる」表示施惠，与本句不合。"]},
{"label":"近义辨析","q":"医師の勧め＿＿、禁煙プログラムに参加することにした。","options":["にかけては","に限って","を問わず","もあって"],"answer":3,"explain":["【近义混同】「〜にかけては」表示「在…方面（技能）」，与本句不合。","【近义混同】「〜に限って」表示「唯独…偏偏」，与本句相反。","【接续不合】「〜を問わず」表示「不分…（并列范畴）」，与本句不合。","正解。「〜もあって」表示「也因为…（原因之一）」，与「劝诱也是参加的原因之一」契合。"]},
]},
{"id":"b1-73","typeKey":"bun1","title":"模拟73 混在・住まいの型","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"新居＿＿、近所の店を一通り回ってみた。","options":["にあたって","における","にわたって","にとって"],"answer":0,"explain":["正解。「〜にあたって」表示「值此（重要行动开始）之际」。","【接续不合】「〜における」是连体形，「新居における、」的接续不合。","【近义混同】「〜にわたって」表示范围持续，与本句的时点不合。","【近义混同】「〜にとって」表示「对…而言」，与本句不合。"]},
{"label":"近义辨析","q":"引っ越しを＿＿、不要な物を大幅に減らした。","options":["あげく","きっかけに","うえで","に至って"],"answer":1,"explain":["【近义混同】「〜あげく」表示消极收场，与本句的正面转变不合。","正解。「〜をきっかけに」表示「以…为契机」。","【近义混同】「〜うえで」表示「在…之后」，与本句的契机义不合。","【接续不合】「〜に至って」表示事态极端化，与本句不合。"]},
{"label":"近义辨析","q":"この町に住んで＿＿、初めて四季の移ろいを感じるようになった。","options":["たびに","たとたん","てからというもの","うちに"],"answer":2,"explain":["【近义混同】「〜たびに」表示「每当…就」，与本句不合。","【近义混同】「〜たとたん」表示「刚一…就（一次性突发）」，与本句的持续不合。","正解。「〜てからというもの」表示「自从…之后（一直）」，强调持续变化。","【近义混同】「〜うちに」表示「在…期间」，与本句的持续不合。"]},
{"label":"接续制约","q":"狭い＿＿、日当たりのいい部屋だ。","options":["わりには","ものの","つつも","ながらも"],"answer":3,"explain":["【接续不合】「〜わりには」须名词の，接续不合。","【接续不合】「〜ものの」须た形·である，接な形容词词干不成立。","【接续不合】「〜つつも」接ます形，接续不合。","正解。「〜ながらも」接名词·な形容词词干，表示「虽然…但是」。"]},
{"label":"接续制约","q":"賃貸契約はした＿＿、引っ越しはまだだ。","options":["ものの","つつも","ながらも","がてら"],"answer":0,"explain":["正解。「〜ものの」接た形，表示「虽然…但是」。","【接续不合】「〜つつも」接ます形，接た形不成立。","【接续不合】「〜ながらも」接ます形·名词，接た形不成立。","【接续不合】「〜がてら」接ます形表示「顺便」，与本句的逆接不合。"]},
]},
{"id":"b1-74","typeKey":"bun1","title":"模拟74 混在・学習の型","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"日程が確定し＿＿、お知らせいたします。","options":["次第で","次第","にあたって","うちに"],"answer":1,"explain":["【接续不合】「〜次第で」接名词，接续不合。","正解。「〜次第」接ます形，表示「一…立刻（随即做）」。","【近义混同】「〜にあたって」表示「值此…之际」，与本句的随即承诺不合。","【近义混同】「〜うちに」表示「在…期间」，与本句不合。"]},
{"label":"呼应制约","q":"答え合わせをし＿＿、自分の弱点が分からない。","options":["ないまでも","ない限り","ないことには","ぬきでは"],"answer":2,"explain":["【接续制约】「〜ないまでも」表示「即便不到…至少」，与本句不合。","【近义混同】「〜ない限り」重条件下的意志·许可，判断句惯用「ないことには」。","正解。「〜ないことには」接ない形，与「分からない」的判断不可能呼应。","【接续不合】「〜ぬきでは」接名词，「し＋ぬきでは」的形态不合。"]},
{"label":"呼应制约","q":"読めば読む＿＿、新しい発見がある。","options":["ばかり","につけ","そばから","ほど"],"answer":3,"explain":["【呼应冲突】「〜ばかり」表示「净是」，与本句不合。","【呼应冲突】「〜につけ」表示「每逢…就」，与ば形呼应不合。","【近义混同】「〜そばから」表示徒劳反复，与本句的累进相反。","正解。「〜ば〜ほど」表示「越…越…」，与「読めば読む」的ば形呼应契合。"]},
{"label":"文末表现","q":"合否は公式発表を見るまでもなく、結果は明白＿＿。","options":["というものだ","というものではない","というところだ","といったらない"],"answer":0,"explain":["正解。「〜というものだ」表示「这才真是…」的本质断言。","【近义混同】「〜というものではない」表示「并非…就行」，方向相反。","【近义混同】「〜というところだ」表示「大概也就…的程度」，与本句相反。","【近义混同】「〜といったらない」表示「难以形容」的感叹，与本句的断言不合。"]},
{"label":"文末表现","q":"毎日少しずつでも解く＿＿。積み重ねが合格を運んでくる。","options":["ものだ","ことだ","わけだ","はずだ"],"answer":1,"explain":["【近义混同】「〜ものだ」表示普遍道理，不针对个人的当下处境。","正解。「〜ことだ」表示「最好…（对个人的具体建议）」，与劝学语境契合。","【近义混同】「〜わけだ」表示「难怪（归结）」，与本句的建议不合。","【近义混同】「〜はずだ」表示「理应（推断）」，与本句的建议不合。"]},
]},
{"id":"b1-75","typeKey":"bun1","title":"模拟75 混在・旅行の型","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"公演は全国十都市＿＿行われる。","options":["に限って","を通じて","にわたって","にとって"],"answer":2,"explain":["【近义混同】「〜に限って」表示「唯独…偏偏」，与本句相反。","【近义混同】「〜を通じて」表示「经由…（中介）」，与本句的范围不合。","正解。「〜にわたって」接范围名词，表示「跨越…」。","【近义混同】「〜にとって」表示「对…而言」，与本句不合。"]},
{"label":"近义辨析","q":"旅行会社＿＿、格安ツアーに申し込んだ。","options":["にわたって","をはじめ","をめぐって","を通じて"],"answer":3,"explain":["【接续不合】「〜にわたって」表示范围持续，与本句不合。","【接续不合】「〜をはじめ」表示「以…为首（列举）」，与本句不合。","【接续不合】「〜をめぐって」表示「围绕…」，与本句不合。","正解。「〜を通じて」表示「经由…（中介）」，与「经旅行社报名」契合。"]},
{"label":"近义辨析","q":"有名な観光地＿＿、宿は早くから埋まる。","options":["ともなると","とあって","としたら","ときたら"],"answer":0,"explain":["正解。「〜ともなると」表示「一到…（程度自然伴随）」，与「名所则早满」的必然契合。","【近义混同】「〜とあって」表示「因为处于特殊状况」，与本句的普遍必然不合。","【近义混同】「〜としたら」表示假定，与本句的必然不合。","【近义混同】「〜ときたら」表示抱怨话题，与本句的中性描述不合。"]},
{"label":"近义辨析","q":"この魅力は観光客＿＿、地元の人々にも新しい発見をもたらす。","options":["を問わず","に限らず","のみならず","はもとより"],"answer":1,"explain":["【接续制约】「〜を問わず」须接一对并列范畴，单个「観光客」不成立。","正解。「〜に限らず」表示「不限于…（扩展到更大范围）」。","【接续制约】「〜のみならず」亦通但「観光客に限らず～にも」的扩展更惯用。","【接续不合】「〜はもとより」须前接名词は，「観光客はもとより」亦通但与「にも」的呼应上「に限らず」更自然。"]},
{"label":"近义辨析","q":"ガイドブックに書いてある＿＿、実際に足を運ばないと分からない。","options":["うちに","たびに","そばから","につけ"],"answer":2,"explain":["【近义混同】「〜うちに」表示「在…期间」，与本句不合。","【近义混同】「〜たびに」表示「每当…就」，与本句不合。","正解。「〜そばから」表示「刚看完就被抹去（纸上得来终觉浅）」的徒劳对照。","【近义混同】「〜につけ」表示「每逢…就」，与本句不合。"]},
]},
{"id":"b1-76","typeKey":"bun1","title":"模拟76 混在・行事の型","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"灯籠流しの夜＿＿、川沿いは多くの人で埋まった。","options":["ときたら","とあれば","ことだから","とあって"],"answer":3,"explain":["【近义混同】「〜ときたら」表示抱怨话题，与本句的正面描写相反。","【近义混同】「〜とあれば」表示「如果是…（就愿意）」，与本句不合。","【接续不合】「〜ことだから」前接人名词の，与本句不合。","正解。「〜とあって」表示「因为处于…特殊状况」，与「当夜的热闹」契合。"]},
{"label":"近义辨析","q":"空も風も、すっかり秋＿＿てきた。","options":["めいて","っぽくなって","げになって","がちになって"],"answer":0,"explain":["正解。「〜めく」接名词，表示「带有…气息」，「秋めいてきた」为季节推移的典型表达。","【近义混同】「〜っぽい」表示静态评价，与本句的推移感不合。","【接续不合】「〜げ」接形容词词干·ます形，「秋げ」不成立。","【接续不合】「〜がち」表示频度倾向，与本句不合。"]},
{"label":"近义辨析","q":"正月の＿＿、実家の匂いを思い出す。","options":["たびに","につけ","につれ","にあたって"],"answer":1,"explain":["【近义混同】「〜たびに」表示中性的反复，缺情感涌起的语感。","正解。「〜につけ」表示「每逢…就（情感自然涌起）」。","【近义混同】「〜につれ」表示「随着…（渐进变化）」，与本句不合。","【近义混同】「〜にあたって」表示「值此…之际」，与本句不合。"]},
{"label":"近义辨析","q":"卒業、就職、結婚と、この一年はおめでたいこと＿＿だった。","options":["まみれ","だらけ","ずくめ","っぽい"],"answer":2,"explain":["【接续不合】「〜まみれ」限液体·粉末附着，不能接抽象名词。","【近义混同】「〜だらけ」多接负面事物的「满是」，且无系列感。","正解。「〜ずくめ」表示「净是…（清一色系列）」，与列举的系列喜事契合。","【接续不合】「〜っぽい」表示气质倾向，与本句的列举不合。"]},
{"label":"近义辨析","q":"この祭りの太鼓は、この土地＿＿の音だ。","options":["をはじめ","に限らず","をおいて","ならでは"],"answer":3,"explain":["【接续不合】「〜をはじめ」表示「以…为首（列举）」，与本句不合。","【近义混同】「〜に限らず」表示「不限于」，与本句相反。","【接续不合】「〜をおいて」接人名词＋否定，「土地をおいての音」不成立。","正解。「〜ならではの」表示「唯有…才有的」。"]},
]},
{"id":"b1-77","typeKey":"bun1","title":"模拟77 混在・報道の型","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"少子化＿＿、大学の経営難が深刻になっている。","options":["に伴って","に応じて","に限り","に先立って"],"answer":0,"explain":["正解。「〜に伴って」表示「伴随…（大规模·书面）」。","【近义混同】「〜に応じて」表示「根据…相应调整（政策性）」，与本句的自然联动不合。","【接续不合】「〜に限り」表示「仅限于…」，与本句不合。","【近义混同】「〜に先立って」表示「在…之前」，与本句不合。"]},
{"label":"文末表现","q":"このまま放置すれば、災害が拡大する＿＿。","options":["しまつです","おそれがあります","きらいがあります","というものです"],"answer":1,"explain":["【时态肯否错位】「〜始末だ」表示事态已实际恶化，与本句的假设不合。","正解。「〜おそれがある」表示「恐怕会…（公告体风险警告）」。","【近义混同】「〜きらいがある」表示惯常习性，与本句的风险不合。","【近义混同】「〜というものだ」表示「这才真是」的断言，与本句不合。"]},
{"label":"文末表现","q":"対応を誤った結果、被害は拡大する＿＿だ。","options":["きらい","おそれ","始末","かぎり"],"answer":2,"explain":["【近义混同】「〜きらいがある」表示惯常习性，与本句不合。","【时态肯否错位】「〜おそれがある」表示事态未发生的风险，与本句的既成不合。","正解。「〜始末だ」表示「落到…的地步（消极归結，已发生）」。","【近义混同】「〜かぎりだ」表示感慨顶点，与本句相反。"]},
{"label":"文末表现","q":"この不況の原因は、世界的な需要の低下＿＿。","options":["ものだ","にすぎない","までもない","にほかならない"],"answer":3,"explain":["【近义混同】「〜ものだ」表示感慨·本性·忠告，与本句的断言不合。","【近义混同】「〜にすぎない」表示「不过是」的贬低，与本句的断定相反。","【近义混同】「〜までもない」表示「没必要」，与本句不合。","正解。「〜にほかならない」表示「正是…（强断定）」。"]},
{"label":"近义辨析","q":"この改修を怠れば、大規模な事故＿＿。","options":["につながりかねない","につながりがたい","につながらざるを得ない","につながりかねる"],"answer":0,"explain":["正解。「〜かねない」接ます形，表示「很可能（酿成坏事）」。","【近义混同】「〜がたい」表示「心理上难以」，与本句的可能性不合。","【接续不合】「〜ざるを得ない」接ない形-ない，接续不合。","【近义混同】「〜かねる」表示「难以（婉拒）」，方向相反。"]},
]},
{"id":"b1-78","typeKey":"bun1","title":"模拟78 混在・家族の型","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"兄は何もしない＿＿、口だけは達者だ。","options":["わりには","くせに","にしては","ものの"],"answer":1,"explain":["【近义混同】「〜わりには」表示中性评价，无谴责。","正解。「〜くせに」表示「明明…却（指责）」，与「什么都不做却伶牙俐齿」契合。","【近义混同】「〜にしては」表示客观评价，无谴责。","【接续不合】「〜ものの」须た形·である，接辞书形不成立。"]},
{"label":"文末表现","q":"親というのは、いくつになっても子を案じる＿＿。","options":["わけだ","ことだ","ものだ","はずだ"],"answer":2,"explain":["【近义混同】「〜わけだ」表示「难怪（归结）」，与本句不合。","【近义混同】「〜ことだ」表示对个人的建议，与本句的本性描述不合。","正解。「〜ものだ」（本性用法）表示「本来就是如此」的普遍本性。","【近义混同】「〜はずだ」表示「理应（推断）」，与本句不合。"]},
{"label":"近义辨析","q":"家計が逼迫しているので、支出の見直しを＿＿。","options":["するしかない","するずにはいられない","しずにはすまない","せざるを得ない"],"answer":3,"explain":["【近义混同】「〜しかない」表示「只能（别无他法）」，与本句的「被迫」语气有别。","【接续不合】「〜ずにはいられない」接ない形（せずには…），「するずには」不成立且表感情冲动。","【接续不合】「〜ずにはすまない」接ない形，接续不合。","正解。「〜ざるを得ない」表示「迫于外部状况不得不」，与「家计所迫」契合。"]},
{"label":"近义辨析","q":"うちの息子は、最近感情的になってきて、子ども＿＿ところがある。","options":["っぽい","げ","がち","気味"],"answer":0,"explain":["正解。「〜っぽい」接名词，表示「有…的味道」，「子どもっぽい」为惯用表达。","【接续不合】「〜げ」接形容词词干·ます形，「子どもげ」不成立。","【接续不合】「〜がち」表示频度倾向，接续与本句不合。","【接续不合】「〜気味」表示当下状态，接续与语义均不合。"]},
{"label":"近义辨析","q":"花見＿＿、近所の公園を散歩するのが日課だ。","options":["かたわら","がてら","ながら","つつ"],"answer":1,"explain":["【接续不合】「〜かたわら」接名词の·辞书形，表示以某身份为本业的兼做，接续不合。","正解。「〜がてら」接ます形，表示「顺便、捎带（主中带副）」。","【接续不合】「〜ながら」接名词表示「保持…原状」，与本句不合。","【接续不合】「〜つつ」接ます形表示并行动作，与本句的主副关系有别。"]},
]},
{"id":"b1-79","typeKey":"bun1","title":"模拟79 混在・仕事の型","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"打ち合わせを重ねた＿＿、企画は白紙に戻った。","options":["うえで","末に","あげく","に先立って"],"answer":2,"explain":["【近义混同】「〜うえで」表示「在…之后」，与本句的收场义不合。","【近义混同】「〜末に」表示中性的最终结果，与本句的消极色彩不合。","正解。「〜あげく」接た形，表示「…的结果（消极收场）」，与「白纸撤回」契合。","【近义混同】「〜に先立って」表示「在…之前」，与本句相反。"]},
{"label":"近义辨析","q":"自分のミスで部課全体に迷惑をかけたのだから、謝らない＿＿。","options":["どころではない","ではいられない","ではおかない","ではすまない"],"answer":3,"explain":["【近义混同】「〜どころではない」表示「哪里谈得上」，与本句不合。","【近义混同】「〜ないではいられない」表示「禁不住（感情冲动）」，与本句的义务不合。","【近义混同】「〜ないではおかない」表示「必然引起」，与本句不合。","正解。「〜ないではすまない」表示「不…就过意不去（社会义务）」。"]},
{"label":"近义辨析","q":"退職する先輩の今後のご活躍を祈って＿＿。","options":["やまない","おかない","いられない","すまない"],"answer":0,"explain":["正解。「〜てやまない」接祈愿类动词て形，表示「衷心…不已」。","【接续不合】「〜(ず)にはおかない」接ない形，接续不合。","【接续不合】「〜(ず)にはいられない」接ない形，接续不合。","【接续不合】「〜(ず)にはすまない」接ない形，接续不合。"]},
{"label":"近义辨析","q":"初めての担当で失敗続きだったが、先輩の励まし＿＿、なんとか乗り越えた。","options":["をよそに","に支えられ","をものともせず","をかまわず"],"answer":1,"explain":["【近义混同】「〜をよそに」表示「无视（外界的声音）」，与本句的感恩相反。","正解。「〜に支えられ」表示「在…的支持下」，与「先辈的鼓励」契合。","【近义混同】「〜をものともせず」表示「不把…放在眼里」，与本句相反。","【接续不合】「〜もかまわず」接名词も，「励ましをかまわず」不成立。"]},
{"label":"近义辨析","q":"突然のシステム障害＿＿、納期の変更を余儀なくされた。","options":["にかけて","にとって","を受けて","に限って"],"answer":2,"explain":["【近义混同】「〜にかけては」表示「在…方面（技能）」，与本句不合。","【近义混同】「〜にとって」表示「对…而言」，与本句的因果不合。","正解。「〜を受けて」表示「由于…（外部事态而应对）」，与「被迫改期」契合。","【近义混同】「〜に限って」表示「唯独…偏偏」，与本句不合。"]},
]},
{"id":"b1-80","typeKey":"bun1","title":"模拟80 逆接・让步の第六弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"接续制约","q":"申請は済ませた＿＿、許可はまだ下りていない。","options":["がてら","つつも","ながらも","ものの"],"answer":3,"explain":["【接续不合】「〜がてら」接ます形表示「顺便」，与本句的逆接不合。","【接续不合】「〜つつも」接ます形，接た形不成立。","【接续不合】「〜ながらも」接ます形·名词，接た形不成立。","正解。「〜ものの」接た形，表示「虽然…但是」。"]},
{"label":"接续制约","q":"都会＿＿、物価の安い街だ。","options":["ながらも","ものの","つつも","わりには"],"answer":0,"explain":["正解。「〜ながらも」接名词·な形容词词干，表示「虽然…但是」。","【接续不合】「〜ものの」须た形·である，接续不合。","【接续不合】「〜つつも」接ます形，接续不合。","【接续不合】「〜わりには」须名词の，接续不合。"]},
{"label":"近义辨析","q":"春＿＿、山の朝風はまだ冷たい。","options":["といっても","とはいえ","ものの","ながらも"],"answer":1,"explain":["【近义混同】「〜といっても」接名词表示「说是…其实（名不副实）」，与本句不合。","正解。「〜とはいえ」可直接接名词，表示「虽说是…（也）」。","【接续不合】「〜ものの」须た形·である，接续不合。","【接续不合】「〜ながらも」接续不合（春ながらも✗）。"]},
{"label":"近义辨析","q":"分かっている＿＿、つい余計なことを言ってしまう。","options":["ものの","ながら","つつ","がてら"],"answer":2,"explain":["【接续不合】「〜ものの」须た形·である，接续不合。","【接续不合】「〜ながら」接ます形亦可（分かりながら），但「いながら」不成立。","正解。「〜つつ」接ます形，表示「明知…却（书面自责）」，「分かっているつつ」稍不自然——本句惯用「分かっていながら」。","【接续不合】「〜がてら」接ます形表示「顺便」，与本句不合。"]},
{"label":"近义辨析","q":"失敗を恐れる＿＿、挑戦をためらう若手が増えている。","options":["ことから","ばかりに","だけあって","あまり"],"answer":3,"explain":["【近义混同】「〜ことから」表示客观缘由，与本句不合。","【接续不合】「〜ばかりに」接た形·な形，接辞书形「恐れる」不成立。","【近义混同】「〜だけあって」表示名实相符，与本句不合。","正解。「〜のあまり」的省略形「恐れるあまり」，表示「因过分…而」。"]},
]},
{"id":"b1-81","typeKey":"bun1","title":"模拟81 逆接・让步の第七弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"震災からの復興は、被害＿＿の状態だ。","options":["どころの騒ぎではない","わりには","にすぎない","をはじめ"],"answer":0,"explain":["正解。「〜どころの騒ぎではない」表示「远非…的状态（程度严重）」。","【近义混同】「〜わりには」表示「与程度不相称」，与本句不合。","【近义混同】「〜にすぎない」表示「不过是」，与本句不合。","【接续不合】「〜をはじめ」表示列举之首，与本句不合。"]},
{"label":"近义辨析","q":"社長＿＿、肩の荷が下りることはない。","options":["とあれば","ともなれば","としたら","ときたら"],"answer":1,"explain":["【近义混同】「〜とあれば」表示「如果是…（就愿意）」，与本句不合。","正解。「〜ともなれば」表示「一到…（程度自然伴随）」。","【近义混同】「〜としたら」表示假定，与本句的必然不合。","【近义混同】「〜ときたら」表示抱怨话题，与本句不合。"]},
{"label":"近义辨析","q":"留学する＿＿、語学学校に通う程度だ。","options":["からといって","とはいえ","といっても","というものの"],"answer":2,"explain":["【近义混同】「〜からといって」表示「不能仅因…就」，与本句不合。","【近义混同】「〜とはいえ」承接前文做部分让步的书面表达，与本句的口语补充不合。","正解。「〜といっても」表示「虽说…（程度大打折扣）」。","【接续不合】「〜というものの」非固定文型。"]},
{"label":"近义辨析","q":"彼は以前＿＿、後輩への気配りが増えた。","options":["に反して","にひきかえ","に限らず","にもまして"],"answer":3,"explain":["【近义混同】「〜に反して」表示「与…相反」，与本句不合。","【近义混同】「〜にひきかえ」表示「与…正相反」的对照，与本句的同向递进不合。","【近义混同】「〜に限らず」表示「不限于…」，与本句不合。","正解。「〜にもまして」表示「比…更甚」，与「比以前更体贴」的递进契合。"]},
{"label":"近义辨析","q":"前回の完敗＿＿、今回は接戦に持ち込んだ。","options":["にひきかえ","に反して","に対して","に比べて"],"answer":0,"explain":["正解。「〜にひきかえ」接名词，表示「与…正相反（落差鲜明）」。","【接续不合】「〜に反して」接予想·期待·ルール，「完敗に反して」不成立。","【接续不合】「〜に対して」表对照须「の＋に対して」，接续不合。","【近义混同】「〜に比べて」表示中性比较，不承载「从惨败到接战」的落差感。"]},
]},
{"id":"b1-82","typeKey":"bun1","title":"模拟82 原因・理由の第五弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"町並みが江戸の姿をとどめる＿＿、観光地として選ばれた。","options":["だけあって","ことから","せいで","あまり"],"answer":1,"explain":["【近义混同】「〜だけあって」表示名实相符的称赞，与本句的缘由不合。","正解。「〜ことから」表示客观缘由，是「由缘由选定·命名」的典型用法。","【近义混同】「〜せいで」表示归咎负面原因，与本句不合。","【接续不合】「〜のあまり」前接感情名词，接续不合。"]},
{"label":"近义辨析","q":"名門校の出身＿＿、教え方にひと味違う。","options":["せいで","ばかりに","だけあって","あまり"],"answer":2,"explain":["【近义混同】「〜せいで」表示归咎，与本句相反。","【近义混同】「〜ばかりに」表示负面归因，与本句的称赞相反。","正解。「〜だけあって」表示「不愧是…（名实相符）」，与「さすが」呼应的语境契合。","【接续不合】「〜のあまり」前接感情名词，接续不合。"]},
{"label":"近义辨析","q":"久しぶりの再会＿＿、会場は初めから終わりまで感動に包まれていた。","options":["ときたら","とあれば","ことだから","とあって"],"answer":3,"explain":["【近义混同】「〜ときたら」表示抱怨话题，与本句的正面描写相反。","【近义混同】「〜とあれば」表示「如果是…（就愿意）」，接意愿，与本句不合。","【接续不合】「〜ことだから」前接人名词の，与本句不合。","正解。「〜とあって」表示「因为处于…特殊状况」，与「再会的感动」契合。"]},
{"label":"近义辨析","q":"冷房の効きすぎた部屋に一日中いた＿＿、体がだるくなった。","options":["せいで","おかげで","だけあって","ことから"],"answer":0,"explain":["正解。「〜せいで」表示「都怪…（归咎负面原因）」，与「身体发沉」的抱怨契合。","【近义混同】「〜おかげで」表示得益于（正面），方向相反。","【近义混同】「〜だけあって」表示名实相符，与本句不合。","【近义混同】「〜ことから」表示客观缘由，与本句的归咎不合。"]},
{"label":"近义辨析","q":"追加調査を怠った＿＿、報告書の信頼性を疑われた。","options":["だけあって","ばかりに","おかげで","ことから"],"answer":1,"explain":["【近义混同】「〜だけあって」表示名实相符，与本句相反。","正解。「〜ばかりに」接た形，表示「只因…（引发负面结果）」，与「被质疑」的悔恨契合。","【近义混同】「〜おかげで」表示得益于，方向相反。","【近义混同】「〜ことから」表示客观缘由，与本句不合。"]},
]},
{"id":"b1-83","typeKey":"bun1","title":"模拟83 契約・時点の第六弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"赴任＿＿、家族の生活環境を整えるべきだ。","options":["にわたって","における","にあたって","にとって"],"answer":2,"explain":["【近义混同】「〜にわたって」表示范围持续，与本句的时点不合。","【接续不合】「〜における」是连体形，「赴任における、」的接续不合。","正解。「〜にあたって」表示「值此（重要行动开始）之际」。","【近义混同】「〜にとって」表示「对…而言」，与本句不合。"]},
{"label":"近义辨析","q":"退職＿＿、長年の感謝を込めて挨拶を述べた。","options":["に限って","につれて","に応じて","に際して"],"answer":3,"explain":["【近义混同】「〜に限って」表示「唯独…偏偏」，与本句不合。","【近义混同】「〜につれて」表示「随着…（自然联动）」，与本句不合。","【近义混同】「〜に応じて」表示「根据…相应变化」，与本句不合。","正解。「〜に際して」表示「当…之际（书面）」。"]},
{"label":"近义辨析","q":"制度改正を＿＿、申請手続きが簡素化された。","options":["契機に","にあたって","に沿って","をよそに"],"answer":0,"explain":["正解。「〜を契機に」表示「以…为转机（重大变化，书面）」。","【近义混同】「〜にあたって」表示主体「在行动之际」的意志，与本句的制度转变不合。","【接续不合】「〜に沿って」表示「遵循」，与本句不合。","【近义混同】「〜をよそに」表示「无视…」，与本句的因果相反。"]},
{"label":"近义辨析","q":"両者の意見を聞いた＿＿、結論を出したい。","options":["あげく","うえで","に先立って","ばかりに"],"answer":1,"explain":["【近义混同】「〜あげく」表示消极收场，与本句的中性先后不合。","正解。「〜たうえで」表示「在…之后（再进行下一步）」。","【近义混同】「〜に先立って」表示「在…之前」，先后相反。","【近义混同】「〜ばかりに」表示负面归因，与本句不合。"]},
{"label":"近义辨析","q":"交渉が決裂＿＿、申し込み自体が取り消された。","options":["に際して","に限って","に至っては","に先立って"],"answer":2,"explain":["【近义混同】「〜に際して」表示「当…之际」，与本句的事态极端化不合。","【近义混同】「〜に限って」表示「唯独…偏偏」，与本句不合。","正解。「〜に至っては」表示「事态发展到…地步（极端例）」。","【近义混同】「〜に先立って」表示「在…之前」，与本句不合。"]},
]},
{"id":"b1-84","typeKey":"bun1","title":"模拟84 強調・断定の第五弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"文末表现","q":"安易に人を責めるのは、軽率＿＿。","options":["といったらない","というものではない","というところだ","というものだ"],"answer":3,"explain":["【近义混同】「〜といったらない」表示「难以形容」的感叹，与本句的断言不合。","【近义混同】「〜というものではない」表示「并非…就行」，方向相反。","【近义混同】「〜というところだ」表示「大概也就…的程度」，与本句相反。","正解。「〜というものだ」表示「这才真是…」的本质断言。"]},
{"label":"文末表现","q":"十年の研究が実ったのだ。努力が実を結ばない＿＿。","options":["わけがない","わけではない","わけにはいかない","ものだ"],"answer":0,"explain":["正解。「〜わけがない」表示「不可能（有充分理由的否定）」。","【近义混同】「〜わけではない」表示「并非…（部分否定）」，与本句的强否定不合。","【近义混同】「〜わけにはいかない」表示「碍于情理不能」，与本句不合。","【近义混同】「〜ものだ」表示感慨·本性·忠告，与本句的否定不合。"]},
{"label":"文末表现","q":"彼の指導には、若手を伸ばす何か＿＿。","options":["ものだ","ものがある","わけだ","というものだ"],"answer":1,"explain":["【近义混同】「〜ものだ」表示感慨·本性·忠告，与本句的「具有特质」不合。","正解。「〜ものがある」表示「确有…之处（由衷感叹）」。","【近义混同】「〜わけだ」表示「难怪（归结）」，与本句不合。","【近义混同】「〜というものだ」表示「这才真是」的断言，与本句不合。"]},
{"label":"文末表现","q":"十年前の古い機械が、まさか高値で取引される＿＿。","options":["というものだ","とはいえ","とは","にほかならない"],"answer":2,"explain":["【近义混同】「〜というものだ」表示「这才真是」的断言，与本句不合。","【近义混同】「〜とはいえ」表示「虽说如此」的部分让步，与本句的惊愕不合。","正解。「〜とは」接句子，表示「竟然…（惊愕，句尾省略）」。","【接续不合】「〜にほかならない」接名词，接句子不成立。"]},
{"label":"文末表现","q":"三年ぶりの実家の味。その喜び＿＿。","options":["とはいえ","というところだ","というものだ","といったらない"],"answer":3,"explain":["【近义混同】「〜とはいえ」表示部分让步，与本句不合。","【近义混同】「〜というところだ」表示「大概也就…的程度」，与本句相反。","【近义混同】「〜というものだ」表示冷静的断言，与本句的激动不合。","正解。「〜といったらない」表示「…得难以形容」的极端感叹。"]},
]},
{"id":"b1-85","typeKey":"bun1","title":"模拟85 文末・評価の第五弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"文末表现","q":"こんな下手な企画、通る＿＿。","options":["ものか","ものだ","までもない","というものだ"],"answer":0,"explain":["正解。「〜ものか」接可能形·辞书形，表示「怎么可能（强烈反问）」。","【近义混同】「〜ものだ」表示感慨·本性·忠告，与本句的反问相反。","【近义混同】「〜までもない」表示「没必要」，与本句不合。","【近义混同】「〜というものだ」表示「这才真是」的断言，与本句相反。"]},
{"label":"文末表现","q":"詳細は公式サイトを見れば分かる。わざわざ問い合わせる＿＿。","options":["まい","までもない","どころではない","ものではない"],"answer":1,"explain":["【近义混同】「〜まい」表示否定意志，与本句的「没必要」不合。","正解。「〜までもない」接辞书形，表示「没必要…」。","【近义混同】「〜どころではない」表示「哪里谈得上」，与本句不合。","【近义混同】「〜ものではない」表示「不该…」的说教，与本句不合。"]},
{"label":"文末表现","q":"彼は運動＿＿、階段を上るのさえつらい。","options":["というものだ","どころではない","どころか","にすぎない"],"answer":2,"explain":["【近义混同】「〜というものだ」表示「这才真是」的断言，与本句不合。","【近义混同】「〜どころではない」表示「哪里谈得上（无暇）」，与本句的递进不合。","正解。「〜どころか」表示「非但…（更甚）」。","【近义混同】「〜にすぎない」表示「不过是」，与本句不合。"]},
{"label":"近义辨析","q":"あの事件は、マスコミを賑わ＿＿。","options":["ざるを得ない","ずにはすまない","ずにはいられない","ずにはおかない"],"answer":3,"explain":["【近义混同】「〜ざるを得ない」表示「迫于外部不得不」，与本句不合。","【近义混同】「〜ずにはすまない」表示「不…就过意不去（义务主体）」，与本句不合。","【近义混同】「〜ずにはいられない」表示「禁不住（情感冲动）」，与本句不合。","正解。「〜ずにはおかない」表示「必然会引起…（主语可为事态）」。"]},
{"label":"文末表现","q":"彼は二度と東京へは来る＿＿と誓って出ていった。","options":["まい","ものか","までもない","ものだ"],"answer":0,"explain":["正解。「〜まい」表示「决不再…」的意志否定，与「誓う」的意志呼应契合。","【近义混同】「〜ものか」为反问句，与「誓う」的意志呼应不合。","【近义混同】「〜までもない」表示「没必要」，与本句不合。","【近义混同】「〜ものだ」表示感慨·本性·忠告，与本句不合。"]},
]},
{"id":"b1-86","typeKey":"bun1","title":"模拟86 様態・傾向の第五弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"彼女はうれし＿＿、涙を浮かべた。","options":["そうで","げに","っぽく","気味に"],"answer":1,"explain":["【接续不合】「〜そう」接形容词词干须去い加そう（うれしそうで），「うれしそうで」不成立。","正解。「〜げ」接形容词词干，表示「…的神情」，「うれしげに」为惯用表达。","【接续不合】「〜っぽい」接形容词词干表示倾向，「うれしppyく」与本句的神情不合。","【接续不合】「〜気味」表示状态，「うれし気味に」不自然。"]},
{"label":"近义辨析","q":"彼は忘れ＿＿ので、大事な予定はメモするようにしている。","options":["気味","げ","っぽい","まみれ"],"answer":2,"explain":["【近义混同】「〜気味」表示「略带…的当下状态」，与本句的性格倾向不合。","【接续不合】「〜げ」表示神情，接续与本句的倾向不合。","正解。「〜っぽい」接ます形，表示「容易…」，「忘れっぽい」为固定表达。","【接续不合】「〜まみれ」表示「沾满」，接续与语义均不合。"]},
{"label":"近义辨析","q":"夜更かしが続いて、少し太り＿＿だ。","options":["っぽい","がち","げ","気味"],"answer":3,"explain":["【接续不合】「〜っぽい」接ます形表示性格倾向，「太りっぽい」与本句的当下状态有别。","【近义混同】「〜がち」表示频度倾向，与本句的当下状态不合。","【接续不合】「〜げ」表示神情，接续与本句不合。","正解。「〜気味」接ます形 stem，表示「略带…的当下状态」，「太り気味」为惯用表达。"]},
{"label":"近义辨析","q":"引っ越しシーズンは、 перевоз屋が予約取り＿＿になる。","options":["がち","気味","げ","っぽい"],"answer":0,"explain":["正解。「〜がち」接ます形 stem，表示「经常处于某状态」，与旺季的频度倾向契合。","【近义混同】「〜気味」表示当下略带的状态，与本句的季节倾向不合。","【接续不合】「〜げ」表示神情，接续与本句不合。","【接续不合】「〜っぽい」表示性格倾向，与本句的频度不合。"]},
{"label":"近义辨析","q":"庭の梅もすっかり春＿＿きた。","options":["っぽく","めいて","げに","気味に"],"answer":1,"explain":["【近义混同】「〜っぽい」表示静态评价，与本句的推移感不合。","正解。「〜めく」接名词，表示「带有…气息」，「春めいてきた」为季节推移的典型表达。","【接续不合】「〜げ」接形容词词干·ます形，「春げ」不成立。","【接续不合】「〜気味」表示状态，「春気味」不自然。"]},
]},
{"id":"b1-87","typeKey":"bun1","title":"模拟87 基準・対応の第五弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"調査結果＿＿、報告書をまとめた。","options":["に応じて","に沿って","に基づいて","に限って"],"answer":2,"explain":["【近义混同】「〜に応じて」表示「根据…相应变化」，与本句不合。","【近义混同】「〜に沿って」表示「沿着…（规程·方针）」，与调查结果的依据义有别。","正解。「〜に基づいて」表示「基于…（事实·依据）」。","【近义混同】「〜に限って」表示「唯独…偏偏」，与本句不合。"]},
{"label":"近义辨析","q":"日程表＿＿、作業を進めてください。","options":["に即して","に基づいて","に応じて","に沿って"],"answer":3,"explain":["【近义混同】「〜に即して」表示「紧扣现实」，与本句不合。","【近义混同】「〜に基づいて」重「依据事实·数据」，流程的沿袭用「に沿って」。","【近义混同】「〜に応じて」表示「根据…相应变化」，与本句不合。","正解。「〜に沿って」表示「沿着…（规程·流程进行）」。"]},
{"label":"近义辨析","q":"研修で得た知識＿＿、実務に生かしてほしい。","options":["をもとに","をきっかけに","に応じて","をめぐって"],"answer":0,"explain":["正解。「〜をもとに」表示「以…为素材·参考」。","【近义混同】「〜をきっかけに」表示「以…为契机」，与本句的素材义不合。","【近义混同】「〜に応じて」表示「根据…相应变化」，与本句不合。","【接续不合】「〜をめぐって」表示「围绕…」，与本句不合。"]},
{"label":"近义辨析","q":"先行事例＿＿、計画を練り直した。","options":["をきっかけに","を踏まえて","をはじめ","をめぐって"],"answer":1,"explain":["【近义混同】「〜をきっかけに」表示「以…为契机」，与本句的依据义不合。","正解。「〜を踏まえて」表示「立足于…（考虑·判断）」。","【接续不合】「〜をはじめ」表示「以…为首（列举）」，与本句不合。","【接续不合】「〜をめぐって」表示「围绕…」，与本句不合。"]},
{"label":"近义辨析","q":"需要の増減＿＿、生産量を調整する。","options":["に伴って","につれて","に応じて","にしたがって"],"answer":2,"explain":["【近义混同】「〜に伴って」表示伴随发生，与本句的对应措施不合。","【近义混同】「〜につれて」表示自然联动，与本句的主动调整不合。","正解。「〜に応じて」表示「根据…相应调整（政策性）」。","【近义混同】「〜にしたがって」表示遵从，与本句不合。"]},
]},
{"id":"b1-88","typeKey":"bun1","title":"模拟88 限定・範囲の第四弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"この資格は実務経験の有無＿＿、誰でも受験できる。","options":["にかけては","に限らず","はもとより","を問わず"],"answer":3,"explain":["【近义混同】「〜にかけては」表示「在…方面（技能）」，与本句不合。","【接续制约】「〜に限らず」多接单个范畴的扩展，「有無」的对立范畴惯用「を問わず」。","【接续不合】「〜はもとより」表示递进列举，与本句不合。","正解。「〜を問わず」接「有無」等对立范畴，表示「不限…」。"]},
{"label":"近义辨析","q":"この悩みは現代社会＿＿、あらゆる時代に通じるものだ。","options":["に限らず","を問わず","のみならず","に限って"],"answer":0,"explain":["正解。「〜に限らず」表示「不限于…（扩展到更大范围）」。","【接续制约】「〜を問わず」须接一对并列范畴，「现代社会」单个名词不成立。","【接续制约】「〜のみならず」亦通但「に限らず～にも」的扩展更自然。","【近义混同】「〜に限って」表示「唯独…偏偏」，与本句相反。"]},
{"label":"近义辨析","q":"漢字＿＿、日本語の基礎も怪しい。","options":["はもとより","はおろか","のみならず","もさることながら"],"answer":1,"explain":["【近义混同】「〜はもとより」用于中性·正面递进，与本句的贬降不合。","正解。「〜はおろか」表示「…自不必说，连…也（消极递进）」。","【近义混同】「〜のみならず」为中性递进，不承载消极语感。","【接续不合】「〜もさることながら」用于两点并置褒扬，与本句相反。"]},
{"label":"近义辨析","q":"この日本酒は国産米＿＿、水にもこだわっている。","options":["のみならず","はおろか","はもとより","ばかりか"],"answer":2,"explain":["【近义混同】「〜のみならず」为中性递进，与本句的「こだわり」呼应上「はもとより」更典型。","【近义混同】「〜はおろか」多接消极递进，与本句的正面展开不合。","正解。「〜はもとより」表示「…自不必说（中性·正面递进）」。","【接续制约】「〜ばかりか」多接消极递进，与本句不合。"]},
{"label":"近义辨析","q":"彼の活躍は国内＿＿、海外のメディアでも報じられた。","options":["をおいて","はおろか","ならでは","のみならず"],"answer":3,"explain":["【接续不合】「〜をおいて」接人名词＋否定，与本句不合。","【近义混同】「〜はおろか」多接消极递进，与本句的正面展开不合。","【接续不合】「〜ならでは」表示「唯有…才有的」，与本句不合。","正解。「〜のみならず」表示「不仅…而且…」的书面递进。"]},
]},
{"id":"b1-89","typeKey":"bun1","title":"模拟89 複合助詞の第五弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"シンポジウムは大阪＿＿開催された。","options":["において","にとって","にかけて","にわたって"],"answer":0,"explain":["正解。「〜において」表示「在…（场所·场合）」，书面体。","【近义混同】「〜にとって」表示「对…而言」，与本句不合。","【近义混同】「〜にかけて」表示「覆盖（范围）」，与本句的场所不合。","【近义混同】「〜にわたって」表示范围·期间持续，不接场所名词。"]},
{"label":"近义辨析","q":"詳しい担当者＿＿、原因は分かっていない。","options":["だに","すら","たりとも","のみ"],"answer":1,"explain":["【接续不合】「〜だに」多用于「夢にだに思わぬ」等惯用，与本句不合。","正解。「〜すら」表示「连…都（书面极端例）」。","【近义混同】「〜たりとも」与最小量搭配，与「担当者」不合。","【近义混同】「〜のみ」表示「唯有」，与本句相反。"]},
{"label":"近义辨析","q":"本店は三月末日＿＿、営業を終了いたします。","options":["にわたって","を限りに","をもって","をもとに"],"answer":2,"explain":["【接续不合】「〜にわたって」表示范围持续，与时点不合。","【近义混同】「〜を限りに」带诀别语气，中性契约惯用「をもって」。","正解。「〜をもって」表示「自…（时限）」，公告体中性表述。","【近义混同】「〜をもとに」表示「以…为素材」，与本句不合。"]},
{"label":"近义辨析","q":"読者＿＿の新聞だ。信頼を裏切らない報道を続けたい。","options":["をめぐる","に基づく","にかかわる","あっての"],"answer":3,"explain":["【接续不合】「〜をめぐる」修饰争论·对立的话题，与本句不合。","【近义混同】「〜に基づく」表示「基于…（依据）」，与本句的存在依存不合。","【近义混同】「〜にかかわる」表示「关系到…」，与本句相反。","正解。「〜あっての＋名词」表示「有…才有…」。"]},
{"label":"近义辨析","q":"先月の火災＿＿、避難経路の再点検を行った。","options":["に鑑み","に応じて","に則って","に限り"],"answer":0,"explain":["正解。「〜に鑑み」表示「鉴于…（公文语决策缘由）」。","【近义混同】「〜に応じて」表示「根据…相应变化」，与本句的缘由不合。","【近义混同】「〜に則って」表示「依照（惯例·先例）」，与本句不合。","【接续不合】「〜に限り」表示「仅限于…」，与本句不合。"]},
]},
{"id":"b1-90","typeKey":"bun1","title":"模拟90 条件・仮定の第五弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"責任ある立場＿＿、発言には慎重であってもらいたい。","options":["とはいえ","である以上は","ならでは","どころか"],"answer":1,"explain":["【近义混同】「〜とはいえ」表示「虽说如此」的让步，与本句的义务不合。","正解。「〜以上(は)」接「である以上」，表示「既然是…就（必须）」。","【接续不合】「〜ならでは」表示「唯有…才有的」，与本句不合。","【近义混同】「〜どころか」表示「非但…反而」，与本句不合。"]},
{"label":"呼应制约","q":"主治医が許可しない＿＿、退院はできない。","options":["ようでは","ないことには","ない限り","ないまでも"],"answer":2,"explain":["【近义混同】「〜ようでは」表示「照…这样下去」的预判，与本句的条件不合。","【接续不合】「〜ないことには」与「許可しない」重叠成双重否定，「許可しない＋ないことには」不成立。","正解。「〜ない限り」表示「只要不…就（不）」，与「不许可就不出院」的许可条件契合。","【接续制约】「〜ないまでも」接续与本句不合。"]},
{"label":"呼应制约","q":"この道＿＿通れば、一時間は短縮できる。","options":["すら","でも","こそ","さえ"],"answer":3,"explain":["【呼应冲突】「〜すら」表示「连…都」的极端例，与ば形条件不合。","【近义混同】「〜でも」表示「比如…之类（轻列举）」，缺最小条件的强调。","【呼应冲突】「〜こそ」表示强调，与ば形条件呼应不合。","正解。「〜さえ〜ば」表示「只要…就（最小充分条件）」。"]},
{"label":"近义辨析","q":"言い間違え＿＿、取り返しのつかない事態になる。","options":["しようものなら","しない限り","しだい","しかねる"],"answer":0,"explain":["正解。「〜(よ)うものなら」接意志形，表示「一旦…的话（后果严重）」。","【近义混同】「〜ない限り」表示「只要不…就（不）」，与本句不合。","【近义混同】「〜次第」接ます形表示「一…立刻」，与本句的警告不合。","【接续不合】「〜かねる」接ます形表示「难以（婉拒）」，与本句不合。"]},
{"label":"呼应制约","q":"目で確かめ＿＿、真実は分からない。","options":["ない限り","ないことには","ぬきでは","ようでは"],"answer":1,"explain":["【近义混同】「〜ない限り」重条件下的意志·许可，判断句惯用「ないことには」。","正解。「〜ないことには」接ない形，与「分からない」的判断不可能呼应。","【接续不合】「〜ぬきでは」接名词，接续不合。","【近义混同】「〜ようでは」表示「照…这样下去」的预判，与本句的条件不合。"]},
]},
{"id":"b1-91","typeKey":"bun1","title":"模拟91 義務・感情の第五弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"両親の健康を願って＿＿。","options":["いられない","おかない","やまない","すまない"],"answer":2,"explain":["【接续不合】「〜(ず)にはいられない」接ない形，接续不合。","【接续不合】「〜(ず)にはおかない」接ない形，接续不合。","正解。「〜てやまない」接祈愿类动词て形，表示「衷心…不已」。","【接续不合】「〜(ず)にはすまない」接ない形，接续不合。"]},
{"label":"近义辨析","q":"あの事故の映像を見ては、胸の痛みを＿＿。","options":["かまわず","余儀なくされる","ものともせず","禁じ得ない"],"answer":3,"explain":["【接续不合】「〜もかまわず」接名词も，「痛みをかまわず」不成立。","【近义混同】「〜を余儀なくされる」表示被迫做某行为，不接情感名词。","【近义混同】「〜をものともせず」表示「不把…放在眼里」，与本句相反。","正解。「〜を禁じ得ない」接情感名词＋を，表示「禁不住…」。"]},
{"label":"近义辨析","q":"御社のますますのご発展を祈り＿＿。","options":["やみません","おきません","いられません","すみません"],"answer":0,"explain":["正解。「〜てやまない」的否定形「やみません」，表示「衷心…不已」的郑重祝愿。","【接续不合】「〜(ず)にはおかない」接ない形，接续不合。","【接续不合】「〜(ず)にはいられない」接ない形，接续不合。","【接续不合】「〜(ず)にはすまない」接ない形，接续不合。"]},
{"label":"近义辨析","q":"彼の無責任な態度は、看過＿＿。","options":["しかねない","できない","がたい","えない"],"answer":1,"explain":["【近义混同】「〜かねない」表示「很可能（坏事）」，与本句的「不能忽视」不合。","正解。「看過できない」为惯用表达，表示「不能忽视」。","【近义混同】「〜がたい」表示「心理上难以」，与本句的义务否定不合。","【近义混同】「〜えない」表示「不可能」，与本句的「不应忽视」有别。"]},
{"label":"近义辨析","q":"彼は跳び上がら＿＿喜んだ。","options":["まじき","んばかりだ","んばかりに","ごとくに"],"answer":2,"explain":["【接续不合】「〜まじき」作连体修饰，与本句不合。","【时态肯否错位】「〜んばかりだ」为结句形，后接「喜んだ」则接续断裂。","正解。「〜んばかりに」接未然形，表示「几乎要…地」，作连用修饰。","【接续不合】「〜ごとく」表示比况，接续与本句的夸张情态不合。"]},
]},
{"id":"b1-92","typeKey":"bun1","title":"模拟92 接続詞の型（第四弾）","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"接续词","q":"売上は順調だ。＿＿、利益率は伸び悩んでいる。","options":["そのため","しかし","つまり","一方で"],"answer":3,"explain":["【文脉断裂】「そのため」表示因果，与本句不合。","【文脉断裂】「しかし」表示逆接，本句为并列对照而非转折。","【文脉断裂】「つまり」表示要约，与本句不合。","正解。「一方で」表示两事项的中性对照（销售额与利润率并观）。"]},
{"label":"接续词","q":"彼が辞めた理由を聞いた。＿＿、待遇への不満だった。","options":["ところによると","というのも","すると","それで"],"answer":0,"explain":["正解。「というのも〜からだ」表示「之所以…是因为」，引出前句的理由。","【文脉断裂】「すると」表示承接（于是），与本句的理由说明不合。","【文脉断裂】「それで」表示因果承接，与本句的理由结构不合。","【接续不合】「ところによると」非固定接续词形。"]},
{"label":"接续词","q":"本規約は全利用者に適用される。＿＿、法人契約の場合は別途定める。","options":["しかし","ただし","つまり","ところが"],"answer":1,"explain":["【近义混同】「しかし」表示全面转折，与本句的例外补充不合。","正解。「ただし」表示附加限制（但书）。","【文脉断裂】「つまり」表示要约，与本句不合。","【文脉断裂】「ところが」表示意外逆接，与本句的但书不合。"]},
{"label":"接续词","q":"明日は必ず来ると誓った。＿＿、現れなかった。","options":["つまり","すると","ところが","そのため"],"answer":2,"explain":["【文脉断裂】「つまり」表示要约，与本句不合。","【文脉断裂】「すると」表示承接，与本句的违背预期不合。","正解。「ところが」表示「可是（结果出乎意料）」。","【文脉断裂】「そのため」表示因果，与本句不合。"]},
{"label":"接续词","q":"値段は高い。＿＿、品質は保証されている。","options":["すると","そのため","つまり","それでも"],"answer":3,"explain":["【文脉断裂】「すると」表示承接，与本句不合。","【文脉断裂】「そのため」表示因果，与本句的逆接不合。","【文脉断裂】「つまり」表示要约，与本句不合。","正解。「それでも」表示「即便如此」，与「贵但保证品质」的让步契合。"]},
]},
{"id":"b1-93","typeKey":"bun1","title":"模拟93 文語・残存表現の第四弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"リーダー＿＿、部下の面倒を見るのが仕事だ。","options":["たるもの","ならでは","たりとも","ともあれ"],"answer":0,"explain":["正解。「〜たるもの」表示「身为…（就该…）」。","【接续不合】「〜ならでは」表示「唯有…才有的」，与本句不合。","【接续不合】「〜たりとも」与最小量名词搭配，接续不合。","【近义混同】「〜はともあれ」表示「姑且不论」，与本句的训诫不合。"]},
{"label":"近义辨析","q":"親＿＿、子の現在を気にしない人はいない。","options":["たりとも","たるもの","まじき","べく"],"answer":1,"explain":["【接续不合】「〜たりとも」与最小量名词搭配，接续不合。","正解。「〜たるもの」表示「身为…（就该…）」，与「身为父母自然挂念」契合。","【接续不合】「〜まじき」作连体修饰（あるまじき行為），与本句不合。","【接续不合】「〜べく」表示「为了…（文语目的）」，与本句不合。"]},
{"label":"近义辨析","q":"天才＿＿、落第はあるものだ。","options":["において","にしても","といえども","ならでは"],"answer":2,"explain":["【接续不合】「〜において」表示「在…（场所·领域）」，与本句的让步不合。","【近义混同】「〜にしても」表示一般让步，语气平淡，无法强调「连天才也」。","正解。「〜といえども」表示「即便是…（也）」，与极端例搭配构成让步强调。","【接续不合】「〜ならでは」表示「唯有…才有的」，与本句不合。"]},
{"label":"近义辨析","q":"校則違反は＿＿、退学の対象になる。","options":["のみ","すら","だに","もとより"],"answer":3,"explain":["【近义混同】「〜のみ」表示「唯有」，与本句不合。","【近义混同】「〜すら」表示「连…都」的极端例举，与本句的「本来就」不合。","【接续不合】「〜だに」多用于「夢にだに」等惯用，与本句不合。","正解。「〜もとより」表示「自不必说（本来就）」，与「校则违反自不必说连…也」的递进契合。"]},
{"label":"近义辨析","q":"お見舞い＿＿、近くまで来たので立ち寄らせていただきました。","options":["かたがた","がてら","ながら","が早いか"],"answer":0,"explain":["正解。「〜かたがた」接名词，表示「兼作…（顺便）」，郑重的拜访寒暄场景正是其典型用法。","【文体不合】「〜がてら」语感轻松日常，与本句郑重的拜访语体不合。","【接续不合】「〜ながら」接名词表示「保持…原状」，与本句的兼作目的不合。","【接续不合】「〜が早いか」表示「刚…立刻」，与本句不合。"]},
]},
{"id":"b1-94","typeKey":"bun1","title":"模拟94 複合助詞の第六弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"幾多の訴訟＿＿、ついに特許が認められた。","options":["をもって","を経て","をはじめ","をめぐって"],"answer":1,"explain":["【近义混同】「〜をもって」表示「以…（手段·时限）」，与本句的经过不合。","正解。「〜を経て」表示「经过…（到达终点）」。","【接续不合】「〜をはじめ」表示「以…为首（列举）」，与本句不合。","【接续不合】「〜をめぐって」表示「围绕…」，与本句不合。"]},
{"label":"近义辨析","q":"先輩の助言＿＿、研究の方向性が定まった。","options":["に沿って","をこめて","のもとで","をもって"],"answer":2,"explain":["【近义混同】「〜に沿って」表示「遵循…（方针）」，与本句不合。","【近义混同】「〜をこめて」表示「满怀…（情感）」，与本句不合。","正解。「〜のもとで」表示「在…之下」。","【近义混同】「〜をもって」表示「以…（手段·时限）」，与本句不合。"]},
{"label":"近义辨析","q":"彼の粘り強さと運＿＿、大舞台での優勝が実現した。","options":["にかけて","とともに","において","とが相まって"],"answer":3,"explain":["【近义混同】「〜にかけて」表示「覆盖（范围）」，与本句不合。","【近义混同】「〜とともに」表示「与…同时·随着」，与本句的相乘效果不合。","【接续不合】「〜において」表示「在…（场所·领域）」，与本句不合。","正解。「〜と（が）相まって」表示「与…相辅相成（效果加剧）」。"]},
{"label":"近义辨析","q":"定年した課長＿＿、若いメンバーがチームを率いることになった。","options":["にかわって","にとって","に応じて","に比べて"],"answer":0,"explain":["正解。「〜にかわって」表示「代替…（接任）」。","【近义混同】「〜にとって」表示「对…而言」，与本句不合。","【近义混同】「〜に応じて」表示「根据…相应变化」，与本句不合。","【近义混同】「〜に比べて」表示「与…相比」，与本句不合。"]},
{"label":"近义辨析","q":"先例＿＿、新規の申請は受け付けない。","options":["に沿い","に則り","に基づき","に鑑み"],"answer":1,"explain":["【近义混同】「〜に沿い」表示「遵循…（方针·指示）」，与先例的沿袭义有别。","正解。「〜に則り」表示「依照（惯例·先例）」，「先例に則り」为固定搭配。","【近义混同】「〜に基づき」表示「基于…（事实·数据）」，与先例不同。","【接续不合】「〜に鑑み」表示「鉴于…（缘由）」，与本句的依照不合。"]},
]},
{"id":"b1-95","typeKey":"bun1","title":"模拟95 敬語・待遇の型④","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"敬語","q":"校長はただいま、応接室で来客と面会＿＿。","options":["されております","させております","いたしております","くださっております"],"answer":0,"explain":["正解。「〜される」是「される」的尊敬语，「されております」表示对方正在会面。","【敬語误用】「〜させる」是使役，「面会させております」与「校长正在会面」不合。","【敬語误用】「〜いたす」是谦让语（我方），方向相反。","【敬語误用】「〜てくださる」表示「对方为我做」，此处无授受义。"]},
{"label":"敬語","q":"本日の会は、三時に始まりますので、それまでにご集合＿＿。","options":["さしあげます","ください","いたします","なさいます"],"answer":1,"explain":["【敬語误用】「〜さしあげる」表示「我方为对方做」，方向相反。","正解。「ご〜ください」表示「请（对方）做…」的郑重请求。","【敬語误用】「〜いたす」是谦让语（我方做），方向相反。","【敬語误用】「〜なさる」是尊敬语的陈述形，不用于请求形。"]},
{"label":"敬語","q":"部長は休日にもかかわらず、資料に目を通して＿＿。","options":["いただきました","さしあげました","くださいました","まいりました"],"answer":2,"explain":["【敬語误用】「〜ていただく」须我方主语，「部長が」不合。","【敬語误用】「〜てさしあげる」表示「我方为对方做」，方向相反。","正解。「〜てくださる」表示「对方为我（方）做…」，与「部长为我过目」契合。","【敬語误用】「まいる」是「行く·来る」的谦让语，与「目を通す」不合。"]},
{"label":"敬語","q":"私どもの案内不足でご迷惑をおかけし、深く＿＿。","options":["お詫びさしあがります","お詫びなさいます","お詫びくださいます","お詫び申し上げます"],"answer":3,"explain":["【接续不合】「さしあがる」非固定敬语形式。","【敬語误用】「〜なさる」是尊敬语（对方做），方向相反。","【敬語误用】「〜てくださる」表示「对方为我做」，方向相反。","正解。「お〜申し上げる」是谦让语大形式，「お詫び申し上げます」为致歉的固定表达。"]},
{"label":"敬語","q":"係の者が出張中のため、私が代わりに対応＿＿。","options":["いたします","なさいます","くださいます","さしあげます"],"answer":0,"explain":["正解。「〜いたす」是「する」的谦让语，用于己方郑重行为。","【敬語误用】「〜なさる」是尊敬语（对方做），方向相反。","【敬語误用】「〜てくださる」表示「对方为我做」，方向相反。","【敬語误用】「〜さしあげる」表示「我方施惠」，与应对语境不合。"]},
]},
{"id":"b1-96","typeKey":"bun1","title":"模拟96 敬語・待遇の型⑤","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"敬語","q":"忘年会の幹事を＿＿。よろしくお願いいたします。","options":["して差しあげます","させていただきます","してくださいます","なさっております"],"answer":1,"explain":["【敬語误用】「〜てさしあげる」表示「我方施惠」，用于担当场合显得傲慢。","正解。「〜(さ)せていただく」表示「承蒙允许我做…」，就任·担当场合的郑重自谦。","【敬語误用】「〜てくださる」表示「对方为我做」，方向相反。","【敬語误用】「〜なさる」是尊敬语（对方做），方向相反。"]},
{"label":"敬語","q":"事務所の鍵をお借りして＿＿。明日必ずお返しします。","options":["いいでしょうか","よろしいでございましょうか","よろしいでしょうか","かまわないでしょうか"],"answer":2,"explain":["【文体不合】「〜ていいでしょうか」口语体，与本句的郑重不合。","【文体不合】「〜でございましょうか」叠床架屋，不自然的敬语。","正解。「〜てよろしいでしょうか」是「てもいいか」的郑重许可询问。","【接续不合】「〜てかまわないでしょうか」形与惯用不合（「かまいませんでしょうか」）。"]},
{"label":"敬語","q":"お手数ですが、ご署名のうえ、下の欄にご記入＿＿。","options":["をお願いいたします","をなさいます","をさしあげます","をいただきますようお願いいたします"],"answer":3,"explain":["【敬語误用】「ご記入をお願いいたします」缺授受方向标记，惯用为「ご記入いただきますよう」。","【敬語误用】「〜なさる」是尊敬语陈述，不用于请求形。","【敬語误用】「〜さしあげる」表示「我方施惠」，方向相反。","正解。「〜ていただきますようお願いいたします」表示「恳请对方为我做」，依頼文书的固定表达。"]},
{"label":"敬語","q":"その節は大変＿＿。心より御礼申し上げます。","options":["お世話になりました","お世話差し上げました","ご世話いただきました","お世話なさいました"],"answer":0,"explain":["正解。「お世話になる」是惯用感恩表达，过去形「お世話になりました」为书信开头定番。","【敬語误用】「〜差し上げる」表示「我方施惠」，与感恩方向相反。","【敬語误用】「ご〜いただく」的授受方向与「世話になる」的惯用形不合。","【敬語误用】「〜なさる」是尊敬语，与感恩语境不合。"]},
{"label":"敬語","q":"この件につきましては、＿＿覚えはございません。","options":["承諾した","承知した","承認した","存じ上げた"],"answer":1,"explain":["【近义混同】「承諾する」表示「答应（承诺）」，与本句的「知道」不合。","正解。「承知する」表示「知道·了解」，「承知した覚えはございません」表示「没有印象接受过」。","【近义混同】「承認する」表示「承认·认可」，与本句不合。","【敬語误用】「存じ上げる」用于对人的敬意，与「覚え」的搭配不合。"]},
]},
{"id":"b1-97","typeKey":"bun1","title":"模拟97 逆接・让步の第八弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"接续制约","q":"手続きは終えた＿＿、反映には数日かかる。","options":["ながらも","つつも","ものの","がてら"],"answer":2,"explain":["【接续不合】「〜ながらも」接ます形·名词，接た形不成立。","【接续不合】「〜つつも」接ます形，接た形不成立。","正解。「〜ものの」接た形，表示「虽然…但是」。","【接续不合】「〜がてら」接ます形表示「顺便」，与本句的逆接不合。"]},
{"label":"接续制约","q":"古い＿＿、音質の良いスピーカーだ。","options":["わりには","ものの","つつも","ながらも"],"answer":3,"explain":["【接续不合】「〜わりには」须名词の，接续不合。","【接续不合】「〜ものの」须た形·である，接续不合。","【接续不合】「〜つつも」接ます形，接续不合。","正解。「〜ながらも」接な形容词词干，表示「虽然…但是」。"]},
{"label":"近义辨析","q":"必要なのは努力だ。＿＿、やり方を間違えては徒労に終わる。","options":["とはいえ","といっても","というものの","とは"],"answer":0,"explain":["正解。「〜とはいえ」承接前句做部分让步的书面表达。","【近义混同】「〜といっても」对同句内容打折扣的口语表达，与本句不合。","【接续不合】「〜というものの」非固定文型。","【近义混同】「〜とは」表示惊愕，与本句不合。"]},
{"label":"近义辨析","q":"誠実な＿＿、どこか信じがたい面がある。","options":["わりには","くせに","にしては","ものの"],"answer":1,"explain":["【近义混同】「〜わりには」表示中性评价，无谴责。","正解。「〜くせに」接な形容词词干＋な，表示「明明…却（指责）」。","【近义混同】「〜にしては」表示客观评价，无谴责。","【接续不合】「〜ものの」须た形·である，接续不合。"]},
{"label":"接续制约","q":"本人はやる気満々＿＿、成果がなかなか出ない。","options":["にしては","のくせに","のわりには","ものの"],"answer":2,"explain":["【接续不合】「〜にしては」直接接名词，「満々にしては」不自然。","【近义混同】「〜くせに」接名词の亦可（やる気満々のくせに），但后句「成果が出ない」为客观描述非指责，惯用「わりには」。","正解。「〜わりには」接名词の，表示「与…程度相比并不相称」。","【接续不合】「〜ものの」须た形·である，接续不合。"]},
]},
{"id":"b1-98","typeKey":"bun1","title":"模拟98 対比・程度の第四弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"兄の慎重さ＿＿、弟は大胆だ。","options":["に比べて","に反して","に対して","にひきかえ"],"answer":3,"explain":["【近义混同】「〜に比べて」表示中性比较，不承载落差感。","【接续不合】「〜に反して」接予想·期待·ルール，接续不合。","【接续制约】「〜に対して」表对照须「の＋に対して」，接续不合。","正解。「〜にひきかえ」表示「与…正相反（落差鲜明）」。"]},
{"label":"近义辨析","q":"部長＿＿、誰もが意見を言いやすい雰囲気だ。","options":["ともなれば","とあれば","としたら","ときたら"],"answer":0,"explain":["正解。「〜ともなれば」表示「一到…（程度自然伴随）」。","【近义混同】「〜とあれば」表示「如果是…（就愿意）」，与本句不合。","【近义混同】「〜としたら」表示假定，与本句的必然不合。","【近义混同】「〜ときたら」表示抱怨话题，与本句的中性描述不合。"]},
{"label":"近义辨析","q":"知ってい＿＿、教えてくれないなんて。","options":["つつ","ながら","ものの","がてら"],"answer":1,"explain":["【接续制约】「〜つつ」接ます形亦可（知りつつ），但「知ってい＋つつ」的形态不合（须「知りつつ」）。","正解。「〜ながら」接ます形，表示「明知…却（逆接）」，「知っていながら」为惯用表达。","【接续不合】「〜ものの」须た形·である，接续不合。","【接续不合】「〜がてら」接ます形表示「顺便」，与本句不合。"]},
{"label":"近义辨析","q":"三十歳＿＿、子供っぽい言動が目立つ。","options":["わりには","にしても","にしては","に限って"],"answer":2,"explain":["【接续不合】「〜わりには」须名词の，接续不合。","【近义混同】「〜にしても」表示「即使…也」的让步，与本句的评价不合。","正解。「〜にしては」接年龄·时点，表示「按其身份却」。","【近义混同】「〜に限って」表示「唯独…偏偏」，与本句不合。"]},
{"label":"近义辨析","q":"この車は燃費がいい＿＿、維持費がかかる。","options":["ものの","一方だ","に対して","反面"],"answer":3,"explain":["【接续制约】「〜ものの」须た形·である，接辞书形不成立。","【接续制约】「〜一方だ」接辞书形表示单方向变化，与本句的两面性不合。","【接续不合】「〜に対して」表对照须「の＋に対して」，接续不合。","正解。「〜反面」表示同一事物的两面（省油与维护费同属一车）。"]},
]},
{"id":"b1-99","typeKey":"bun1","title":"模拟99 原因・理由の第六弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"この川は水源が寺院の裏山＿＿、「寺川」と呼ばれる。","options":["であることから","だけあって","せいで","あまり"],"answer":0,"explain":["正解。「〜ことから」表示客观缘由，是「由缘由命名」的典型用法。","【近义混同】「〜だけあって」表示名实相符，与本句的命名依据不合。","【近义混同】「〜せいで」表示归咎负面原因，与本句不合。","【接续不合】「〜のあまり」前接感情名词，接续不合。"]},
{"label":"近义辨析","q":"さすが経験者＿＿、対応が落ち着いている。","options":["ばかりに","だけあって","せいで","あまり"],"answer":1,"explain":["【近义混同】「〜ばかりに」表示负面归因，与本句相反。","正解。「〜だけあって」表示「不愧是…（名实相符）」。","【近义混同】「〜せいで」表示归咎，与本句相反。","【接续不合】「〜のあまり」前接感情名词，接续不合。"]},
{"label":"近义辨析","q":"塩分の取りすぎ＿＿、むくみがひどい。","options":["だけあって","のおかげで","のせいで","ことから"],"answer":2,"explain":["【近义混同】「〜だけあって」表示名实相符，与本句不合。","【近义混同】「〜おかげで」表示得益于，方向相反。","正解。「〜せいで」表示「都怪…（归咎负面原因）」。","【近义混同】「〜ことから」表示客观缘由，与本句的归咎不合。"]},
{"label":"近义辨析","q":"少し手続きが遅れただけ＿＿、締め切りを過ぎてしまった。","options":["ことから","だけあって","おかげで","ばかりに"],"answer":3,"explain":["【近义混同】「〜ことから」表示客观缘由，与本句不合。","【近义混同】「〜だけあって」表示名实相符，与本句相反。","【近义混同】「〜おかげで」表示得益于，方向相反。","正解。「〜ばかりに」接た形，表示「只因…（引发负面结果）」。"]},
{"label":"近义辨析","q":"合格の喜び＿＿、声を上げて泣いた。","options":["のあまり","ばかりに","だけあって","ことから"],"answer":0,"explain":["正解。「〜のあまり」前接感情·状态名词，表示「因过分…而」。","【接续不合】「〜ばかりに」接た形·な形，接续不合。","【近义混同】「〜だけあって」表示名实相符，与本句不合。","【接续不合】「〜ことから」接句子的普通形，接续不合。"]},
]},
{"id":"b1-100","typeKey":"bun1","title":"模拟100 原因・理由の第七弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"練習を重ねた＿＿、本番では実力を出せた。","options":["だけあって","だけに","ばかりに","あまり"],"answer":1,"explain":["【近义混同】「〜だけあって」表示名实相符的称赞，与本句的相乘不合。","正解。「〜だけに」表示「正因为…所以更加」，与「苦练换来发挥」的相乘契合。","【近义混同】「〜ばかりに」表示负面归因，与本句相反。","【接续不合】「〜のあまり」前接感情名词，接续不合。"]},
{"label":"近义辨析","q":"猛暑＿＿、ビールの売上が伸びている。","options":["ことだから","とあれば","とあって","ときたら"],"answer":2,"explain":["【接续不合】「〜ことだから」前接人名词の，与本句不合。","【近义混同】「〜とあれば」表示「如果是…（就愿意）」，接意愿，与本句不合。","正解。「〜とあって」表示「因为处于…特殊状况」。","【近义混同】「〜ときたら」表示抱怨话题，与本句不合。"]},
{"label":"近义辨析","q":"電車が止まった＿＿、会議に間に合わなかったのです。","options":["だけあって","とあって","ばかりに","ものですから"],"answer":3,"explain":["【近义混同】「〜だけあって」表示名实相符，与本句无关。","【近义混同】「〜とあって」客观描述特殊状况，不用于个人辩解。","【文体不合】「〜ばかりに」为书面强调归因，不能用于礼貌辩解。","正解。「〜ものですから」表示「因为…（辩解语气）」，与迟到说明场合契合。"]},
{"label":"近义辨析","q":"文化の違い＿＿、誤解が生じることもある。","options":["ゆえに","ばかりに","せいで","あまり"],"answer":0,"explain":["正解。「〜ゆえに」接名词，表示「因…（文语）」，用于客观陈述。","【接续不合】「〜ばかりに」接た形·な形，接续不合。","【近义混同】「〜せいで」表示归咎于人的责任，与结构性原因不合。","【接续不合】「〜のあまり」前接感情名词，接续不合。"]},
{"label":"近义辨析","q":"週末ということも＿＿、行楽地はどこも混んでいた。","options":["とあって","あって","ばかりに","ことから"],"answer":1,"explain":["【接续不合】「〜とあって」与「ということもあって」的既定搭配不可互换。","正解。「〜もあって」表示「也因为…（原因之一）」，「ということもあって」为惯用呼应。","【近义混同】「〜ばかりに」表示负面归因，与本句不合。","【近义混同】「〜ことから」表示命名·依据的客观缘由，与本句不合。"]},
]},
{"id":"b1-101","typeKey":"bun1","title":"模拟101 契約・時点の第七弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"接续制约","q":"非常ベルが鳴った＿＿、全員が避難を始めた。","options":["なり","や否や","とたん","そばから"],"answer":2,"explain":["【接续不合】「〜なり」须辞书形（鳴るなり）。","【接续不合】「〜や否や」须辞书形（鳴るや否や）。","正解。「〜たとたん」接た形，表示「刚一…就（突发）」。","【近义混同】「〜そばから」表示徒劳反复，与本句的一次性突发不合。"]},
{"label":"近义辨析","q":"彼は家に帰る＿＿、ゲームを始めた。","options":["そばから","とたん","や否や","なり"],"answer":3,"explain":["【近义混同】「〜そばから」表示徒劳反复，与本句不合。","【接续不合】「〜たとたん」须た形，接续不合。","【近义混同】「〜や否や」重突发的客观事态，不带同一主体连续动作的连贯性。","正解。「〜なり」接辞书形，表示同一主体动作「刚一…就（紧接着）」。"]},
{"label":"接续制约","q":"店が開く＿＿、客がなだれ込んだ。","options":["や否や","とたん","なり","たびに"],"answer":0,"explain":["正解。「〜や否や」接辞书形，表示「一…立刻（书面）」。","【接续不合】「〜たとたん」须た形（開いたとたん）。","【接续不合】「〜なり」须辞书形亦可（開くなり）だが主语客が店と异なり「同一主体紧接」のなりは不自然。","【近义混同】「〜たびに」表示「每当…就」，与本句的一次性不合。"]},
{"label":"近义辨析","q":"教えた＿＿忘れる後輩に、先輩は手を焼いている。","options":["たびに","そばから","うちに","につけ"],"answer":1,"explain":["【近义混同】「〜たびに」表示中性的反复习惯，缺徒劳感。","正解。「〜そばから」表示「刚…就（被抵消）」的徒劳反复。","【近义混同】「〜うちに」表示「在…期间」，与本句不合。","【近义混同】「〜につけ」表示「每逢…就（情感涌起）」，与本句不合。"]},
{"label":"近义辨析","q":"交渉が難航＿＿、取引の見直しも検討され始めた。","options":["に際して","に限って","に至っては","に先立って"],"answer":2,"explain":["【近义混同】「〜に際して」表示「当…之际」，与本句的事态极端化不合。","【近义混同】「〜に限って」表示「唯独…偏偏」，与本句不合。","正解。「〜に至っては」表示「事态发展到…地步（极端例）」。","【近义混同】「〜に先立って」表示「在…之前」，与本句不合。"]},
]},
{"id":"b1-102","typeKey":"bun1","title":"模拟102 契約・時点の第八弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"さんざん迷った＿＿、何も買わずに帰った。","options":["に先立って","末に","うえで","あげく"],"answer":3,"explain":["【近义混同】「〜に先立って」表示「在…之前」，与本句相反。","【近义混同】「〜末に」表示中性的最终结果，与本句的消极色彩不合。","【近义混同】「〜うえで」表示「在…之后」，与本句的收场义不合。","正解。「〜あげく」接た形，表示「…的结果（消极收场）」，与「什么都没买」契合。"]},
{"label":"近义辨析","q":"話し合いを重ねた＿＿、両校の交流が実現した。","options":["末に","あげく","たびに","に至るまで"],"answer":0,"explain":["正解。「〜末(に)」接た形，表示「经过…最终（中性）」，与「交流实现」契合。","【近义混同】「〜あげく」带消极色彩，与积极结果不合。","【近义混同】「〜たびに」表示「每当…就」，与本句不合。","【近义混同】「〜に至るまで」表示范围极限，与本句不合。"]},
{"label":"近义辨析","q":"関係者と協議した＿＿、方針を固めたい。","options":["あげく","うえで","からには","ばかりに"],"answer":1,"explain":["【近义混同】「〜あげく」表示消极收场，与本句的中性先后不合。","正解。「〜たうえで」表示「在…之后（再进行下一步）」。","【接续制约】「〜からには」接辞书形，接续不合且表义务。","【近义混同】「〜ばかりに」表示负面归因，与本句不合。"]},
{"label":"近义辨析","q":"新しい仕事＿＿、生活リズムを整えたい。","options":["にわたって","における","にあたって","にとって"],"answer":2,"explain":["【近义混同】「〜にわたって」表示范围持续，与本句的时点不合。","【接续不合】「〜における」是连体形，接续不合。","正解。「〜にあたって」表示「值此（重要行动开始）之际」。","【近义混同】「〜にとって」表示「对…而言」，与本句不合。"]},
{"label":"近义辨析","q":"重要な式典＿＿、改まった服装でお越し下さい。","options":["に限って","につれて","に応じて","に際して"],"answer":3,"explain":["【近义混同】「〜に限って」表示「唯独…偏偏」，与本句不合。","【近义混同】「〜につれて」表示「随着…」，与本句不合。","【近义混同】「〜に応じて」表示「根据…相应变化」，与本句不合。","正解。「〜に際して」表示「当…之际（书面）」。"]},
]},
{"id":"b1-103","typeKey":"bun1","title":"模拟103 強調・断定の第六弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"文末表现","q":"休日にまで仕事の電話がかかってくる＿＿。","options":["とは","とはいえ","というものだ","にほかならない"],"answer":0,"explain":["正解。「〜とは」接句子，表示「竟然…（惊愕，句尾省略）」。","【近义混同】「〜とはいえ」表示「虽说如此」的部分让步，与本句的惊愕不合。","【近义混同】「〜というものだ」表示「这才真是」的断言，与本句不合。","【接续不合】「〜にほかならない」接名词，接句子不成立。"]},
{"label":"近义辨析","q":"指紋の一致から、犯人は社内の者＿＿。","options":["に限る","に相違ない","に越したことはない","にはあたらない"],"answer":1,"explain":["【近义混同】「〜に限る」表示「最好（莫过于）」的建议，与本句的推断不合。","正解。「〜に相違ない」接普通形，表示「必是…」的书面断定。","【近义混同】「〜に越したことはない」表示「没有比…更好」，与本句不合。","【近义混同】「〜にはあたらない」表示「不值得（惊讶）」，与本句不合。"]},
{"label":"文末表现","q":"約束を守らない友人と、付き合いを続ける必要＿＿。","options":["というところだ","というものだ","というものはない","といったらない"],"answer":2,"explain":["【近义混同】「〜というところだ」表示「大概也就…的程度」，与本句相反。","【近义混同】「〜というものだ」表示「这才真是」的断言，方向相反。","正解。「〜というものではない」表示「并非…就行（部分否定）」。","【近义混同】「〜といったらない」表示「难以形容」的感叹，与本句不合。"]},
{"label":"文末表现","q":"彼の回復力は、若者のそれ＿＿。","options":["ものだ","にすぎない","までもない","にほかならない"],"answer":3,"explain":["【近义混同】「〜ものだ」表示感慨·本性·忠告，与本句的断言不合。","【近义混同】「〜にすぎない」表示「不过是」的贬低，与本句相反。","【近义混同】「〜までもない」表示「没必要」，与本句不合。","正解。「〜にほかならない」表示「正是…（强断定抬升）」。"]},
{"label":"文末表现","q":"僕の意見は一つの見方＿＿、参考にすぎない。","options":["にすぎない","にほかならない","までもない","ものだ"],"answer":0,"explain":["正解。「〜にすぎない」表示「不过是…」的贬降。","【近义混同】「〜にほかならない」表示「正是…」的抬升，与本句相反。","【近义混同】「〜までもない」表示「没必要」，与本句不合。","【近义混同】「〜ものだ」表示感慨·本性·忠告，与本句不合。"]},
]},
{"id":"b1-104","typeKey":"bun1","title":"模拟104 文末・評価の第六弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"文末表现","q":"あんな安い材料で、まともな家具が作れる＿＿。","options":["ものだ","ものか","までもない","というものだ"],"answer":1,"explain":["【近义混同】「〜ものだ」表示感慨·本性·忠告，与本句的反问相反。","正解。「〜ものか」接可能形，表示「怎么可能（强烈反问）」。","【近义混同】「〜までもない」表示「没必要」，与本句不合。","【近义混同】「〜というものだ」表示「这才真是」的断言，与本句相反。"]},
{"label":"文末表现","q":"住所は案内の地図を見れば分かる。電話で聞く＿＿。","options":["どころではない","まい","までもない","ものではない"],"answer":2,"explain":["【近义混同】「〜どころではない」表示「哪里谈得上」，与本句不合。","【近义混同】「〜まい」表示否定意志，与本句的「没必要」不合。","正解。「〜までもない」接辞书形，表示「没必要…」。","【近义混同】「〜ものではない」表示「不该…」的说教，与本句不合。"]},
{"label":"文末表现","q":"彼はテニス＿＿、歩くのさえ億劫がっている。","options":["にすぎない","どころではない","というものだ","どころか"],"answer":3,"explain":["【近义混同】「〜にすぎない」表示「不过是」，与本句不合。","【近义混同】「〜どころではない」表示「哪里谈得上（无暇）」，与本句的递进不合。","【近义混同】「〜というものだ」表示「这才真是」的断言，与本句不合。","正解。「〜どころか」表示「非但…（更甚）」。"]},
{"label":"文末表现","q":"早く謝ればいい＿＿、意地を張り続けている。","options":["ものを","ものだ","ものか","ものがある"],"answer":0,"explain":["正解。「〜ものを」表示「要是…就好了（责难未做）」。","【近义混同】「〜ものだ」表示感慨·本性·忠告，与本句的责难不合。","【近义混同】「〜ものか」为反问，与本句不合。","【近义混同】「〜ものがある」表示「确有…之处」，与本句不合。"]},
{"label":"文末表现","q":"上達したいなら、毎日音読する＿＿。","options":["ものだ","ことだ","わけだ","はずだ"],"answer":1,"explain":["【近义混同】「〜ものだ」表示普遍道理，不针对个人的当下处境。","正解。「〜ことだ」表示「最好…（对个人的具体建议）」。","【近义混同】「〜わけだ」表示「难怪（归结）」，与本句的建议不合。","【近义混同】「〜はずだ」表示「理应（推断）」，与本句的建议不合。"]},
]},
{"id":"b1-105","typeKey":"bun1","title":"模拟105 義務・感情の第六弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"台風が接近しているので、工事の予定は中止せざるを＿＿。","options":["いられない","おかない","得ない","すまない"],"answer":2,"explain":["【近义混同】「〜ずにはいられない」表示感情冲动，与本句的外部强制不合。","【近义混同】「〜ずにはおかない」接ない形（中止せずには），与「中止せざる」的形态有别，且义为「必然引起」。","正解。「〜ざるを得ない」（する→せざる）表示「迫于外部状况不得不」。","【近义混同】「〜ずにはすまない」表示社会义务，与本句的外部状况不合。"]},
{"label":"近义辨析","q":"あの発言は、波紋を呼ば＿＿。","options":["ざるを得ない","ずにはすまない","ずにはいられない","ずにはおかない"],"answer":3,"explain":["【近义混同】「〜ざるを得ない」表示「迫于外部不得不」，与本句不合。","【近义混同】「〜ずにはすまない」表示「不…就过意不去（义务主体）」，与本句不合。","【近义混同】「〜ずにはいられない」表示「禁不住（感情冲动）」，与本句不合。","正解。「〜ずにはおかない」表示「必然会引起…（主语可为事态）」。"]},
{"label":"近义辨析","q":"その映像を見ては、涙を＿＿。","options":["禁じ得ない","余儀なくされる","ものともせず","かまわず"],"answer":0,"explain":["正解。「〜を禁じ得ない」接情感名词＋を，表示「禁不住…」。","【近义混同】「〜を余儀なくされる」表示被迫做某行为，不接情感名词。","【近义混同】「〜をものともせず」表示「不把…放在眼里」，与本句相反。","【接续不合】「〜もかまわず」接名词も，「涙をかまわず」不成立。"]},
{"label":"近义辨析","q":"合格の知らせに、喜び＿＿です。","options":["に堪えない","の極み","きわまりない","てやまない"],"answer":1,"explain":["【接续制约】「〜に堪えない」多接消极情感，与「喜び」不合。","正解。「〜の極み」接情感名词，表示「…之极」，「喜びの極みです」为惯用表达。","【接续制约】「〜きわまりない」接な形容词词干表贬义，不接积极情感。","【接续不合】「〜てやまない」接动词て形，接续不合。"]},
{"label":"近义辨析","q":"被災地の一日も早い復興を祈って＿＿。","options":["いられません","おきません","やみません","すみません"],"answer":2,"explain":["【接续不合】「〜(ず)にはいられない」接ない形，接续不合。","【接续不合】「〜(ず)にはおかない」接ない形，接续不合。","正解。「〜てやまない」的否定形「やみません」，表示「衷心…不已」的郑重祝愿。","【接续不合】「〜(ず)にはすまない」接ない形，接续不合。"]},
]},
{"id":"b1-106","typeKey":"bun1","title":"模拟106 義務・感情の第七弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"突然の雪＿＿、帰宅ラッシュに大きな混乱が生じた。","options":["だけあって","のおかげで","ばかりに","のため"],"answer":3,"explain":["【近义混同】「〜だけあって」表示名实相符，与本句不合。","【近义混同】「〜おかげで」表示得益于，方向相反。","【接续不合】「〜ばかりに」接た形·な形，接续不合。","正解。「〜のため」表示客观原因，中性的书面表达。"]},
{"label":"近义辨析","q":"この曲を聴くと、故郷を思い出さずには＿＿。","options":["いられない","おかない","すまない","ならない"],"answer":0,"explain":["正解。「〜ずにはいられない」表示「禁不住（感情自发）」。","【近义混同】「〜ずにはおかない」表示「必然引起」，与本句的冲动不合。","【近义混同】「〜ずにはすまない」表示「不…就过意不去（义务）」，与本句的冲动不合。","【接续不合】「〜ないわけにはいかない」接ない形，接续不合。"]},
{"label":"近义辨析","q":"掃除を怠った結果、カビが生えてしまい、壁を塗り直さずには＿＿。","options":["いられない","すまない","おかない","ならない"],"answer":1,"explain":["【近义混同】「〜ずにはいられない」表示感情冲动，与本句的义务不合。","正解。「〜ずにはすまない」表示「不…就过意不去／难免被追究（义务）」，与「不得不重涂」契合。","【近义混同】「〜ずにはおかない」表示「必然引起」，主语为事态，与本句的义务不合。","【接续不合】「〜ないわけにはいかない」接ない形，接续不合。"]},
{"label":"近义辨析","q":"文豪の直筆を前にして、その筆力に感動＿＿。","options":["をものともせず","を余儀なくされた","を禁じ得なかった","をかまわず"],"answer":2,"explain":["【近义混同】「〜をものともせず」表示「不把…放在眼里」，与本句相反。","【近义混同】「〜を余儀なくされる」表示被迫做某行为，不接情感名词。","正解。「〜を禁じ得ない」接情感名词＋を，表示「禁不住…」。","【接续不合】「〜もかまわず」接名词も，「感動をかまわず」不成立。"]},
{"label":"近义辨析","q":"彼の不作法な振る舞いは、見るに＿＿。","options":["限る","過ぎない","足らない","堪えない"],"answer":3,"explain":["【近义混同】「〜に限る」表示「最好」，与本句相反。","【近义混同】「〜に過ぎない」表示「不过是」，与本句不合。","【近义混同】「〜に足らない」表示「不值得」，与本句的「不堪」有别。","正解。「見るに堪えない」表示「不堪入目」，为惯用表达。"]},
]},
{"id":"b1-107","typeKey":"bun1","title":"模拟107 変化・傾向の第五弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"少子化で、地方の学校は統廃合が進む＿＿。","options":["一方だ","ばかりだ","つつある","がちだ"],"answer":0,"explain":["正解。「〜一方だ」接辞书形，表示「不断地朝一个方向变化」。","【近义混同】「〜ばかりだ」重「越发（负面感叹）」，与本句的方向性趋势表述有别。","【近义混同】「〜つつある」表示「变化途中（渐进）」，与本句的总量趋势表述有别。","【接续制约】「〜がち」接ます形 stem，接辞书形不成立。"]},
{"label":"近义辨析","q":"町の活気は少しずつ取り戻され＿＿。","options":["一方だ","つつある","ばかりだ","かけている"],"answer":1,"explain":["【近义混同】「〜一方だ」表示单方向的加速变化，与本句的渐进感不合。","正解。「〜つつある」接ます形，表示「变化正在渐进进行」，与「少しずつ」呼应。","【近义混同】「〜ばかりだ」重负面感叹，与本句的中性过程不合。","【近义混同】「〜かけている」表示「开始…但未完成」，与本句的变化过程不合。"]},
{"label":"近义辨析","q":"放置すれば、個人情報の漏洩＿＿。","options":["に発展えない","に発展しかねる","に発展しかねない","に発展がたい"],"answer":2,"explain":["【接续不合】「〜えない」接ます形（発展えない✗　発展し得ない），接续不合。","【近义混同】「〜かねる」表示「难以（婉拒）」，方向相反。","正解。「〜かねない」接ます形，表示「很可能（酿成坏事）」。","【接续不合】「〜がたい」接ます形，「発展がたい」与本句的可能性不合。"]},
{"label":"文末表现","q":"予算の関係で、この要望には応じ＿＿。","options":["がたいです","かねません","えます","かねます"],"answer":3,"explain":["【近义混同】「〜がたい」表示书面评价，「応じかねます」为商务惯用形。","【近义混同】「〜かねない」表示「很可能（坏事）」，与本句的婉拒相反。","【近义混同】「〜える」表示「可能」，与本句相反。","正解。「〜かねる」表示「难以…（婉拒）」，「応じかねます」为商务场合的固定婉拒表达。"]},
{"label":"近义辨析","q":"彼が遅刻するのは、十分＿＿ことだ。","options":["ありうる","ありかねない","ありえない","ありがちな"],"answer":0,"explain":["正解。「〜うる」接ます形，表示「有可能（中性）」。","【近义混同】「〜かねない」限定负面结果，与本句的中性评价不合。","【近义混同】「〜えない」表示「不可能」，与本句相反。","【近义混同】「〜がちな」表示频度倾向，与本句的可能性不合。"]},
]},
{"id":"b1-108","typeKey":"bun1","title":"模拟108 様態・傾向の第六弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"彼女はうれしそうな、いや＿＿な顔で頷いた。","options":["うれしいそう","うれしげ","うれしっぽい","うれし気味"],"answer":1,"explain":["【接续不合】「〜そう」接形容词须去い（うれしそうな），「うれしいそうな」不成立。","正解。「〜げ」接形容词词干，表示「…的神情」，「うれしげな」为惯用表达。","【接续不合】「〜っぽい」接形容词词干表示倾向，「うれしっぽいな顔」不自然。","【接续不合】「〜気味」表示状态，「うれし気味な顔」不自然。"]},
{"label":"近义辨析","q":"彼は物忘れ＿＿で、同じ話を何度もする。","options":["気味","げ","っぽい","まみれ"],"answer":2,"explain":["【接续不合】「〜気味」表示状态，「物忘れ気味で」不自然。","【接续不合】「〜げ」接形容词词干·ます形，「物忘れげ」不自然。","正解。「〜っぽい」接ます形，表示「容易…」，「物忘れっぽい」为惯用表达。","【接续不合】「〜まみれ」表示「沾满」，接续与语义均不合。"]},
{"label":"近义辨析","q":"彼は最近、塩分を控え＿＿にしている。","options":["っぽい","がち","げ","気味"],"answer":3,"explain":["【接续不合】「〜っぽい」表示性格倾向，与本句的当下状态有别。","【近义混同】「〜がち」表示频度倾向，与本句的当下状态不合。","【接续不合】「〜げ」表示神情，接续与本句不合。","正解。「〜気味」接ます形 stem，表示「略带…的当下状态」。"]},
{"label":"近义辨析","q":"彼は忙しくて、人付き合いを疎か＿＿だ。","options":["がち","気味","げ","っぽい"],"answer":0,"explain":["正解。「〜がち」接ます形 stem，表示「经常处于某状态」。","【近义混同】「〜気味」表示当下状态，与本句的频度倾向不合。","【接续不合】「〜げ」表示神情，接续与本句不合。","【接续不合】「〜っぽい」表示性格倾向，与本句的频度不合。"]},
{"label":"近义辨析","q":"打ち合わせの議事録が間違い＿＿で、読み直す手間がかかった。","options":["ずくめ","だらけ","まみれ","っぽい"],"answer":1,"explain":["【近义混同】「〜ずくめ」表示「清一色系列」的接连感，与本句的「充斥」不合。","正解。「〜だらけ」表示「满是…（缺点）」，「間違いだらけ」为固定搭配。","【接续不合】「〜まみれ」限液体·粉末附着，不能接抽象名词。","【接续不合】「〜っぽい」表示气质倾向，与本句的充斥义不合。"]},
]},
{"id":"b1-109","typeKey":"bun1","title":"模拟109 基準・対応の第六弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"臨床データ＿＿、この治療法の有効性が確認された。","options":["に応じて","に沿って","に基づいて","に限って"],"answer":2,"explain":["【近义混同】「〜に応じて」表示「根据…相应变化」，与本句不合。","【近义混同】「〜に沿って」表示「沿着…（规程·方针）」，与数据的依据义有别。","正解。「〜に基づいて」表示「基于…（事实·数据）」。","【近义混同】「〜に限って」表示「唯独…偏偏」，与本句不合。"]},
{"label":"近义辨析","q":"レシピ＿＿、生地をこねてください。","options":["に即して","に基づいて","に応じて","に沿って"],"answer":3,"explain":["【近义混同】「〜に即して」表示「紧扣现实」，与本句不合。","【近义混同】「〜に基づいて」重「依据事实·数据」，流程的沿袭用「に沿って」。","【近义混同】「〜に応じて」表示「根据…相应变化」，与本句不合。","正解。「〜に沿って」表示「沿着…（规程·流程进行）」。"]},
{"label":"近义辨析","q":"市民の声＿＿、新しい政策が生まれた。","options":["をもとに","をきっかけに","に応じて","をめぐって"],"answer":0,"explain":["正解。「〜をもとに」表示「以…为素材·参考」。","【近义混同】「〜をきっかけに」表示「以…为契机」，与本句的素材义不合。","【近义混同】「〜に応じて」表示「根据…相应变化」，与本句不合。","【接续不合】「〜をめぐって」表示「围绕…」，与本句不合。"]},
{"label":"近义辨析","q":"先行研究＿＿、仮説を立て直した。","options":["をきっかけに","を踏まえて","をはじめ","をめぐって"],"answer":1,"explain":["【近义混同】「〜をきっかけに」表示「以…为契机」，与本句的依据义不合。","正解。「〜を踏まえて」表示「立足于…（考虑·判断）」。","【接续不合】「〜をはじめ」表示「以…为首（列举）」，与本句不合。","【接续不合】「〜をめぐって」表示「围绕…」，与本句不合。"]},
{"label":"近义辨析","q":"客の注文＿＿、料理の量を変えられる。","options":["に伴って","につれて","に応じて","にしたがって"],"answer":2,"explain":["【近义混同】「〜に伴って」表示伴随发生，与本句的对应措施不合。","【近义混同】「〜につれて」表示自然联动，与本句的主动调整不合。","正解。「〜に応じて」表示「根据…相应调整（政策性）」。","【近义混同】「〜にしたがって」表示遵从，与本句不合。"]},
]},
{"id":"b1-110","typeKey":"bun1","title":"模拟110 基準・経由の第四弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"現地のボランティア＿＿、被災地の復旧が進んだ。","options":["にわたって","をはじめ","をめぐって","を通じて"],"answer":3,"explain":["【接续不合】「〜にわたって」表示范围持续，与本句不合。","【接续不合】「〜をはじめ」表示「以…为首（列举）」，与本句不合。","【接续不合】「〜をめぐって」表示「围绕…」，与本句不合。","正解。「〜を通じて」表示「经由…（中介）」。"]},
{"label":"近义辨析","q":"京都＿＿、各地で紅葉が見頃を迎えている。","options":["をはじめ","を中心に","をこめて","をもとに"],"answer":0,"explain":["正解。「〜をはじめ」表示「以…为首（列举代表，含全体）」。","【近义混同】「〜を中心に」表示「以…为核心」，与本句的列举不合。","【近义混同】「〜をこめて」表示「满怀…（情感）」，与本句不合。","【近义混同】「〜をもとに」表示「以…为素材」，与本句不合。"]},
{"label":"近义辨析","q":"新制度＿＿、意見が交わされた。","options":["を通じて","をめぐって","にわたって","をもとに"],"answer":1,"explain":["【近义混同】「〜を通じて」表示「经由…（中介）」，与本句不合。","正解。「〜をめぐって」表示「围绕…（展开讨论）」。","【接续不合】「〜にわたって」表示范围持续，不接话题名词。","【近义混同】「〜をもとに」表示「以…为素材」，与本句不合。"]},
{"label":"近义辨析","q":"梅雨は九州から東北＿＿、各地に大雨をもたらした。","options":["にとって","を通じて","にわたって","にかけて"],"answer":2,"explain":["【近义混同】「〜にとって」表示「对…而言」，与本句不合。","【近义混同】「〜を通じて」表示「经由…（中介）」，与本句的范围不合。","正解。「〜にわたって」接范围名词，表示「跨越…」。","【近义混同】「〜にかけて」表示「覆盖（范围）」，与本句的时间推移有别。"]},
{"label":"近义辨析","q":"高齢化＿＿、医療費の負担が増えている。","options":["に先立って","に応じて","に限り","に伴って"],"answer":3,"explain":["【近义混同】「〜に先立って」表示「在…之前」，与本句不合。","【近义混同】「〜に応じて」表示「根据…相应调整（政策性）」，与本句的自然联动不合。","【接续不合】「〜に限り」表示「仅限于…」，与本句不合。","正解。「〜に伴って」表示「伴随…（大规模·书面）」。"]},
]},
{"id":"b1-111","typeKey":"bun1","title":"模拟111 限定・範囲の第五弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"男女＿＿、この仕事に向いた人は採用したい。","options":["を問わず","に限らず","のみならず","に限って"],"answer":0,"explain":["正解。「〜を問わず」接「男女·昼夜」等对立范畴，表示「不限…」。","【接续制约】「〜に限らず」多接单个范畴的扩展，「男女」的对立范畴惯用「を問わず」。","【接续制约】「〜のみならず」亦通但「男女を問わず」为告示惯用。","【近义混同】「〜に限って」表示「唯独…偏偏」，与本句相反。"]},
{"label":"近义辨析","q":"この歌手の人気は若者＿＿、幅広い世代に及んでいる。","options":["を問わず","に限らず","のみならず","に限って"],"answer":1,"explain":["【接续制约】「〜を問わず」须接一对并列范畴，单个「若者」不成立。","正解。「〜に限らず」表示「不限于…（扩展到更大范围）」。","【接续制约】「〜のみならず」亦通但「に限らず～にも」的扩展更自然。","【近义混同】「〜に限って」表示「唯独…偏偏」，与本句相反。"]},
{"label":"近义辨析","q":"彼は漢字＿＿、読み書きの基礎から学び直している。","options":["のみならず","はおろか","はもとより","ばかりか"],"answer":2,"explain":["【近义混同】「〜のみならず」为中性递进，与本句「もとより～も」的呼应上更典型。","【近义混同】「〜はおろか」多接消极递进，与本句的正面展开不合。","正解。「〜はもとより」表示「…自不必说（中性·正面递进）」。","【接续制约】「〜ばかりか」多接消极递进，与本句不合。"]},
{"label":"近义辨析","q":"彼は文章＿＿、署名すらまともにできない。","options":["もさることながら","はもとより","のみならず","はおろか"],"answer":3,"explain":["【接续不合】「〜もさることながら」用于两点并置褒扬，与本句相反。","【近义混同】「〜はもとより」用于中性·正面递进，与本句的贬降不合。","【近义混同】「〜のみならず」为中性递进，不承载消极语感。","正解。「〜はおろか」表示「…自不必说，连…也（消极递进）」。"]},
{"label":"近义辨析","q":"彼の発言は国内＿＿、海外でも波紋を呼んだ。","options":["のみならず","はおろか","ならでは","をおいて"],"answer":0,"explain":["正解。「〜のみならず」表示「不仅…而且…」的书面递进。","【近义混同】「〜はおろか」多接消极递进，与本句的正面展开不合。","【接续不合】「〜ならでは」表示「唯有…才有的」，与本句不合。","【接续不合】「〜をおいて」接人名词＋否定，与本句不合。"]},
]},
{"id":"b1-112","typeKey":"bun1","title":"模拟112 複合助詞の第七弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"式典は東京ドーム＿＿催された。","options":["にとって","において","にかけて","にわたって"],"answer":1,"explain":["【近义混同】「〜にとって」表示「对…而言」，与本句不合。","正解。「〜において」表示「在…（场所·场合）」，书面体。","【近义混同】「〜にかけて」表示「覆盖（范围）」，与本句的场所不合。","【近义混同】「〜にわたって」表示范围持续，不接场所名词。"]},
{"label":"接续制约","q":"海外生活＿＿の苦労は、言葉の壁に尽きる。","options":["にとっての","において","における","にかけての"],"answer":2,"explain":["【接续不合】「〜にとっての」表示「对…而言的」，与本句不合。","【接续不合】「〜において」为连用形，「においての苦労」不成立。","正解。「〜における」是「において」的连体形，直接修饰名词。","【接续不合】「〜にかけての」表示「在…方面的」，与本句不合。"]},
{"label":"近义辨析","q":"ベテランの彼＿＿、初歩的なミスをした。","options":["のみ","だに","たりとも","すら"],"answer":3,"explain":["【近义混同】「〜のみ」表示「唯有」，与本句相反。","【接续不合】「〜だに」多用于「夢にだに思わぬ」等惯用，与本句不合。","【近义混同】「〜たりとも」与最小量名词搭配，与「ベテラン」不合。","正解。「〜すら」表示「连…都（书面极端例）」。"]},
{"label":"近义辨析","q":"一日＿＿休むことなく、練習を続けた。","options":["たりとも","すら","だに","のみ"],"answer":0,"explain":["正解。「〜たりとも」与最小量名词搭配，表示「哪怕一天也…」。","【近义混同】「〜すら」表示「连…都」的极端例举，「一日すら」亦通但最小量＋否定惯用「たりとも」。","【接续不合】「〜だに」多用于「夢にだに」等惯用，与本句不合。","【近义混同】「〜のみ」表示「唯有」，与本句不合。"]},
{"label":"近义辨析","q":"今学期＿＿、授業料が改定されます。","options":["を限りに","をもって","にわたって","をもとに"],"answer":1,"explain":["【近义混同】「〜を限りに」带诀别语气，中性时限惯用「をもって」。","正解。「〜をもって」表示「自…（时限）」，公告体中性表述。","【接续不合】「〜にわたって」表示范围持续，与时点不合。","【近义混同】「〜をもとに」表示「以…为素材」，与本句不合。"]},
]},
{"id":"b1-113","typeKey":"bun1","title":"模拟113 複合助詞の第八弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"信頼＿＿の長い付き合いだ。","options":["にかかわる","に基づく","あって","をめぐる"],"answer":2,"explain":["【近义混同】「〜にかかわる」表示「关系到…」，与本句相反。","【近义混同】「〜に基づく」表示「基于…（依据）」，与本句的存在依存不合。","正解。「〜あっての＋名词」表示「有…才有…」。","【接续不合】「〜をめぐる」修饰争论·对立的话题，与本句不合。"]},
{"label":"近义辨析","q":"年度末の混雑＿＿、手続きの早期完了をお願いする。","options":["に限り","に応じて","に則って","に鑑み"],"answer":3,"explain":["【接续不合】「〜に限り」表示「仅限于…」，与本句不合。","【近义混同】「〜に応じて」表示「根据…相应变化」，与本句的缘由不合。","【近义混同】「〜に則って」表示「依照（惯例·先例）」，与本句不合。","正解。「〜に鑑み」表示「鉴于…（公文语决策缘由）」。"]},
{"label":"近义辨析","q":"市役所＿＿、観光の案内所が開設された。","options":["を中心に","をはじめ","をきっかけに","を皮切りに"],"answer":0,"explain":["正解。「〜を中心に」表示「以…为中心（围绕其展开）」。","【近义混同】「〜をはじめ」表示「以…为首（列举代表）」，与本句的核心展开不合。","【近义混同】「〜をきっかけに」表示「以…为契机」，与本句不合。","【近义混同】「〜を皮切りに」表示「以…为开端（时间）」，与本句的空间核心不合。"]},
{"label":"近义辨析","q":"暗算＿＿、彼の右に出る者はいない。","options":["において","にかけては","にとって","に比べて"],"answer":1,"explain":["【近义混同】「〜において」表示「在…（场所·领域）」，不带评价。","正解。「〜にかけては」表示「在…方面（首屈一指）」，与「无人能出其右」的 evaluation 契合。","【近义混同】「〜にとって」表示「对…而言」，与本句不合。","【近义混同】「〜に比べて」表示「与…相比」的单纯比较，不承载评价。"]},
{"label":"近义辨析","q":"彼は人目＿＿、夜中に一人で練習を続けた。","options":["をものともせず","をよそに","を顧みず","にかかわらず"],"answer":2,"explain":["【近义混同】「〜をものともせず」表示「不把…放在眼里」的强者姿态，与本句的奋不顾身有别。","【近义混同】「〜をよそに」表示「无视（外界的反对·期待）」，与本句的无视目光有细微之别。","正解。「〜を顧みず」表示「不顾…（他人目光·自身安危）」，与「不顾人目」契合。","【近义混同】「〜にかかわらず」表示「不论…」，与本句不合。"]},
]},
{"id":"b1-114","typeKey":"bun1","title":"模拟114 条件・仮定の第六弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"呼应制约","q":"彼と話し＿＿、問題の解決はあり得ない。","options":["ぬきでは","ない限り","ようでは","ないことには"],"answer":3,"explain":["【接续不合】「〜ぬきでは」接名词，接续不合。","【近义混同】「〜ない限り」重条件下的意志·许可，判断句惯用「ないことには」。","【近义混同】「〜ようでは」表示「照…这样下去」的预判，与本句的条件不合。","正解。「〜ないことには」接ない形，与「あり得ない」的判断不可能呼应。"]},
{"label":"呼应制约","q":"本人が同意しない＿＿、手続きは進められない。","options":["ない限り","ないことには","ようでは","ないまでも"],"answer":0,"explain":["正解。「〜ない限り」表示「只要不…就（不）」，与「不同意就无法推进」的程序许可契合。","【接续不合】「〜ないことには」与「同意しない」重叠成双重否定，「同意しない＋ないことには」不成立。","【近义混同】「〜ようでは」表示「照…这样下去」的预判，与本句的条件不合。","【接续制约】「〜ないまでも」接续与本句不合。"]},
{"label":"呼应制约","q":"この道＿＿通れば、十分钟は短縮できる。","options":["でも","さえ","こそ","すら"],"answer":1,"explain":["【近义混同】「〜でも」表示「比如…之类（轻列举）」，缺最小条件的强调。","正解。「〜さえ〜ば」表示「只要…就（最小充分条件）」。","【呼应冲突】「〜こそ」表示强调，与ば形条件呼应不合。","【呼应冲突】「〜すら」表示「连…都」的极端例，与ば形条件不合。"]},
{"label":"近义辨析","q":"思い込み＿＿、大失敗しかねない。","options":["しだい","しない限り","しようものなら","しかねる"],"answer":2,"explain":["【近义混同】「〜次第」接ます形表示「一…立刻」，与本句的警告不合。","【近义混同】「〜ない限り」表示「只要不…就（不）」，与本句不合。","正解。「〜(よ)うものなら」接意志形，表示「一旦…的话（后果严重）」。","【接续不合】「〜かねる」接ます形表示「难以（婉拒）」，与本句不合。"]},
{"label":"近义辨析","q":"部長＿＿、責任を取るべきだ。","options":["どころか","とはいえ","ならでは","である以上は"],"answer":3,"explain":["【近义混同】「〜どころか」表示「非但…反而」，与本句不合。","【近义混同】「〜とはいえ」表示「虽说如此」的让步，与本句的义务不合。","【接续不合】「〜ならでは」表示「唯有…才有的」，与本句不合。","正解。「〜以上(は)」接「である以上」，表示「既然是…就（必须）」。"]},
]},
{"id":"b1-115","typeKey":"bun1","title":"模拟115 文語・残存表現の第五弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"近义辨析","q":"リーダー＿＿、自分の行動に責任を持つべきだ。","options":["たるもの","ならでは","たりとも","ともあれ"],"answer":0,"explain":["正解。「〜たるもの」表示「身为…（就该…）」。","【接续不合】「〜ならでは」表示「唯有…才有的」，与本句不合。","【接续不合】「〜たりとも」与最小量名词搭配，接续不合。","【近义混同】「〜はともあれ」表示「姑且不论」，与本句的训诫不合。"]},
{"label":"近义辨析","q":"彼は医者＿＿、患者の痛みを理解しない。","options":["たりとも","たるもの","まじき","べく"],"answer":1,"explain":["【接续不合】「〜たりとも」与最小量名词搭配，接续不合。","正解。「〜たるもの」表示「身为…（就该…）」，与「身为医生却…」的谴责契合。","【接续不合】「〜まじき」作连体修饰（あるまじき行為），与本句不合。","【接续不合】「〜べく」表示「为了…（文语目的）」，与本句不合。"]},
{"label":"近义辨析","q":"名人＿＿、ミスはあるものだ。","options":["において","にしても","といえども","ならでは"],"answer":2,"explain":["【接续不合】「〜において」表示「在…（场所·领域）」，与本句的让步不合。","【近义混同】「〜にしても」表示一般让步，语气平淡，无法强调「连名人也」。","正解。「〜といえども」表示「即便是…（也）」，与极端例搭配构成让步强调。","【接续不合】「〜ならでは」表示「唯有…才有的」，与本句不合。"]},
{"label":"近义辨析","q":"校門前は＿＿、車の進入を禁じる。","options":["がたい","まじき","ごとく","べからず"],"answer":3,"explain":["【接续不合】「〜がたい」接ます形表示「难以」，接续与本句不合。","【接续不合】「〜まじき」作连体修饰，不能直接结句表示禁止。","【接续不合】「〜ごとく」表示比况，与本句的禁止不合。","正解。「〜べからず」接辞书形，表示「不可…」的告示禁止。"]},
{"label":"近义辨析","q":"ご報告＿＿、お邪魔いたしました。","options":["かたがた","がてら","ながら","が早いか"],"answer":0,"explain":["正解。「〜かたがた」接名词，表示「兼作…（顺便）」，郑重的拜访寒暄场景正是其典型用法。","【文体不合】「〜がてら」语感轻松日常，与本句郑重的拜访语体不合。","【接续不合】「〜ながら」接名词表示「保持…原状」，与本句的兼作目的不合。","【接续不合】「〜が早いか」表示「刚…立刻」，与本句的目的兼作不合。"]},
]},
{"id":"b1-116","typeKey":"bun1","title":"模拟116 呼応の型（第三弾）","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"呼应制约","q":"＿＿現実とは思えない光景だった。","options":["たとえ","まるで","あまり","もし"],"answer":1,"explain":["【呼应冲突】「たとえ」与让步呼应，本句无比况。","正解。「まるで〜ようだ」表示「仿佛…一般」的比况呼应。","【呼应冲突】「あまり」与否定·程度呼应，本句无否定。","【呼应冲突】「もし」与条件句呼应，本句无比况。"]},
{"label":"呼应制约","q":"＿＿雨に降られても、式は決行する。","options":["あまり","まるで","たとえ","決して"],"answer":2,"explain":["【呼应冲突】「あまり」与程度·否定呼应，本句无。","【呼应冲突】「まるで」与比况呼应，本句无比况。","正解。「たとえ〜ても」表示「即便…也」，让步强调的固定呼应。","【呼应冲突】「決して」与否定呼应，本句的让步不合。"]},
{"label":"呼应制约","q":"値段が高いからといって、＿＿品質がいいわけではない。","options":["あまり","まるで","たとえ","必ずしも"],"answer":3,"explain":["【呼应冲突】「あまり」与程度呼应，本句无。","【呼应冲突】「まるで」与比况呼应，本句无比况。","【呼应冲突】「たとえ」与让步呼应，本句无条件让步。","正解。「必ずしも〜ない」表示「未必（部分否定）」，与「〜わけではない」契合。"]},
{"label":"呼应制约","q":"健康のため、＿＿タバコを吸わないことだ。","options":["決して","必ずしも","あまり","たとえ"],"answer":0,"explain":["正解。「決して〜ない」表示「决不（全面否定）」，与禁止的强语气契合。","【呼应冲突】「必ずしも〜ない」表示部分否定，与本句的全面禁止不合。","【呼应冲突】「あまり」与程度呼应，本句无。","【呼应冲突】「たとえ」与让步呼应，本句无。"]},
{"label":"呼应制约","q":"＿＿の疲労で、彼は倒れてしまった。","options":["まるで","あまり","たとえ","決して"],"answer":1,"explain":["【呼应冲突】「まるで」与比况呼应，本句无比况。","正解。「あまりの＋名词」表示「过分…（以致）」，「あまりの疲労」为惯用表达。","【呼应冲突】「たとえ」与让步呼应，本句无。","【呼应冲突】「決して」与否定呼应，本句无。"]},
]},
{"id":"b1-117","typeKey":"bun1","title":"模拟117 接続詞の型（第五弾）","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"接续词","q":"郊外は静かだ。＿＿、交通の便が悪い。","options":["つまり","しかし","一方で","そのため"],"answer":2,"explain":["【文脉断裂】「つまり」表示要约，与本句不合。","【文脉断裂】「しかし」表示逆接，本句为并列对照而非转折。","正解。「一方で」表示两事项的中性对照（安静与不便并观）。","【文脉断裂】「そのため」表示因果，与本句不合。"]},
{"label":"接续词","q":"＿＿、彼の方法は速い。しかし、精度では劣る。","options":["そもそも","もっとも","むしろ","たしかに"],"answer":3,"explain":["【文脉断裂】「そもそも」表示追根溯源，与本句不合。","【近义混同】「もっとも」表示附加保留，不能开启让步反驳。","【文脉断裂】「むしろ」表示「倒不如说」，与本句的让步不合。","正解。「たしかに」表示「诚然（先让步）」，与后句「しかし」构成让步反驳的固定节奏。"]},
{"label":"接续词","q":"入場は無料である。＿＿、別途飲食代がかかる。","options":["ただし","しかし","つまり","ところが"],"answer":0,"explain":["正解。「ただし」表示附加限制（但书）。","【近义混同】「しかし」表示全面转折，与本句的例外补充不合。","【文脉断裂】「つまり」表示要约，与本句不合。","【文脉断裂】「ところが」表示意外逆接，与本句的但书不合。"]},
{"label":"接续词","q":"彼は必ず来ると言っていた。＿＿、来なかった。","options":["すると","ところが","つまり","そのため"],"answer":1,"explain":["【文脉断裂】「すると」表示承接，与本句的违背预期不合。","正解。「ところが」表示「可是（结果出乎意料）」。","【文脉断裂】「つまり」表示要约，与本句不合。","【文脉断裂】「そのため」表示因果，与本句不合。"]},
{"label":"接续词","q":"二十年住んでいる。＿＿、近所の名前を知らない。","options":["そこで","それでも","それにしては","つまり"],"answer":2,"explain":["【文脉断裂】「そこで」表示于是·转换话题，与本句不合。","【近义混同】「それでも」表示让步（即便如此），与本句的落差评价不合。","正解。「それにしては」表示「就…而言却（预期落差）」。","【文脉断裂】「つまり」表示要约，与本句不合。"]},
]},
{"id":"b1-118","typeKey":"bun1","title":"模拟118 文末・評価の第七弾","minutes":4,"source":"本站原创模拟（非真题）","questions":[
{"label":"文末表现","q":"相手の立場に立って考えるのが、本当の思いやり＿＿。","options":["といったらない","というものではない","というところだ","というものだ"],"answer":3,"explain":["【近义混同】「〜といったらない」表示「难以形容」的感叹，与本句的断言不合。","【近义混同】「〜というものではない」表示「并非…就行」，方向相反。","【近义混同】「〜というところだ」表示「大概也就…的程度」，与本句相反。","正解。「〜というものだ」表示「这才真是…」的本质断言。"]},
{"label":"文末表现","q":"頑張ったのだから、結果が出ないはず＿＿。","options":["がない","ではない","にはいかない","だ"],"answer":0,"explain":["正解。「〜わけがない」表示「不可能（有充分理由的否定）」。","【近义混同】「〜わけではない」表示「并非…（部分否定）」，与本句的强否定不合。","【近义混同】「〜わけにはいかない」表示「碍于情理不能」，与本句不合。","【接续不合】「〜はずだ」接续不合（「出ないはずだ」为可能，但本句的「わけ」呼应更强）。"]},
{"label":"文末表现","q":"彼の演奏には聴衆を惹きつける＿＿。","options":["ものだ","ものがある","わけだ","というものだ"],"answer":1,"explain":["【近义混同】「〜ものだ」表示感慨·本性·忠告，与本句的「具有特质」不合。","正解。「〜ものがある」表示「确有…之处（由衷感叹）」。","【近义混同】「〜わけだ」表示「难怪（归结）」，与本句不合。","【近义混同】「〜というものだ」表示「这才真是」的断言，与本句不合。"]},
{"label":"近义辨析","q":"バスに乗り遅れて、危なく遅刻する＿＿。","options":["ところを","ところに","ところだった","ところで"],"answer":2,"explain":["【近义混同】「〜ところを」表示「正当…之际（致谢·免于）」，与本句不合。","【近义混同】「〜ところに」表示「正当…时（外部事件）」，与本句的未遂不合。","正解。「〜ところだった」接辞书形，表示「差点就…」。","【近义混同】「〜ところで」接た形表示「即使…也」，与本句不合。"]},
{"label":"文末表现","q":"彼が犯人である＿＿。勤務中ずっとここにいたのだから。","options":["ものだ","わけではない","わけにはいかない","わけがない"],"answer":3,"explain":["【近义混同】「〜ものだ」表示感慨·本性·忠告，与本句不合。","【近义混同】「〜わけではない」表示「并非…（部分否定）」，与本句的强否定不合。","【近义混同】「〜わけにはいかない」表示「碍于情理不能」，与本句不合。","正解。「〜わけがない」表示「不可能（有充分理由的否定）」。"]},
]},
);
